import React, { useState, useEffect } from 'react';
import api from '../utils/api';
import ConfirmDialog from '../components/ConfirmDialog';
import MessageBanner from '../components/MessageBanner';
import '../styles/AdminSecuritySettings.css';

export default function AdminSecuritySettings() {
  const [twoFAEnabled, setTwoFAEnabled] = useState(false);
  const [loginHistory, setLoginHistory] = useState([]);
  const [backupCodes, setBackupCodes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [tab, setTab] = useState('overview'); // overview, 2fa, history
  const [showBackupCodes, setShowBackupCodes] = useState(false);
  const [twoFAModal, setTwoFAModal] = useState(null); // null, 'enable', 'disable'
  const [confirm, setConfirm] = useState({ open: false, title: '', message: '', onConfirm: null });

  useEffect(() => {
    fetchSecuritySettings();
  }, []);

  const fetchSecuritySettings = async () => {
    setLoading(true);
    setError('');

    try {
      const response = await api.get('/security/settings');
      setTwoFAEnabled(response.data.twoFAEnabled);
      setBackupCodes(response.data.backupCodes || []);
    } catch (err) {
      setError('Failed to load security settings');
    }

    try {
      const historyResponse = await api.get('/security/login-history', { params: { limit: 10 } });
      setLoginHistory(historyResponse.data.logins);
    } catch (err) {
      console.error('Failed to load login history:', err);
    }

    setLoading(false);
  };

  const handleDisable2FA = () => {
    setConfirm({
      open: true,
      title: 'Disable Two-Factor Authentication',
      message: '⚠️ Disabling 2FA will reduce your account security. Are you sure?',
      onConfirm: async () => {
        setConfirm({ open: false });
        try {
          await api.post('/security/2fa/disable');
          setTwoFAEnabled(false);
          setSuccess('✅ Two-Factor Authentication disabled');
          setTwoFAModal(null);
          setTimeout(() => setSuccess(''), 3000);
        } catch (err) {
          setError(err.response?.data?.error || 'Failed to disable 2FA');
        }
      },
    });
  };

  const handleRegenerateCodes = () => {
    setConfirm({
      open: true,
      title: 'Regenerate Backup Codes',
      message: 'Generate new backup codes? Old codes will no longer work.',
      onConfirm: async () => {
        setConfirm({ open: false });
        try {
          const response = await api.post('/security/2fa/regenerate-backup-codes');
          setBackupCodes(response.data.backupCodes);
          setSuccess('✅ New backup codes generated');
          setTimeout(() => setSuccess(''), 3000);
        } catch (err) {
          setError(err.response?.data?.error || 'Failed to regenerate backup codes');
        }
      },
    });
  };

  const formatDate = (date) => {
    return new Date(date).toLocaleString();
  };

  const getLoginIcon = (method) => {
    const icons = {
      password: '🔐',
      '2fa': '🔐🔑',
      session_restored: '🔓',
    };
    return icons[method] || '•';
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
    setSuccess('✓ Copied to clipboard');
    setTimeout(() => setSuccess(''), 2500);
  };

  if (loading) {
    return <div className="settings-loading">⏳ Loading security settings...</div>;
  }

  return (
    <div className="admin-security-settings">
      <div className="settings-header">
        <h1>🔐 Security Settings</h1>
        <p>Manage your admin account security preferences</p>
      </div>

      {error && (
        <MessageBanner
          type="error"
          title="Security error"
          message={error}
          onClose={() => setError('')}
        />
      )}
      {success && (
        <MessageBanner
          type="success"
          title="Success"
          message={success}
          onClose={() => setSuccess('')}
        />
      )}

      <ConfirmDialog
        open={confirm.open}
        title={confirm.title}
        message={confirm.message}
        onConfirm={confirm.onConfirm}
        onCancel={() => setConfirm({ open: false })}
      />

      {/* Tab Navigation */}
      <div className="settings-tabs">
        <button
          className={`tab-btn ${tab === 'overview' ? 'active' : ''}`}
          onClick={() => setTab('overview')}
        >
          📋 Overview
        </button>
        <button
          className={`tab-btn ${tab === '2fa' ? 'active' : ''}`}
          onClick={() => setTab('2fa')}
        >
          🔐 Two-Factor Auth
        </button>
        <button
          className={`tab-btn ${tab === 'history' ? 'active' : ''}`}
          onClick={() => setTab('history')}
        >
          📜 Login History
        </button>
      </div>

      {/* Overview Tab */}
      {tab === 'overview' && (
        <div className="settings-content">
          <div className="settings-card">
            <h2>Security Status</h2>
            <div className="status-grid">
              <div className="status-item">
                <div className="status-label">Two-Factor Authentication</div>
                <div className={`status-value ${twoFAEnabled ? 'enabled' : 'disabled'}`}>
                  {twoFAEnabled ? '✓ Enabled' : '✗ Disabled'}
                </div>
              </div>
              <div className="status-item">
                <div className="status-label">Password Expiration</div>
                <div className="status-value active">90 days</div>
              </div>
              <div className="status-item">
                <div className="status-label">Session Timeout</div>
                <div className="status-value active">30 minutes</div>
              </div>
              <div className="status-item">
                <div className="status-label">Login Lockout</div>
                <div className="status-value active">5 attempts</div>
              </div>
            </div>
          </div>

          <div className="settings-card">
            <h2>Security Recommendations</h2>
            <div className="recommendations">
              {!twoFAEnabled && (
                <div className="recommendation critical">
                  <span className="icon">⚠️</span>
                  <div className="recommendation-content">
                    <h4>Enable Two-Factor Authentication</h4>
                    <p>2FA adds an extra layer of security to your admin account.</p>
                    <button
                      className="btn btn-primary"
                      onClick={() => setTwoFAModal('enable')}
                    >
                      Enable 2FA
                    </button>
                  </div>
                </div>
              )}
              <div className="recommendation info">
                <span className="icon">💡</span>
                <div className="recommendation-content">
                  <h4>Review Your Login Activity</h4>
                  <p>Regularly check your login history for any suspicious activity.</p>
                </div>
              </div>
              <div className="recommendation info">
                <span className="icon">💡</span>
                <div className="recommendation-content">
                  <h4>Use a Strong, Unique Password</h4>
                  <p>Avoid reusing passwords across different services.</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 2FA Tab */}
      {tab === '2fa' && (
        <div className="settings-content">
          <div className="settings-card">
            <h2>Two-Factor Authentication</h2>
            <div className="two-fa-status">
              <div className="status-indicator">
                <div className={`indicator ${twoFAEnabled ? 'active' : 'inactive'}`}></div>
                <span>{twoFAEnabled ? 'Enabled' : 'Disabled'}</span>
              </div>
              <p className="status-description">
                {twoFAEnabled
                  ? 'Your account is protected with two-factor authentication. You will need to enter a code from your authenticator app when logging in.'
                  : 'Enable 2FA to require a verification code when logging in.'}
              </p>
            </div>

            <div className="two-fa-actions">
              {twoFAEnabled ? (
                <>
                  <button
                    className="btn btn-secondary"
                    onClick={() => setShowBackupCodes(!showBackupCodes)}
                  >
                    🔑 {showBackupCodes ? 'Hide' : 'View'} Backup Codes
                  </button>
                  <button
                    className="btn btn-warning"
                    onClick={handleRegenerateCodes}
                  >
                    🔄 Regenerate Backup Codes
                  </button>
                  <button
                    className="btn btn-danger"
                    onClick={() => setTwoFAModal('disable')}
                  >
                    ✗ Disable 2FA
                  </button>
                </>
              ) : (
                <button
                  className="btn btn-primary"
                  onClick={() => setTwoFAModal('enable')}
                >
                  🔐 Enable 2FA
                </button>
              )}
            </div>

            {/* Backup Codes */}
            {showBackupCodes && backupCodes.length > 0 && (
              <div className="backup-codes-section">
                <h3>Backup Codes</h3>
                <p className="backup-note">
                  Keep these codes in a safe place. You can use each code once to login if you lose access to your authenticator app.
                </p>
                <div className="backup-codes-list">
                  {backupCodes.map((code, index) => (
                    <div key={index} className="backup-code-item">
                      <code>{code}</code>
                      <button
                        className="copy-btn-small"
                        onClick={() => copyToClipboard(code)}
                        title="Copy code"
                      >
                        📋
                      </button>
                    </div>
                  ))}
                </div>
                <button
                  className="btn btn-secondary"
                  onClick={() => {
                    const text = backupCodes.join('\n');
                    const element = document.createElement('a');
                    element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(text));
                    element.setAttribute('download', 'backup-codes.txt');
                    element.style.display = 'none';
                    document.body.appendChild(element);
                    element.click();
                    document.body.removeChild(element);
                  }}
                >
                  💾 Download Codes
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Login History Tab */}
      {tab === 'history' && (
        <div className="settings-content">
          <div className="settings-card">
            <h2>Login History</h2>
            <p className="history-info">Showing your last 10 login attempts</p>

            {loginHistory.length === 0 ? (
              <p className="no-data">No login history available</p>
            ) : (
              <div className="login-history-list">
                {loginHistory.map((login, index) => (
                  <div key={index} className={`login-item ${login.successful ? 'success' : 'failed'}`}>
                    <div className="login-icon">{getLoginIcon(login.method)}</div>
                    <div className="login-info">
                      <div className="login-method">
                        {login.successful ? '✓' : '✗'} {login.method.toUpperCase()}
                      </div>
                      <p>{login.browser} on {login.os}</p>
                      <p className="ip">🌐 {login.ipAddress}</p>
                      <p className="timestamp">📅 {formatDate(login.loginTime)}</p>
                    </div>
                    {login.notes && (
                      <div className="login-notes">
                        {login.notes}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {/* 2FA Modal */}
      {twoFAModal && (
        <div className="modal-overlay">
          <div className="modal-dialog">
            <div className="modal-header">
              <h2>
                {twoFAModal === 'enable' ? '🔐 Enable Two-Factor Authentication' : '⚠️ Disable 2FA?'}
              </h2>
              <button
                className="modal-close"
                onClick={() => setTwoFAModal(null)}
              >
                ✕
              </button>
            </div>

            <div className="modal-body">
              {twoFAModal === 'enable' && (
                <div>
                  <p>To enable 2FA, you will need to:</p>
                  <ol>
                    <li>Download an authenticator app (Google Authenticator, Microsoft Authenticator, Authy, etc.)</li>
                    <li>Scan a QR code with your app</li>
                    <li>Verify your setup with a test code</li>
                    <li>Save your backup codes in a safe place</li>
                  </ol>
                </div>
              )}

              {twoFAModal === 'disable' && (
                <div>
                  <p className="warning">
                    ⚠️ Disabling 2FA will reduce the security of your admin account. We strongly recommend keeping it enabled.
                  </p>
                  <p>Are you sure you want to disable two-factor authentication?</p>
                </div>
              )}
            </div>

            <div className="modal-footer">
              <button
                className="btn btn-secondary"
                onClick={() => setTwoFAModal(null)}
              >
                Cancel
              </button>
              {twoFAModal === 'enable' && (
                <button
                  className="btn btn-primary"
                  onClick={() => {
                    window.location.href = '/admin/security/2fa-setup';
                  }}
                >
                  Continue →
                </button>
              )}
              {twoFAModal === 'disable' && (
                <button
                  className="btn btn-danger"
                  onClick={handleDisable2FA}
                >
                  Disable 2FA
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import api from '../utils/api';
import '../styles/AnalyticsDashboard.css';

export default function AnalyticsDashboard({ classId }) {
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState('weekly');
  const [selectedMetric, setSelectedMetric] = useState('revenue');

  useEffect(() => {
    fetchAnalytics();
  }, [classId, period]);

  const fetchAnalytics = async () => {
    try {
      const response = await api.get(`/analytics/class/${classId}?period=${period}`);
      setAnalytics(response.data);
    } catch (error) {
      console.error('Failed to fetch analytics:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="loading">Loading analytics...</div>;
  }

  if (!analytics) {
    return <div className="error">No analytics data available</div>;
  }

  return (
    <div className="analytics-dashboard">
      <div className="analytics-header">
        <h2>Class Analytics</h2>
        <select value={period} onChange={(e) => setPeriod(e.target.value)} className="period-select">
          <option value="daily">Daily</option>
          <option value="weekly">Weekly</option>
          <option value="monthly">Monthly</option>
          <option value="yearly">Yearly</option>
        </select>
      </div>

      <div className="metrics-grid">
        <div className="metric-card">
          <div className="metric-value">{analytics.totalEnrollments}</div>
          <div className="metric-label">Total Enrollments</div>
        </div>
        <div className="metric-card">
          <div className="metric-value">${analytics.totalRevenue}</div>
          <div className="metric-label">Total Revenue</div>
        </div>
        <div className="metric-card">
          <div className="metric-value">{analytics.avgRating?.toFixed(1) || 'N/A'}</div>
          <div className="metric-label">Average Rating</div>
        </div>
        <div className="metric-card">
          <div className="metric-value">{analytics.completionRate || 0}%</div>
          <div className="metric-label">Completion Rate</div>
        </div>
      </div>

      <div className="charts-container">
        <div className="chart">
          <h3>Revenue Trend</h3>
          <div className="chart-placeholder">
            {analytics.revenueData && (
              <div className="simple-chart">
                {analytics.revenueData.map((point, idx) => (
                  <div
                    key={idx}
                    className="chart-bar"
                    style={{ height: `${(point.amount / Math.max(...analytics.revenueData.map(p => p.amount))) * 200}px` }}
                    title={`${point.date}: $${point.amount}`}
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="chart">
          <h3>Enrollment Trend</h3>
          <div className="chart-placeholder">
            {analytics.enrollmentData && (
              <div className="simple-chart">
                {analytics.enrollmentData.map((point, idx) => (
                  <div
                    key={idx}
                    className="chart-bar enrollment"
                    style={{ height: `${(point.count / Math.max(...analytics.enrollmentData.map(p => p.count))) * 200}px` }}
                    title={`${point.date}: ${point.count} students`}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="engagement-section">
        <h3>Engagement Metrics</h3>
        <div className="engagement-metrics">
          <div className="engagement-item">
            <span className="label">Avg. Session Duration:</span>
            <span className="value">{analytics.avgSessionDuration} min</span>
          </div>
          <div className="engagement-item">
            <span className="label">Attendance Rate:</span>
            <span className="value">{analytics.attendanceRate}%</span>
          </div>
          <div className="engagement-item">
            <span className="label">Chat Activity:</span>
            <span className="value">{analytics.totalMessages} messages</span>
          </div>
          <div className="engagement-item">
            <span className="label">Retention Rate:</span>
            <span className="value">{analytics.retentionRate}%</span>
          </div>
        </div>
      </div>

      <div className="recommendations-section">
        <h3>AI Recommendations</h3>
        <div className="recommendations-list">
          {analytics.recommendations && analytics.recommendations.length > 0 ? (
            analytics.recommendations.map((rec, idx) => (
              <div key={idx} className="recommendation-item">
                <span className="recommendation-icon">💡</span>
                <p>{rec}</p>
              </div>
            ))
          ) : (
            <p>No recommendations at this time</p>
          )}
        </div>
      </div>

      <button className="btn btn-primary export-btn">📥 Export Report</button>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAdmin } from '../context/AdminContext';

const AuditLogViewer = ({ logs: initialLogs }) => {
  const { fetchAuditLogs, exportAuditLogsPhase5G, loading } = useAdmin();
  const [logs, setLogs] = useState(initialLogs?.logs || []);
  const [filteredLogs, setFilteredLogs] = useState(logs);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(50);
  
  // Filters
  const [actionFilter, setActionFilter] = useState('');
  const [adminFilter, setAdminFilter] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [statusFilter, setStatusFilter] = useState('');

  // Get unique values for filters
  const uniqueActions = [...new Set(logs.map(l => l.action))];
  const uniqueAdmins = [...new Set(logs.map(l => l.adminEmail))];
  const uniqueStatuses = [...new Set(logs.map(l => l.status))];

  // Apply filters
  useEffect(() => {
    let filtered = logs;

    if (actionFilter) {
      filtered = filtered.filter(l => l.action === actionFilter);
    }

    if (adminFilter) {
      filtered = filtered.filter(l => l.adminEmail === adminFilter);
    }

    if (statusFilter) {
      filtered = filtered.filter(l => l.status === statusFilter);
    }

    if (dateRange.start) {
      const startDate = new Date(dateRange.start);
      filtered = filtered.filter(l => new Date(l.createdAt) >= startDate);
    }

    if (dateRange.end) {
      const endDate = new Date(dateRange.end);
      endDate.setHours(23, 59, 59);
      filtered = filtered.filter(l => new Date(l.createdAt) <= endDate);
    }

    setFilteredLogs(filtered);
    setCurrentPage(1);
  }, [logs, actionFilter, adminFilter, dateRange, statusFilter]);

  // Pagination
  const totalPages = Math.ceil(filteredLogs.length / pageSize);
  const paginatedLogs = filteredLogs.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );

  const handleLoadMore = async () => {
    const nextPage = currentPage + 1;
    const data = await fetchAuditLogs(nextPage, 50);
    if (data?.logs) {
      setLogs([...logs, ...data.logs]);
    }
  };

  const handleExport = async () => {
    const filters = {
      action: actionFilter,
      adminEmail: adminFilter,
      status: statusFilter,
      startDate: dateRange.start,
      endDate: dateRange.end
    };
    await exportAuditLogsPhase5G(filters);
  };

  const handleClearFilters = () => {
    setActionFilter('');
    setAdminFilter('');
    setStatusFilter('');
    setDateRange({ start: '', end: '' });
  };

  const getActionIcon = (action) => {
    const icons = {
      'host_approved': '✅',
      'host_rejected': '❌',
      'host_suspended': '🔒',
      'content_rejected': '🚫',
      'content_approved': '✓',
      'user_suspended': '🔘',
      'commission_updated': '💰',
      'feature_toggled': '🚩',
      'template_updated': '📧',
    };
    return icons[action] || '📝';
  };

  const getStatusBadgeClass = (status) => {
    return `badge badge-${status.toLowerCase()}`;
  };

  return (
    <div className="audit-log-viewer">
      <h2>Audit Logs</h2>
      <p className="card-description">
        Track all administrative actions performed on the platform for compliance and security.
      </p>

      <div className="filters-section">
        <h3>Filters</h3>

        <div className="filter-grid">
          <div className="filter-group">
            <label>Action</label>
            <select
              value={actionFilter}
              onChange={(e) => setActionFilter(e.target.value)}
              disabled={loading}
            >
              <option value="">All Actions</option>
              {uniqueActions.map(action => (
                <option key={action} value={action}>
                  {action}
                </option>
              ))}
            </select>
          </div>

          <div className="filter-group">
            <label>Admin</label>
            <select
              value={adminFilter}
              onChange={(e) => setAdminFilter(e.target.value)}
              disabled={loading}
            >
              <option value="">All Admins</option>
              {uniqueAdmins.map(admin => (
                <option key={admin} value={admin}>
                  {admin}
                </option>
              ))}
            </select>
          </div>

          <div className="filter-group">
            <label>Status</label>
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              disabled={loading}
            >
              <option value="">All Statuses</option>
              {uniqueStatuses.map(status => (
                <option key={status} value={status}>
                  {status}
                </option>
              ))}
            </select>
          </div>

          <div className="filter-group">
            <label>Start Date</label>
            <input
              type="date"
              value={dateRange.start}
              onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
              disabled={loading}
            />
          </div>

          <div className="filter-group">
            <label>End Date</label>
            <input
              type="date"
              value={dateRange.end}
              onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
              disabled={loading}
            />
          </div>

          <div className="filter-group filter-actions">
            <button
              onClick={handleClearFilters}
              className="btn btn-secondary btn-sm"
              disabled={loading}
            >
              Clear Filters
            </button>
            <button
              onClick={handleExport}
              className="btn btn-primary btn-sm"
              disabled={loading || filteredLogs.length === 0}
            >
              📥 Export CSV
            </button>
          </div>
        </div>

        <div className="filter-summary">
          Showing {paginatedLogs.length} of {filteredLogs.length} logs
        </div>
      </div>

      <div className="logs-table-container">
        <table className="logs-table">
          <thead>
            <tr>
              <th>Timestamp</th>
              <th>Admin</th>
              <th>Action</th>
              <th>Target</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {paginatedLogs.length > 0 ? (
              paginatedLogs.map((log, index) => (
                <tr key={index} className={`log-row status-${log.status}`}>
                  <td className="timestamp">
                    {new Date(log.createdAt).toLocaleString()}
                  </td>
                  <td className="admin">
                    {log.adminEmail}
                  </td>
                  <td className="action">
                    <span className="action-icon">{getActionIcon(log.action)}</span>
                    {log.action}
                  </td>
                  <td className="target">
                    <div className="target-info">
                      <span className="target-type">{log.targetType}</span>
                      <span className="target-id">{log.targetId}</span>
                    </div>
                  </td>
                  <td>
                    <span className={getStatusBadgeClass(log.status)}>
                      {log.status}
                    </span>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="5" className="empty-state">
                  No logs found matching the selected filters
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && currentPage < totalPages && (
        <div className="pagination">
          <button
            onClick={handleLoadMore}
            className="btn btn-primary"
            disabled={loading}
          >
            Load More ({currentPage}/{totalPages})
          </button>
        </div>
      )}

      <div className="log-info">
        <h4>💡 Audit Log Information</h4>
        <ul>
          <li><strong>Timestamp:</strong> When the action was performed (UTC)</li>
          <li><strong>Admin:</strong> Email of the administrator who performed the action</li>
          <li><strong>Action:</strong> Type of action (approve, reject, suspend, etc.)</li>
          <li><strong>Target:</strong> Resource that was affected (User, Class, Host, etc.)</li>
          <li><strong>Status:</strong> Result of the action (success, error, pending)</li>
        </ul>
        <p className="info-note">
          All audit logs are retained for 1 year for compliance purposes. Export data for long-term archival.
        </p>
      </div>
    </div>
  );
};

export default AuditLogViewer;

import { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
