﻿import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../utils/api';
import './BulkEmail.css';

const BulkEmail = () => {
  const { user } = useAuth();
  const [emailType, setEmailType] = useState('all');
  const [classId, setClassId] = useState('');
  const [subject, setSubject] = useState('');
  const [content, setContent] = useState('');
  const [sending, setSending] = useState(false);
  const [message, setMessage] = useState('');
  const [stats, setStats] = useState(null);
  const [classes, setClasses] = useState([]);
  const [loadingStats, setLoadingStats] = useState(false);

  useEffect(() => {
    if (user?.isHost) {
      fetchClasses();
      fetchStats();
    }
  }, [user]);

  const fetchClasses = async () => {
    try {
      const response = await api.get('/classes/my-classes');
      setClasses(response.data);
    } catch (error) {
      console.error('Error fetching classes:', error);
    }
  };

  const fetchStats = async () => {
    setLoadingStats(true);
    try {
      const response = await api.get('/admin/email-stats');
      setStats(response.data);
    } catch (error) {
      console.error('Error fetching email stats:', error);
    } finally {
      setLoadingStats(false);
    }
  };

  const handleSendEmail = async () => {
    if (!subject.trim() || !content.trim()) {
      setMessage('Please fill in both subject and content');
      return;
    }

    setSending(true);
    setMessage('');

    try {
      let endpoint = '/admin/bulk-email/all';
      let payload = {
        subject: subject.trim(),
        content: content.trim(),
        userType: emailType,
      };

      if (emailType === 'class' && classId) {
        endpoint = `/admin/bulk-email/class/${classId}`;
        payload = {
          subject: subject.trim(),
          content: content.trim(),
        };
      }

      const response = await api.post(endpoint, payload);

      setMessage(`Email sent successfully! Sent: ${response.data.results.sent}, Failed: ${response.data.results.failed}`);
      setSubject('');
      setContent('');
      fetchStats(); // Refresh stats
    } catch (error) {
      console.error('Error sending bulk email:', error);
      setMessage('Failed to send email. Please try again.');
    } finally {
      setSending(false);
    }
  };

  const handleTestEmail = async () => {
    if (!subject.trim() || !content.trim()) {
      setMessage('Please fill in both subject and content');
      return;
    }

    if (!user?.email) {
      setMessage('No email address available for testing');
      return;
    }

    setSending(true);
    setMessage('');

    try {
      await api.post('/admin/test-email', {
        email: user.email,
        subject: subject.trim(),
        content: content.trim(),
      });

      setMessage('Test email sent successfully!');
    } catch (error) {
      console.error('Error sending test email:', error);
      setMessage('Failed to send test email. Please try again.');
    } finally {
      setSending(false);
    }
  };

  if (!user?.isHost) {
    return (
      <div className="bulk-email-access-denied">
        <h2>Access Denied</h2>
        <p>You need to be a host to access bulk email functionality.</p>
      </div>
    );
  }

  return (
    <div className="bulk-email">
      <h2>Bulk Email Management</h2>

      {stats && (
        <div className="email-stats">
          <h3>Email Statistics</h3>
          <div className="stats-grid">
            <div className="stat-item">
              <span className="stat-label">Total Users:</span>
              <span className="stat-value">{stats.totalUsers}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Verified Emails:</span>
              <span className="stat-value">{stats.verifiedUsers} ({stats.verificationRate}%)</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Marketing Opt-ins:</span>
              <span className="stat-value">{stats.marketingOptIns} ({stats.marketingOptInRate}%)</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Session Reminders:</span>
              <span className="stat-value">{stats.sessionReminders}</span>
            </div>
            <div className="stat-item">
              <span className="stat-label">Expiry Warnings:</span>
              <span className="stat-value">{stats.expiryWarnings}</span>
            </div>
          </div>
        </div>
      )}

      <div className="bulk-email-form">
        <h3>Send Bulk Email</h3>

        {message && (
          <div className={`bulk-email-message ${message.includes('successfully') ? 'success' : 'error'}`}>
            {message}
          </div>
        )}

        <div className="form-group">
          <label>Email Type:</label>
          <select
            value={emailType}
            onChange={(e) => setEmailType(e.target.value)}
          >
            <option value="all">All Users</option>
            <option value="students">Students Only</option>
            <option value="hosts">Hosts Only</option>
            <option value="class">Specific Class Subscribers</option>
          </select>
        </div>

        {emailType === 'class' && (
          <div className="form-group">
            <label>Select Class:</label>
            <select
              value={classId}
              onChange={(e) => setClassId(e.target.value)}
              required
            >
              <option value="">Choose a class...</option>
              {classes.map(cls => (
                <option key={cls._id} value={cls._id}>
                  {cls.title}
                </option>
              ))}
            </select>
          </div>
        )}

        <div className="form-group">
          <label>Subject:</label>
          <input
            type="text"
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder="Email subject line"
            required
          />
        </div>

        <div className="form-group">
          <label>Content:</label>
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Email content (HTML supported)"
            rows={10}
            required
          />
        </div>

        <div className="form-actions">
          <button
            className="test-email-btn"
            onClick={handleTestEmail}
            disabled={sending}
          >
            Send Test Email
          </button>
          <button
            className="send-bulk-btn"
            onClick={handleSendEmail}
            disabled={sending || (emailType === 'class' && !classId)}
          >
            {sending ? 'Sending...' : 'Send Bulk Email'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default BulkEmail;

import React, { useState, useEffect } from 'react';
import api from '../utils/api';
import './BundleForm.css';

const BundleForm = ({ bundle = null, onSubmit, onCancel }) => {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    courseIds: [],
    pricing: {
      model: 'flat',
      amount: 0,
      totalOriginalPrice: 0,
      totalBundlePrice: 0,
    },
    category: 'Other',
    tags: '',
    thumbnailUrl: '',
    allowedStudents: 'any',
  });

  const [courses, setCourses] = useState([]);
  const [loadingCourses, setLoadingCourses] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  // Fetch available courses
  useEffect(() => {
    const fetchCourses = async () => {
      try {
        setLoadingCourses(true);
        const response = await api.get('/api/host/my-classes');
        setCourses(response.data || []);
      } catch (err) {
        setError('Failed to fetch courses');
      } finally {
        setLoadingCourses(false);
      }
    };

    fetchCourses();

    // Populate form if editing
    if (bundle) {
      setFormData({
        title: bundle.title || '',
        description: bundle.description || '',
        courseIds: bundle.courseIds || [],
        pricing: bundle.pricing || {
          model: 'flat',
          amount: 0,
          totalOriginalPrice: 0,
          totalBundlePrice: 0,
        },
        category: bundle.category || 'Other',
        tags: (bundle.tags || []).join(', '),
        thumbnailUrl: bundle.thumbnailUrl || '',
        allowedStudents: bundle.allowedStudents || 'any',
      });
    }
  }, [bundle]);

  // Calculate original price from selected courses
  useEffect(() => {
    const selectedCourses = courses.filter((c) =>
      formData.courseIds.includes(c._id)
    );
    const totalPrice = selectedCourses.reduce((sum, c) => sum + (c.price || 0), 0);

    setFormData((prev) => ({
      ...prev,
      pricing: {
        ...prev.pricing,
        totalOriginalPrice: totalPrice,
        totalBundlePrice: calculateBundlePrice(
          prev.pricing.model,
          prev.pricing.amount,
          totalPrice
        ),
      },
    }));
  }, [formData.courseIds, courses]);

  const calculateBundlePrice = (model, amount, originalPrice) => {
    if (model === 'percentage') {
      return originalPrice * (1 - amount / 100);
    } else {
      return amount;
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handlePricingChange = (e) => {
    const { name, value } = e.target;
    const model = name === 'model' ? value : formData.pricing.model;
    const amount = name === 'amount' ? parseFloat(value) : formData.pricing.amount;

    setFormData((prev) => ({
      ...prev,
      pricing: {
        ...prev.pricing,
        [name]: name === 'amount' ? amount : value,
        totalBundlePrice: calculateBundlePrice(
          model,
          amount,
          prev.pricing.totalOriginalPrice
        ),
      },
    }));
  };

  const handleCourseToggle = (courseId) => {
    setFormData((prev) => {
      const courseIds = prev.courseIds.includes(courseId)
        ? prev.courseIds.filter((id) => id !== courseId)
        : [...prev.courseIds, courseId];

      if (courseIds.length > 10) {
        setError('Bundle can contain maximum 10 courses');
        return prev;
      }

      return { ...prev, courseIds };
    });
    setError(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);

    // Validation
    if (!formData.title.trim()) {
      setError('Bundle title is required');
      return;
    }

    if (!formData.description.trim()) {
      setError('Bundle description is required');
      return;
    }

    if (formData.courseIds.length < 2) {
      setError('Bundle must contain at least 2 courses');
      return;
    }

    if (formData.courseIds.length > 10) {
      setError('Bundle can contain maximum 10 courses');
      return;
    }

    if (formData.pricing.model === 'flat' && formData.pricing.amount <= 0) {
      setError('Bundle price must be greater than 0');
      return;
    }

    if (formData.pricing.model === 'percentage' && formData.pricing.amount > 100) {
      setError('Discount percentage cannot exceed 100%');
      return;
    }

    try {
      setSaving(true);
      const submitData = {
        ...formData,
        tags: formData.tags
          .split(',')
          .map((tag) => tag.trim())
          .filter((tag) => tag.length > 0),
      };

      onSubmit(submitData);
    } catch (err) {
      setError(err.message || 'Failed to save bundle');
    } finally {
      setSaving(false);
    }
  };

  if (loadingCourses) {
    return <div className="bundle-form__loading">Loading courses...</div>;
  }

  if (courses.length === 0) {
    return (
      <div className="bundle-form__error">
        <p>You need to create at least 2 courses before creating a bundle.</p>
        <button onClick={onCancel}>Cancel</button>
      </div>
    );
  }

  return (
    <form className="bundle-form" onSubmit={handleSubmit}>
      <div className="bundle-form__header">
        <h2 className="bundle-form__title">
          {bundle ? 'Edit Bundle' : 'Create New Bundle'}
        </h2>
        <button
          type="button"
          className="bundle-form__close"
          onClick={onCancel}
          aria-label="Close form"
        >
          ✕
        </button>
      </div>

      {error && (
        <div className="bundle-form__error-message" role="alert">
          {error}
        </div>
      )}

      <div className="bundle-form__scroll">
        {/* Basic Info */}
        <fieldset className="bundle-form__section">
          <legend>Basic Information</legend>

          <div className="bundle-form__field">
            <label htmlFor="title" className="bundle-form__label">
              Bundle Title <span className="bundle-form__required">*</span>
            </label>
            <input
              id="title"
              type="text"
              name="title"
              className="bundle-form__input"
              value={formData.title}
              onChange={handleInputChange}
              placeholder="Enter bundle title (e.g., 'Complete Web Development')"
              maxLength={100}
              required
            />
            <span className="bundle-form__help">
              {formData.title.length}/100 characters
            </span>
          </div>

          <div className="bundle-form__field">
            <label htmlFor="description" className="bundle-form__label">
              Description <span className="bundle-form__required">*</span>
            </label>
            <textarea
              id="description"
              name="description"
              className="bundle-form__textarea"
              value={formData.description}
              onChange={handleInputChange}
              placeholder="Describe what students will learn from this bundle"
              maxLength={2000}
              rows={4}
              required
            />
            <span className="bundle-form__help">
              {formData.description.length}/2000 characters
            </span>
          </div>

          <div className="bundle-form__field">
            <label htmlFor="category" className="bundle-form__label">
              Category
            </label>
            <select
              id="category"
              name="category"
              className="bundle-form__select"
              value={formData.category}
              onChange={handleInputChange}
            >
              <option value="Technology">Technology</option>
              <option value="Business">Business</option>
              <option value="Design">Design</option>
              <option value="Art">Art</option>
              <option value="Music">Music</option>
              <option value="Language">Language</option>
              <option value="Health">Health</option>
              <option value="Other">Other</option>
            </select>
          </div>

          <div className="bundle-form__field">
            <label htmlFor="tags" className="bundle-form__label">
              Tags (comma-separated)
            </label>
            <input
              id="tags"
              type="text"
              name="tags"
              className="bundle-form__input"
              value={formData.tags}
              onChange={handleInputChange}
              placeholder="e.g., beginner, comprehensive, career-focused"
            />
          </div>
        </fieldset>

        {/* Courses Selection */}
        <fieldset className="bundle-form__section">
          <legend>
            Select Courses <span className="bundle-form__required">*</span>
            <span className="bundle-form__count">
              ({formData.courseIds.length}/10)
            </span>
          </legend>

          <div className="bundle-form__courses">
            {courses.map((course) => (
              <label key={course._id} className="bundle-form__course-item">
                <input
                  type="checkbox"
                  className="bundle-form__checkbox"
                  checked={formData.courseIds.includes(course._id)}
                  onChange={() => handleCourseToggle(course._id)}
                  disabled={
                    !formData.courseIds.includes(course._id) &&
                    formData.courseIds.length >= 10
                  }
                />
                <div className="bundle-form__course-info">
                  <span className="bundle-form__course-name">{course.title}</span>
                  <span className="bundle-form__course-price">
                    ${course.price?.toFixed(2) || '0.00'}
                  </span>
                </div>
              </label>
            ))}
          </div>
        </fieldset>

        {/* Pricing */}
        <fieldset className="bundle-form__section">
          <legend>Pricing <span className="bundle-form__required">*</span></legend>

          <div className="bundle-form__field">
            <label htmlFor="model" className="bundle-form__label">
              Pricing Model
            </label>
            <div className="bundle-form__radio-group">
              <label className="bundle-form__radio">
                <input
                  type="radio"
                  name="model"
                  value="flat"
                  checked={formData.pricing.model === 'flat'}
                  onChange={handlePricingChange}
                />
                Fixed Price
              </label>
              <label className="bundle-form__radio">
                <input
                  type="radio"
                  name="model"
                  value="percentage"
                  checked={formData.pricing.model === 'percentage'}
                  onChange={handlePricingChange}
                />
                Percentage Discount
              </label>
            </div>
          </div>

          <div className="bundle-form__field">
            <label htmlFor="amount" className="bundle-form__label">
              {formData.pricing.model === 'flat' ? 'Bundle Price ($)' : 'Discount (%)'}
              <span className="bundle-form__required">*</span>
            </label>
            <input
              id="amount"
              type="number"
              name="amount"
              className="bundle-form__input"
              value={formData.pricing.amount}
              onChange={handlePricingChange}
              min="0"
              max={formData.pricing.model === 'percentage' ? 100 : undefined}
              step="0.01"
              required
            />
          </div>

          <div className="bundle-form__pricing-summary">
            <div className="bundle-form__summary-item">
              <span>Original Price:</span>
              <span className="bundle-form__summary-value">
                ${formData.pricing.totalOriginalPrice.toFixed(2)}
              </span>
            </div>
            <div className="bundle-form__summary-item">
              <span>Bundle Price:</span>
              <span className="bundle-form__summary-value bundle-form__summary-value--highlight">
                ${formData.pricing.totalBundlePrice.toFixed(2)}
              </span>
            </div>
            <div className="bundle-form__summary-item">
              <span>Student Saves:</span>
              <span className="bundle-form__summary-value bundle-form__summary-value--savings">
                ${(
                  formData.pricing.totalOriginalPrice - formData.pricing.totalBundlePrice
                ).toFixed(2)}
              </span>
            </div>
          </div>
        </fieldset>

        {/* Settings */}
        <fieldset className="bundle-form__section">
          <legend>Settings</legend>

          <div className="bundle-form__field">
            <label htmlFor="allowedStudents" className="bundle-form__label">
              Who Can Enroll?
            </label>
            <select
              id="allowedStudents"
              name="allowedStudents"
              className="bundle-form__select"
              value={formData.allowedStudents}
              onChange={handleInputChange}
            >
              <option value="any">Any Student</option>
              <option value="new">New Students Only</option>
              <option value="existing">Existing Students Only</option>
            </select>
          </div>

          <div className="bundle-form__field">
            <label htmlFor="thumbnailUrl" className="bundle-form__label">
              Thumbnail URL
            </label>
            <input
              id="thumbnailUrl"
              type="url"
              name="thumbnailUrl"
              className="bundle-form__input"
              value={formData.thumbnailUrl}
              onChange={handleInputChange}
              placeholder="https://example.com/image.jpg"
            />
          </div>
        </fieldset>
      </div>

      {/* Actions */}
      <div className="bundle-form__footer">
        <button
          type="button"
          className="bundle-form__button bundle-form__button--cancel"
          onClick={onCancel}
          disabled={saving}
        >
          Cancel
        </button>
        <button
          type="submit"
          className="bundle-form__button bundle-form__button--submit"
          disabled={saving || formData.courseIds.length < 2}
        >
          {saving ? 'Saving...' : bundle ? 'Update Bundle' : 'Create Bundle'}
        </button>
      </div>
    </form>
  );
};

export default BundleForm;

import React, { useState, useEffect } from 'react';
import '../styles/CalendarView.css';

export default function CalendarView({ schedules = [], onSelectDate, onNavigateMonth, onEditSchedule }) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [viewMode, setViewMode] = useState('month'); // month, week, day
  
  // Color status mapping
  const getScheduleStatus = (schedule) => {
    const now = new Date();
    const start = new Date(schedule.scheduledStartTime);
    if (schedule.status === 'live' || (start <= now && schedule.status !== 'completed')) return 'live';
    if (schedule.status === 'completed') return 'completed';
    return 'scheduled';
  };

  const getDaysInMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const getSchedulesForDate = (date) => {
    return schedules.filter(schedule => {
      const scheduleDate = new Date(schedule.scheduledStartTime);
      return (
        scheduleDate.getDate() === date.getDate() &&
        scheduleDate.getMonth() === date.getMonth() &&
        scheduleDate.getFullYear() === date.getFullYear()
      );
    });
  };

  const handlePrevMonth = () => {
    const newDate = new Date(currentDate.getFullYear(), currentDate.getMonth() - 1);
    setCurrentDate(newDate);
    if (onNavigateMonth) onNavigateMonth(newDate);
  };

  const handleNextMonth = () => {
    const newDate = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1);
    setCurrentDate(newDate);
    if (onNavigateMonth) onNavigateMonth(newDate);
  };

  const handleToday = () => {
    setCurrentDate(new Date());
  };

  const renderMonthView = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayOfMonth(currentDate);
    const days = [];
    const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    // Add empty cells for days before month starts
    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="calendar-day empty"></div>);
    }

    // Add days of month
    for (let day = 1; day <= daysInMonth; day++) {
      const date = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
      const daySchedules = getSchedulesForDate(date);
      const isToday = 
        date.toDateString() === new Date().toDateString();

      days.push(
        <div 
          key={day} 
          className={`calendar-day ${isToday ? 'today' : ''} ${daySchedules.length > 0 ? 'has-schedules' : ''}`}
          onClick={() => onSelectDate && onSelectDate(date)}
        >
          <div className="day-number">{day}</div>
          <div className="schedules-preview">
            {daySchedules.slice(0, 2).map((schedule, idx) => {
              const status = getScheduleStatus(schedule);
              return (
                <div 
                  key={idx} 
                  className={`schedule-preview status-${status}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    if (onEditSchedule) onEditSchedule(schedule);
                  }}
                  title={schedule.title}
                >
                  {new Date(schedule.scheduledStartTime).toLocaleTimeString([], {
                    hour: '2-digit',
                    minute: '2-digit',
                  })}{' '}
                  {schedule.title.substring(0, 10)}
                </div>
              );
            })}
            {daySchedules.length > 2 && (
              <div className="more-schedules">+{daySchedules.length - 2} more</div>
            )}
          </div>
        </div>
      );
    }

    return (
      <div className="month-view">
        <div className="weekday-header">
          {weekdays.map(day => (
            <div key={day} className="weekday">{day}</div>
          ))}
        </div>
        <div className="calendar-grid">
          {days}
        </div>
      </div>
    );
  };

  return (
    <div className="calendar-view">
      <div className="calendar-header">
        <button onClick={handlePrevMonth} className="btn-nav">← Prev</button>
        <div className="calendar-title">
          {currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
        </div>
        <button onClick={handleNextMonth} className="btn-nav">Next →</button>
        <button onClick={handleToday} className="btn-today">Today</button>
      </div>

      <div className="view-mode-selector">
        <button 
          className={`btn-view ${viewMode === 'month' ? 'active' : ''}`}
          onClick={() => setViewMode('month')}
        >
          Month
        </button>
        <button 
          className={`btn-view ${viewMode === 'week' ? 'active' : ''}`}
          onClick={() => setViewMode('week')}
        >
          Week
        </button>
        <button 
          className={`btn-view ${viewMode === 'day' ? 'active' : ''}`}
          onClick={() => setViewMode('day')}
        >
          Day
        </button>
      </div>

      {viewMode === 'month' && renderMonthView()}
      
      <div className="legend">
        <div className="legend-item">
          <div className="legend-color scheduled"></div>
          <span>Scheduled</span>
        </div>
        <div className="legend-item">
          <div className="legend-color live"></div>
          <span>Live</span>
        </div>
        <div className="legend-item">
          <div className="legend-color completed"></div>
          <span>Completed</span>
        </div>
        <div className="legend-item">
          <div className="legend-color today"></div>
          <span>Today</span>
        </div>
      </div>
    </div>
  );
}

