import React, { useState } from 'react';
import api from '../utils/api';
import '../styles/ChangePassword.css';

export default function ChangePassword({ isExpired = false, onSuccess }) {
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [passwordStrength, setPasswordStrength] = useState(0);
  const [showCriteria, setShowCriteria] = useState(false);

  // Password strength validator
  const calculatePasswordStrength = (password) => {
    let strength = 0;
    if (password.length >= 8) strength += 25;
    if (password.length >= 12) strength += 10;
    if (/[a-z]/.test(password)) strength += 15;
    if (/[A-Z]/.test(password)) strength += 15;
    if (/\d/.test(password)) strength += 15;
    if (/[!@#$%^&*(),.?":{}|<>]/.test(password)) strength += 20;
    return Math.min(strength, 100);
  };

  const checkPasswordRequirements = (password) => {
    const requirements = {
      minLength: password.length >= 8,
      uppercase: /[A-Z]/.test(password),
      lowercase: /[a-z]/.test(password),
      number: /\d/.test(password),
      special: /[!@#$%^&*(),.?":{}|<>]/.test(password),
    };
    return requirements;
  };

  const handleNewPasswordChange = (e) => {
    const password = e.target.value;
    setNewPassword(password);
    const strength = calculatePasswordStrength(password);
    setPasswordStrength(strength);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    // Validation
    if (!isExpired && !currentPassword) {
      setError('Current password is required');
      setLoading(false);
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }

    if (passwordStrength < 50) {
      setError('Password is too weak. Please use a stronger password.');
      setLoading(false);
      return;
    }

    try {
      const response = await api.post('/security/password/change', {
        currentPassword: isExpired ? undefined : currentPassword,
        newPassword,
      });

      setSuccess('✅ Password changed successfully!');
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');

      setTimeout(() => {
        // Clear temporary token
        localStorage.removeItem('tempToken');
        
        if (isExpired) {
          // Redirect back to login for fresh authentication
          window.location.href = '/admin/login';
        } else if (onSuccess) {
          onSuccess();
        }
      }, 1500);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to change password');
    } finally {
      setLoading(false);
    }
  };

  const requirements = checkPasswordRequirements(newPassword);
  const allRequirementsMet = Object.values(requirements).every(v => v);

  return (
    <div className={`change-password-container ${isExpired ? 'expired' : ''}`}>
      <div className="change-password-box">
        <div className="password-header">
          <h1>{isExpired ? '🔄 Password Expired' : '🔐 Change Password'}</h1>
          <p>
            {isExpired
              ? 'Your admin password has expired. Please set a new one.'
              : 'Update your admin account password'}
          </p>
        </div>

        {error && <div className="password-error">{error}</div>}
        {success && <div className="password-success">{success}</div>}

        <form onSubmit={handleSubmit}>
          {/* Current Password */}
          {!isExpired && (
            <div className="form-group">
              <label htmlFor="currentPassword">Current Password</label>
              <input
                type="password"
                id="currentPassword"
                value={currentPassword}
                onChange={(e) => setCurrentPassword(e.target.value)}
                placeholder="Enter current password"
                disabled={loading}
                required
              />
            </div>
          )}

          {/* New Password */}
          <div className="form-group">
            <label htmlFor="newPassword">
              New Password
              {newPassword && (
                <span className="password-strength">
                  Strength: <span style={{ color: getStrengthColor(passwordStrength) }}>
                    {getStrengthText(passwordStrength)}
                  </span>
                </span>
              )}
            </label>
            <input
              type="password"
              id="newPassword"
              value={newPassword}
              onChange={handleNewPasswordChange}
              onFocus={() => setShowCriteria(true)}
              onBlur={() => setShowCriteria(false)}
              placeholder="Enter new password"
              disabled={loading}
              required
            />

            {/* Password Strength Bar */}
            {newPassword && (
              <div className="password-strength-bar">
                <div
                  className="strength-fill"
                  style={{
                    width: `${passwordStrength}%`,
                    backgroundColor: getStrengthColor(passwordStrength),
                  }}
                ></div>
              </div>
            )}

            {/* Password Requirements */}
            {showCriteria && newPassword && (
              <div className="password-criteria">
                <p className={requirements.minLength ? 'met' : 'unmet'}>
                  ✓ At least 8 characters
                </p>
                <p className={requirements.uppercase ? 'met' : 'unmet'}>
                  ✓ Uppercase letter (A-Z)
                </p>
                <p className={requirements.lowercase ? 'met' : 'unmet'}>
                  ✓ Lowercase letter (a-z)
                </p>
                <p className={requirements.number ? 'met' : 'unmet'}>
                  ✓ Number (0-9)
                </p>
                <p className={requirements.special ? 'met' : 'unmet'}>
                  ✓ Special character (!@#$%^&*...)
                </p>
              </div>
            )}
          </div>

          {/* Confirm Password */}
          <div className="form-group">
            <label htmlFor="confirmPassword">Confirm Password</label>
            <input
              type="password"
              id="confirmPassword"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              placeholder="Confirm new password"
              disabled={loading}
              required
            />
            {confirmPassword && newPassword !== confirmPassword && (
              <p className="mismatch-error">❌ Passwords do not match</p>
            )}
          </div>

          <button
            type="submit"
            className="change-password-btn"
            disabled={loading || !allRequirementsMet}
          >
            {loading ? '⏳ Changing password...' : '✓ Change Password'}
          </button>
        </form>

        {isExpired && (
          <div className="expiration-notice">
            <p>
              ⚠️ For security reasons, admin passwords expire every 90 days.
              Please change your password to continue using the admin dashboard.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

function getStrengthColor(strength) {
  if (strength < 30) return '#f44336';
  if (strength < 60) return '#ff9800';
  if (strength < 85) return '#ffc107';
  return '#4caf50';
}

function getStrengthText(strength) {
  if (strength < 30) return 'Weak';
  if (strength < 60) return 'Fair';
  if (strength < 85) return 'Good';
  return 'Strong';
}

import React from 'react';
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts';
import '../styles/DemographicsPanel.css';

export default function DemographicsPanel({ data }) {
  if (!data) {
    return (
      <div className="demographics-panel">
        <p className="chart-empty">Loading demographics...</p>
      </div>
    );
  }

  const browsers = data.browsers || {};
  const operatingSystems = data.operatingSystems || {};
  const deviceTypes = data.deviceTypes || {};

  // Format data for charts
  const browserData = Object.entries(browsers)
    .filter(([, count]) => count > 0)
    .map(([name, count]) => ({ name, value: count }));

  const osData = Object.entries(operatingSystems)
    .filter(([, count]) => count > 0)
    .map(([name, count]) => ({ name, value: count }));

  const deviceData = Object.entries(deviceTypes)
    .filter(([, count]) => count > 0)
    .map(([name, count]) => ({ name, value: count }));

  const COLORS_BROWSER = {
    Chrome: '#4285F4',
    Firefox: '#FF7139',
    Safari: '#555555',
    Edge: '#0078D4',
    Other: '#999999',
  };

  const COLORS_OS = {
    Windows: '#0078D4',
    MacOS: '#A2AAAD',
    Linux: '#FCC624',
    iOS: '#555555',
    Android: '#3DDC84',
  };

  const COLORS_DEVICE = {
    Desktop: '#3498db',
    Tablet: '#2ecc71',
    Mobile: '#e74c3c',
  };

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div className="custom-tooltip">
          <p className="tooltip-label">{payload[0].payload.name}</p>
          <p className="tooltip-value">{payload[0].payload.value} viewers</p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="demographics-panel">
      {/* Browser Distribution */}
      <div className="demographics-section">
        <div className="section-header">
          <h3>Browser Distribution</h3>
          <p>Which browsers viewers used</p>
        </div>
        {browserData.length > 0 ? (
          <div className="chart-container">
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={browserData}
                  cx="50%"
                  cy="50%"
                  outerRadius={100}
                  fill="#8884d8"
                  dataKey="value"
                  label={({ name, value }) => `${name}: ${value}`}
                >
                  {browserData.map((entry, index) => (
                    <Cell
                      key={`cell-${index}`}
                      fill={COLORS_BROWSER[entry.name] || '#999'}
                    />
                  ))}
                </Pie>
                <Tooltip content={<CustomTooltip />} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <p className="chart-empty">No browser data available</p>
        )}
      </div>

      {/* Operating System Distribution */}
      <div className="demographics-section">
        <div className="section-header">
          <h3>Operating System Distribution</h3>
          <p>Which operating systems viewers used</p>
        </div>
        {osData.length > 0 ? (
          <div className="chart-container">
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={osData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="value" fill="#3498db" radius={[8, 8, 0, 0]}>
                  {osData.map((entry, index) => (
                    <Cell
                      key={`cell-${index}`}
                      fill={COLORS_OS[entry.name] || '#999'}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <p className="chart-empty">No OS data available</p>
        )}
      </div>

      {/* Device Type Distribution */}
      <div className="demographics-section">
        <div className="section-header">
          <h3>Device Type Distribution</h3>
          <p>Desktop, Tablet, or Mobile viewers</p>
        </div>
        {deviceData.length > 0 ? (
          <div className="chart-container">
            <ResponsiveContainer width="100%" height={300}>
              <BarChart data={deviceData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="value" fill="#3498db" radius={[8, 8, 0, 0]}>
                  {deviceData.map((entry, index) => (
                    <Cell
                      key={`cell-${index}`}
                      fill={COLORS_DEVICE[entry.name] || '#999'}
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <p className="chart-empty">No device data available</p>
        )}
      </div>

      {/* Demographics Summary Table */}
      <div className="demographics-summary">
        <h3>Demographics Summary</h3>
        <div className="summary-tables">
          <div className="summary-table-wrapper">
            <h4>Browsers</h4>
            <table className="demographics-table">
              <tbody>
                {browserData.map((item, index) => (
                  <tr key={index}>
                    <td>{item.name}</td>
                    <td>{item.value} viewers</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="summary-table-wrapper">
            <h4>Operating Systems</h4>
            <table className="demographics-table">
              <tbody>
                {osData.map((item, index) => (
                  <tr key={index}>
                    <td>{item.name}</td>
                    <td>{item.value} viewers</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="summary-table-wrapper">
            <h4>Device Types</h4>
            <table className="demographics-table">
              <tbody>
                {deviceData.map((item, index) => (
                  <tr key={index}>
                    <td>{item.name}</td>
                    <td>{item.value} viewers</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

﻿import React, { useState, useEffect } from 'react';
import { api } from '../utils/api';
import '../styles/DynamicPricingManager.css';

export default function DynamicPricingManager({ bundleId }) {
  const [bundle, setBundle] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('analysis');
  const [analysis, setAnalysis] = useState(null);
  const [flashSaleForm, setFlashSaleForm] = useState({
    discountPercent: 20,
    durationHours: 24
  });
  const [seasonalForm, setSeasonalForm] = useState({
    seasons: [
      { name: 'Winter Sale', months: [11, 0, 1], multiplier: 0.9 },
      { name: 'Summer Promotion', months: [5, 6, 7], multiplier: 0.95 },
      { name: 'Back to School', months: [7, 8], multiplier: 0.85 }
    ]
  });
  const [abTestForm, setAbTestForm] = useState({
    durationDays: 7,
    variants: [
      { name: 'Control', discountType: 'percentage', discountValue: 0, trafficPercentage: 50 },
      { name: 'Discount 10%', discountType: 'percentage', discountValue: 10, trafficPercentage: 25 },
      { name: 'Discount 20%', discountType: 'percentage', discountValue: 20, trafficPercentage: 25 }
    ]
  });
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  useEffect(() => {
    if (bundleId) {
      loadBundleData();
    }
  }, [bundleId]);

  const loadBundleData = async () => {
    try {
      setLoading(true);
      const [bundleResponse, analysisResponse] = await Promise.all([
        api.get(`/bundles/${bundleId}`),
        api.get(`/bundles/${bundleId}/analyze-pricing`)
      ]);

      setBundle(bundleResponse.data);
      setAnalysis(analysisResponse.data);
    } catch (err) {
      console.error('Load bundle data error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleOptimizePricing = async () => {
    try {
      await api.post(`/bundles/${bundleId}/optimize-pricing`);
      setSuccess('Pricing optimized successfully!');
      setTimeout(() => setSuccess(null), 4000);
      loadBundleData();
    } catch (err) {
      setError('Failed to optimize pricing');
      setTimeout(() => setError(null), 4000);
      console.error('Optimize pricing error:', err);
    }
  };

  const handleCreateFlashSale = async (e) => {
    e.preventDefault();
    try {
      await api.post(`/bundles/${bundleId}/flash-sale`, flashSaleForm);
      setSuccess('Flash sale created successfully!');
      setTimeout(() => setSuccess(null), 4000);
      setFlashSaleForm({ discountPercent: 20, durationHours: 24 });
      loadBundleData();
    } catch (err) {
      setError('Failed to create flash sale');
      setTimeout(() => setError(null), 4000);
      console.error('Create flash sale error:', err);
    }
  };

  const handleSetSeasonalPricing = async (e) => {
    e.preventDefault();
    try {
      await api.post(`/bundles/${bundleId}/seasonal-pricing`, {
        seasonConfig: seasonalForm.seasons
      });
      setSuccess('Seasonal pricing set successfully!');
      setTimeout(() => setSuccess(null), 4000);
      loadBundleData();
    } catch (err) {
      setError('Failed to set seasonal pricing');
      setTimeout(() => setError(null), 4000);
      console.error('Set seasonal pricing error:', err);
    }
  };

  const handleCreateABTest = async (e) => {
    e.preventDefault();
    try {
      await api.post(`/bundles/${bundleId}/ab-test`, abTestForm);
      setSuccess('A/B test created successfully!');
      setTimeout(() => setSuccess(null), 4000);
      loadBundleData();
    } catch (err) {
      setError('Failed to create A/B test');
      setTimeout(() => setError(null), 4000);
      console.error('Create A/B test error:', err);
    }
  };

  const addABTestVariant = () => {
    setAbTestForm(prev => ({
      ...prev,
      variants: [...prev.variants, {
        name: `Variant ${prev.variants.length + 1}`,
        discountType: 'percentage',
        discountValue: 0,
        trafficPercentage: 0
      }]
    }));
  };

  const updateABTestVariant = (index, field, value) => {
    setAbTestForm(prev => ({
      ...prev,
      variants: prev.variants.map((variant, i) =>
        i === index ? { ...variant, [field]: value } : variant
      )
    }));
  };

  const removeABTestVariant = (index) => {
    setAbTestForm(prev => ({
      ...prev,
      variants: prev.variants.filter((_, i) => i !== index)
    }));
  };

  if (loading) {
    return <div className="dynamic-pricing-manager"><div className="loading">Loading pricing data...</div></div>;
  }

  if (!bundle) {
    return <div className="dynamic-pricing-manager"><div className="error">Bundle not found</div></div>;
  }

  return (
    <div className="dynamic-pricing-manager">
      <div className="pricing-header">
        <h2>Dynamic Pricing Manager</h2>
        <p>Optimize your bundle pricing with AI-powered recommendations</p>
      </div>

        {error && <div className="alert alert-error" style={{marginTop:12}}>{error}</div>}
        {success && <div className="alert alert-success" style={{marginTop:12}}>{success}</div>}

      <div className="pricing-tabs">
        <button
          className={`tab-btn ${activeTab === 'analysis' ? 'active' : ''}`}
          onClick={() => setActiveTab('analysis')}
        >
          Performance Analysis
        </button>
        <button
          className={`tab-btn ${activeTab === 'flash' ? 'active' : ''}`}
          onClick={() => setActiveTab('flash')}
        >
          Flash Sales
        </button>
        <button
