                         placeholder="Variant name"
                        value={variant.name}
                        onChange={(e) => updateABTestVariant(index, 'name', e.target.value)}
                        required
                      />
                      <button
                        type="button"
                        onClick={() => removeABTestVariant(index)}
                        className="remove-variant"
                        disabled={abTestForm.variants.length <= 2}
                      >
                        Ã—
                      </button>
                    </div>

                    <div className="variant-settings">
                      <select
                        value={variant.discountType}
                        onChange={(e) => updateABTestVariant(index, 'discountType', e.target.value)}
                      >
                        <option value="percentage">Percentage</option>
                        <option value="fixed">Fixed Amount</option>
                      </select>

                      <input
                        type="number"
                        min="0"
                        max={variant.discountType === 'percentage' ? 100 : bundle.pricing.totalBundlePrice}
                        value={variant.discountValue}
                        onChange={(e) => updateABTestVariant(index, 'discountValue', parseFloat(e.target.value))}
                        placeholder={variant.discountType === 'percentage' ? '%' : '$'}
                        required
                      />

                      <input
                        type="number"
                        min="0"
                        max="100"
                        value={variant.trafficPercentage}
                        onChange={(e) => updateABTestVariant(index, 'trafficPercentage', parseInt(e.target.value))}
                        placeholder="% traffic"
                        required
                      />
                    </div>

                    <div className="variant-preview">
                      Price: ${(bundle.pricing.totalBundlePrice *
                        (variant.discountType === 'percentage'
                          ? (1 - variant.discountValue / 100)
                          : Math.max(0, bundle.pricing.totalBundlePrice - variant.discountValue)
                        )).toFixed(2)}
                    </div>
                  </div>
                ))}

                <button type="button" onClick={addABTestVariant} className="btn btn-secondary">
                  Add Variant
                </button>
              </div>

              <button type="submit" className="btn btn-primary">
                Start A/B Test
              </button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
}

﻿import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../utils/api';
import './EmailPreferences.css';

const EmailPreferences = () => {
  const { user } = useAuth();
  const [preferences, setPreferences] = useState({
    paymentConfirmations: true,
    sessionReminders: true,
    subscriptionExpiry: true,
    classAnnouncements: true,
    marketingEmails: false,
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetchPreferences();
  }, []);

  const fetchPreferences = async () => {
    try {
      const response = await api.get('/user/email-preferences');
      setPreferences(response.data);
    } catch (error) {
      console.error('Error fetching preferences:', error);
      setMessage('Failed to load email preferences');
    } finally {
      setLoading(false);
    }
  };

  const handlePreferenceChange = (key, value) => {
    setPreferences(prev => ({
      ...prev,
      [key]: value,
    }));
  };

  const savePreferences = async () => {
    setSaving(true);
    setMessage('');

    try {
      await api.put('/user/email-preferences', preferences);
      setMessage('Email preferences saved successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error saving preferences:', error);
      setMessage('Failed to save email preferences');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="email-preferences-loading">Loading preferences...</div>;
  }

  return (
    <div className="email-preferences">
      <h2>Email Preferences</h2>
      <p className="email-preferences-description">
        Choose which emails you would like to receive from EduTalk. You can change these settings at any time.
      </p>

      {message && (
        <div className={`email-preferences-message ${message.includes('successfully') ? 'success' : 'error'}`}>
          {message}
        </div>
      )}

      <div className="email-preferences-list">
        <div className="email-preference-item">
          <div className="preference-content">
            <h3>Payment Confirmations</h3>
            <p>Receive emails when payments are processed successfully</p>
          </div>
          <label className="toggle-switch">
            <input
              type="checkbox"
              checked={preferences.paymentConfirmations}
              onChange={(e) => handlePreferenceChange('paymentConfirmations', e.target.checked)}
            />
            <span className="toggle-slider"></span>
          </label>
        </div>

        <div className="email-preference-item">
          <div className="preference-content">
            <h3>Session Reminders</h3>
            <p>Get reminded about upcoming class sessions</p>
          </div>
          <label className="toggle-switch">
            <input
              type="checkbox"
              checked={preferences.sessionReminders}
              onChange={(e) => handlePreferenceChange('sessionReminders', e.target.checked)}
            />
            <span className="toggle-slider"></span>
          </label>
        </div>

        <div className="email-preference-item">
          <div className="preference-content">
            <h3>Subscription Expiry Warnings</h3>
            <p>Receive warnings when your class subscriptions are about to expire</p>
          </div>
          <label className="toggle-switch">
            <input
              type="checkbox"
              checked={preferences.subscriptionExpiry}
              onChange={(e) => handlePreferenceChange('subscriptionExpiry', e.target.checked)}
            />
            <span className="toggle-slider"></span>
          </label>
        </div>

        <div className="email-preference-item">
          <div className="preference-content">
            <h3>Class Announcements</h3>
            <p>Stay updated with important announcements from your classes</p>
          </div>
          <label className="toggle-switch">
            <input
              type="checkbox"
              checked={preferences.classAnnouncements}
              onChange={(e) => handlePreferenceChange('classAnnouncements', e.target.checked)}
            />
            <span className="toggle-slider"></span>
          </label>
        </div>

        <div className="email-preference-item">
          <div className="preference-content">
            <h3>Marketing Emails</h3>
            <p>Receive promotional emails about new features and classes</p>
          </div>
          <label className="toggle-switch">
            <input
              type="checkbox"
              checked={preferences.marketingEmails}
              onChange={(e) => handlePreferenceChange('marketingEmails', e.target.checked)}
            />
            <span className="toggle-slider"></span>
          </label>
        </div>
      </div>

      <div className="email-preferences-actions">
        <button
          className="save-preferences-btn"
          onClick={savePreferences}
          disabled={saving}
        >
          {saving ? 'Saving...' : 'Save Preferences'}
        </button>
      </div>
    </div>
  );
};

export default EmailPreferences;

import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  BarChart,
  Bar,
} from 'recharts';
import '../styles/AnalyticsCharts.css';

export default function EngagementMetrics({ data }) {
  if (!data) {
    return <div className="chart-container"><p className="chart-empty">Loading...</p></div>;
  }

  const engagement = data.engagement || {};
  const timeline = data.timeline || [];

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div className="custom-tooltip">
          <p className="tooltip-time">
            {new Date(payload[0].payload.time).toLocaleTimeString()}
          </p>
          {payload.map((entry, index) => (
            <p key={index} style={{ color: entry.color }}>
              {entry.name}: {entry.value}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  const chartData = timeline.map((item) => ({
    time: new Date(item.time).toLocaleTimeString(),
    engagement: Math.round(item.engagement || 0),
    chatMessages: item.chatMessages || 0,
  }));

  return (
    <div className="engagement-metrics">
      {/* KPI Cards */}
      <div className="engagement-kpis">
        <div className="engagement-kpi">
          <h4>Average Engagement Score</h4>
          <p className="kpi-number">{engagement.averageScore || 0}/100</p>
        </div>
        <div className="engagement-kpi">
          <h4>Chat Messages</h4>
          <p className="kpi-number">{engagement.totalChatMessages || 0}</p>
        </div>
        <div className="engagement-kpi">
          <h4>Chat Participation Rate</h4>
          <p className="kpi-number">
            {Math.round(engagement.chatParticipationRate || 0)}%
          </p>
        </div>
        <div className="engagement-kpi">
          <h4>Average Watch Time</h4>
          <p className="kpi-number">{engagement.averageWatchTime || 0} min</p>
        </div>
      </div>

      {/* Timeline Chart */}
      <div className="chart-container">
        <h3>Engagement Over Time</h3>
        <ResponsiveContainer width="100%" height={350}>
          <LineChart data={chartData} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
            <XAxis
              dataKey="time"
              stroke="#666"
              tick={{ fontSize: 12 }}
              angle={-45}
              textAnchor="end"
              height={80}
            />
            <YAxis
              yAxisId="left"
              stroke="#9b59b6"
              label={{
                value: 'Engagement Score',
                angle: -90,
                position: 'insideLeft',
              }}
            />
            <YAxis
              yAxisId="right"
              orientation="right"
              stroke="#e74c3c"
              label={{
                value: 'Chat Messages',
                angle: 90,
                position: 'insideRight',
              }}
            />
            <Tooltip content={<CustomTooltip />} />
            <Legend wrapperStyle={{ paddingTop: '20px' }} />
            <Line
              yAxisId="left"
              type="monotone"
              dataKey="engagement"
              stroke="#9b59b6"
              dot={false}
              strokeWidth={2}
              name="Engagement Score"
            />
            <Line
              yAxisId="right"
              type="stepAfter"
              dataKey="chatMessages"
              stroke="#e74c3c"
              dot={false}
              strokeWidth={2}
              name="Chat Messages"
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      {/* Insights */}
      <div className="engagement-insights">
        <h3>Insights</h3>
        <ul>
          <li>
            <strong>Most Engaged Metric:</strong>{' '}
            {engagement.chatParticipationRate > 30
              ? 'High chat participation'
              : 'Focus on building community'}
          </li>
          <li>
            <strong>Watch Time:</strong> Viewers stayed an average of{' '}
            {engagement.averageWatchTime || 0} minutes
          </li>
          <li>
            <strong>Chat Health:</strong> {engagement.totalChatMessages} messages from{' '}
            {engagement.totalViewers} viewers
          </li>
        </ul>
      </div>
    </div>
  );
}

import React from 'react';
import '../styles/ErrorBoundary.css';

const isDevelopment = import.meta.env.DEV;

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      errorCount: 0
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState(prevState => ({
      error,
      errorInfo,
      errorCount: prevState.errorCount + 1
    }));

    // Log to console for debugging
    console.error('Error caught by boundary:', error);
    console.error('Error info:', errorInfo);

    // Optionally send to error tracking service (Sentry, etc.)
    // this.reportToErrorTracking(error, errorInfo);
  }

  resetError = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null
    });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="error-boundary">
          <div className="error-boundary__container">
            <div className="error-boundary__icon">⚠️</div>
            <h1 className="error-boundary__title">Something went wrong</h1>
            <p className="error-boundary__message">
              We encountered an unexpected error. Please try again or contact support if the problem persists.
            </p>

            {isDevelopment && this.state.error && (
              <details className="error-boundary__details">
                <summary>Error Details (Development Only)</summary>
                <pre className="error-boundary__error-stack">
                  {this.state.error.toString()}
                  {'\n\n'}
                  {this.state.errorInfo?.componentStack}
                </pre>
              </details>
            )}

            <div className="error-boundary__actions">
              <button
                className="error-boundary__button error-boundary__button--primary"
                onClick={this.resetError}
              >
                Try Again
              </button>
              <button
                className="error-boundary__button error-boundary__button--secondary"
                onClick={() => window.location.href = '/'}
              >
                Go Home
              </button>
            </div>

            {this.state.errorCount > 3 && (
              <p className="error-boundary__warning">
                Multiple errors detected. Please refresh the page or clear your browser cache.
              </p>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

import { useState, useEffect, useRef } from 'react';
import '../styles/HLSPlayer.css';

export default function HLSPlayer({ streamId, quality, onQualityChange, isLive }) {
  const videoRef = useRef(null);
  const containerRef = useRef(null);
  const hlsRef = useRef(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [currentBitrate, setCurrentBitrate] = useState('Auto');
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [networkStats, setNetworkStats] = useState({
    bitrate: 0,
    framerate: 0,
    droppedFrames: 0
  });

  // Initialize HLS player
  useEffect(() => {
    const initHLS = async () => {
      try {
        // Dynamic import of HLS.js to avoid issues if not installed yet
        let Hls;
        try {
          Hls = (await import("hls.js")).default;
        } catch (err) {
          console.warn('HLS.js not installed, falling back to native HLS support');
          // Use native HLS support (Safari)
          if (videoRef.current && videoRef.current.canPlayType('application/vnd.apple.mpegurl')) {
            const manifestUrl = `https://videodelivery.net/${streamId}/manifest/video.m3u8`;
            videoRef.current.src = manifestUrl;
            setLoading(false);
            return;
          }
          throw new Error('HLS not supported in this browser');
        }

        if (!Hls.isSupported()) {
          throw new Error('HLS not supported in this browser');
        }

        const manifestUrl = `https://videodelivery.net/${streamId}/manifest/video.m3u8`;

        const hls = new Hls({
          debug: false,
          enableWorker: true,
          lowLatencyMode: true,
          maxBufferLength: 30,
          maxMaxBufferLength: 60,
        });

        hls.loadSource(manifestUrl);
        hls.attachMedia(videoRef.current);

        // Events
        hls.on(Hls.Events.MANIFEST_PARSED, () => {
          console.log('HLS manifest parsed, quality levels available:', hls.levels.length);
          setLoading(false);
          videoRef.current.play().catch(() => {
            // Autoplay failed, user will click play
          });
        });

        hls.on(Hls.Events.ERROR, (event, data) => {
          console.error('HLS error:', data);
          if (data.fatal) {
            setError(`Stream error: ${data.details}`);
          }
        });

        hls.on(Hls.Events.hlsLevelSwitching, (event, data) => {
          if (hls.levels[data.level]) {
            const levelName = hls.levels[data.level].name || hls.levels[data.level].bitrate;
            setCurrentBitrate(levelName);
            onQualityChange?.(levelName);
          }
        });

        hls.on(Hls.Events.statsUpdated, (event, data) => {
          setNetworkStats({
            bitrate: Math.round(data.bitrate / 1000),
            framerate: Math.round(data.framesDecoded / (data.audioSamples / 48000)) || 0,
            droppedFrames: data.framesDropped || 0
          });
        });

        hlsRef.current = hls;

        // Start stats polling
        const statsInterval = setInterval(() => {
          if (videoRef.current && hlsRef.current) {
            const level = hlsRef.current.currentLevel;
            if (level >= 0 && hlsRef.current.levels[level]) {
              const name = hlsRef.current.levels[level].name || 
                          `${hlsRef.current.levels[level].height}p`;
              setCurrentBitrate(name);
            }
          }
        }, 2000);

        return () => {
          clearInterval(statsInterval);
          hls.destroy();
        };
      } catch (err) {
        console.error('Failed to initialize HLS:', err);
        setError(err.message);
        setLoading(false);
      }
    };

    if (streamId && videoRef.current) {
      initHLS();
    }

    return () => {
      if (hlsRef.current) {
        hlsRef.current.destroy();
        hlsRef.current = null;
      }
    };
  }, [streamId, onQualityChange]);

  // Handle quality change
  useEffect(() => {
    if (!hlsRef.current || !quality) return;

    if (quality === 'auto') {
      hlsRef.current.currentLevel = -1;
      setCurrentBitrate('Auto');
    } else {
      const levelIndex = hlsRef.current.levels.findIndex(
        (level) => {
          const name = level.name || `${level.height}p`;
          return name === quality || name.includes(quality);
        }
      );

      if (levelIndex >= 0) {
        hlsRef.current.currentLevel = levelIndex;
        const level = hlsRef.current.levels[levelIndex];
        setCurrentBitrate(level.name || `${level.height}p`);
      }
    }
  }, [quality]);

  // Handle fullscreen
  const toggleFullscreen = async () => {
    try {
      if (!document.fullscreenElement) {
        // Enter fullscreen
        if (containerRef.current.requestFullscreen) {
          await containerRef.current.requestFullscreen();
          // Lock portrait for mobile
          if (screen.orientation && screen.orientation.lock) {
            await screen.orientation.lock('landscape').catch(() => {});
          }
          setIsFullscreen(true);
        }
      } else {
        // Exit fullscreen
        if (document.exitFullscreen) {
          await document.exitFullscreen();
          // Unlock orientation
          if (screen.orientation && screen.orientation.unlock) {
            screen.orientation.unlock();
          }
          setIsFullscreen(false);
        }
      }
    } catch (err) {
      console.error('Fullscreen error:', err);
    }
  };

  // Handle fullscreen change event
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
    };
  }, []);

  // Handle video click for fullscreen
  const handleVideoClick = () => {
    if (videoRef.current) {
      if (videoRef.current.paused) {
        videoRef.current.play();
      } else {
        videoRef.current.pause();
      }
    }
  };

  // Handle double-click for fullscreen
  const handleVideoDoubleClick = () => {
    toggleFullscreen();
  };

  return (
    <div className="hls-player-container">
      {loading && (
        <div className="player-loading">
          <div className="loading-spinner">
            <div className="spinner"></div>
            <p>Loading stream...</p>
          </div>
        </div>
      )}

      {error && (
        <div className="player-error">
          <div className="error-content">
            <span className="error-icon">⚠️</span>
            <p>{error}</p>
            <small>Trying to reconnect...</small>
          </div>
        </div>
      )}

      <div className={`hls-player ${loading ? 'loading' : ''} ${error ? 'error' : ''} ${isFullscreen ? 'fullscreen' : ''}`} ref={containerRef}>
        <video
          ref={videoRef}
          controls
          autoPlay
          muted={false}
          className="video-element"
          poster="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 720'%3E%3Crect fill='%23000' width='1280' height='720'/%3E%3C/svg%3E"
          onClick={handleVideoClick}
          onDoubleClick={handleVideoDoubleClick}
        />

        <button 
          className="fullscreen-button"
          onClick={toggleFullscreen}
          title={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
          aria-label={isFullscreen ? 'Exit fullscreen' : 'Enter fullscreen'}
        >
          {isFullscreen ? '⛶' : '⛶'}
        </button>

        <div className="player-stats">
          <div className="stat-badge">
            <span className="stat-label">Quality:</span>
            <span className="stat-value">{currentBitrate}</span>
          </div>
          {networkStats.bitrate > 0 && (
            <div className="stat-badge">
              <span className="stat-label">Bitrate:</span>
              <span className="stat-value">{networkStats.bitrate} kbps</span>
            </div>
          )}
          {isLive && <div className="live-badge">🔴 LIVE</div>}
        </div>
      </div>

      <div className="player-footer">
        <p className="stream-quality-info">
          Video quality: {currentBitrate}
          {networkStats.bitrate > 0 && ` • ${networkStats.bitrate} kbps`}
        </p>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import '../styles/Header.css';
import { useAuth } from '../hooks/useAuth';
import { Link, useNavigate } from 'react-router-dom';
import NotificationBadge from './NotificationBadge';
import MobileNav from './MobileNav';
import LanguageSwitcher from './LanguageSwitcher';
import ToastContainer from './ToastContainer';
import { initSocket, setNotificationHandler, closeSocket } from '../utils/socket';
import { showToast } from '../utils/toastManager';
import api from '../utils/api';

export default function Header() {
  const { t } = useTranslation('common');
  const { user, isAuthenticated, logout, token } = useAuth();
  const navigate = useNavigate();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [pointsBalance, setPointsBalance] = useState(null);

  const handleLogout = () => {
    // close socket on logout
    try { closeSocket(); } catch (e) { console.warn('closeSocket failed', e); }
    logout();
    navigate('/');
    setMobileMenuOpen(false);
  };

  const closeMobileMenu = () => {
    setMobileMenuOpen(false);
  };

  useEffect(() => {
    let mounted = true;
    async function fetchBalance() {
      if (!user) return;
      try {
        const res = await api.get(`/points/balance/${user._id}`);
        if (mounted) setPointsBalance(res.data.balance || 0);
      } catch (err) {
        console.warn('Failed to load points balance', err.message || err);
      }
    }

    fetchBalance();

    // init socket if token exists
    if (isAuthenticated && token) {
      const sock = initSocket(token);
      setNotificationHandler((notif) => {
        // show a toast on achievement notifications
        if (notif && notif.type === 'achievement_unlocked') {
          showToast({
            title: notif.title || 'Achievement Unlocked',
            message: notif.message || '',
            type: 'success',
            ttl: 6000,
            action: { url: '/achievements', label: 'View' },
          });
        }
      });
    }

    return () => { mounted = false; };
  }, [isAuthenticated, user, token]);

  return (
    <header className="header">
      <div className="container">
        <Link to="/" className="logo">
          <h1>EduTalk</h1>
        </Link>

        <nav className="nav">
          <Link to="/browse" className="nav-link">{t('header.browseClasses')}</Link>

          {isAuthenticated ? (
            <>
              <Link to="/dashboard" className="nav-link">
                {user?.isHost ? 'My Teaching' : t('header.dashboard')}
              </Link>
              {user?.isHost && (
                <>
                  <Link to="/host-dashboard" className="nav-link">Host Dashboard</Link>
                  <Link to="/analytics" className="nav-link">📊 Analytics</Link>
                  <Link to="/moderation" className="nav-link">🛡️ Moderation</Link>
                  <Link to="/schedules" className="nav-link">📅 Schedules</Link>
                </>
              )}
              <Link to="/achievements" className="nav-link">Achievements</Link>
              <Link to="/points" className="nav-link">Points</Link>
              {user?.isAdmin && (                <Link to="/admin/dashboard" className="nav-link admin-link">🔐 Admin Panel</Link>
              )}
              <Link to="/recordings" className="nav-link">Recordings</Link>
              <Link to="/appeals" className="nav-link" title="View your content appeals">📋 Appeals</Link>
              <NotificationBadge />
              <LanguageSwitcher />
              <div className="points-inline" title="Total points">
                🏅 {pointsBalance != null ? pointsBalance : '—'}
              </div>
              <button onClick={handleLogout} className="nav-button logout">
                {t('header.logout')}
              </button>
            </>
          ) : (
            <>
              <div className="auth-buttons">
                <Link to="/login" className="nav-link">{t('header.login')}</Link>
                <Link to="/signup" className="nav-button">{t('header.signup')}</Link>
              </div>
              <LanguageSwitcher />
            </>
          )}
        </nav>

        {/* Mobile Menu Button */}
        <button
          className="mobile-menu-button"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle menu"
          aria-expanded={mobileMenuOpen}
        >
          <span></span>
          <span></span>
          <span></span>
        </button>

        {/* Mobile Navigation */}
        {mobileMenuOpen && (
          <MobileNav
            isAuthenticated={isAuthenticated}
            user={user}
            onLogout={handleLogout}
            onClose={closeMobileMenu}
          />
        )}
      </div>
      <ToastContainer />
    </header>
  );
}

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import '../styles/LanguageSwitcher.css';

const LanguageSwitcher = () => {
  const { i18n, t } = useTranslation('common');
  const [isOpen, setIsOpen] = useState(false);

  const languages = [
    { code: 'en', name: 'English', flag: '🇬🇧' },
    { code: 'es', name: 'Español', flag: '🇪🇸' },
    { code: 'fr', name: 'Français', flag: '🇫🇷' },
    { code: 'de', name: 'Deutsch', flag: '🇩🇪' },
    { code: 'zh', name: '中文', flag: '🇨🇳' },
    { code: 'ar', name: 'العربية', flag: '🇸🇦' },
  ];

  const changeLanguage = (code) => {
    try {
      localStorage.setItem('i18nextLng', code);
    } catch (e) {
      // ignore localStorage write errors
    }

    i18n.changeLanguage(code).catch(err => console.error('i18n changeLanguage error:', err));

    document.documentElement.lang = code;
    const isRTL = code === 'ar';
    document.documentElement.dir = isRTL ? 'rtl' : 'ltr';
    document.body.dir = isRTL ? 'rtl' : 'ltr';
    setIsOpen(false);
  };

  // Normalize language code (handle en-US, zh-CN, etc.)
  const activeLangCode = (i18n.language || i18n.resolvedLanguage || 'en').split('-')[0];
  const currentLang = languages.find(lang => lang.code === activeLangCode) || languages[0];

  return (
    <div className="language-switcher">
      <button
        className="language-button"
        onClick={(e) => { e.stopPropagation(); setIsOpen(!isOpen); }}
        title={t('selectLanguage')}
        aria-label={t('selectLanguage')}
      >
        <span className="language-flag">{currentLang.flag}</span>
        <span className="language-code">{currentLang.code.toUpperCase()}</span>
      </button>

      {isOpen && (
        <div className="language-dropdown">
          {languages.map(lang => (
            <button
              key={lang.code}
              className={`language-option ${i18n.language === lang.code ? 'active' : ''}`}
              onClick={() => changeLanguage(lang.code)}
            >
              <span className="flag">{lang.flag}</span>
              <span className="name">{lang.name}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default LanguageSwitcher;

