  const [chapters, setChapters] = useState([]);
  const videoRef = React.useRef(null);

  useEffect(() => {
    fetchRecording();
  }, [recordingId]);

  const fetchRecording = async () => {
    try {
      const response = await api.get(`/recordings/${recordingId}`);
      setRecording(response.data);
      setChapters(response.data.chapters || []);
    } catch (error) {
      console.error('Failed to fetch recording:', error);
    } finally {
      setLoading(false);
    }
  };

  const jumpToChapter = (timestamp) => {
    if (videoRef.current) {
      videoRef.current.currentTime = timestamp;
    }
  };

  if (loading) {
    return <div className="loading">Loading recording...</div>;
  }

  if (!recording) {
    return <div className="error">Recording not found</div>;
  }

  return (
    <div className="recording-player">
      <div className="player-main">
        <div className="video-wrapper">
          <video
            ref={videoRef}
            src={recording.hlsUrl || recording.storageUrl}
            controls
            onTimeUpdate={(e) => setCurrentTime(e.target.currentTime)}
            className="video-player"
          />
          <div className="watermark">📧 {recording.watermarkText}</div>
        </div>

        <div className="video-info">
          <h2>{recording.title}</h2>
          <p>{recording.description}</p>
          
          <div className="info-grid">
            <div className="info-item">
              <span className="label">Duration:</span>
              <span className="value">{Math.floor(recording.duration / 60)} minutes</span>
            </div>
            <div className="info-item">
              <span className="label">File Size:</span>
              <span className="value">{(recording.fileSize / 1024 / 1024).toFixed(2)} MB</span>
            </div>
            <div className="info-item">
              <span className="label">Status:</span>
              <span className="value">{recording.status}</span>
            </div>
          </div>
        </div>
      </div>

      <aside className="player-sidebar">
        <div className="sidebar-section">
          <h3>Transcript</h3>
          <div className="transcript">
            {recording.transcript ? (
              <p>{recording.transcript.substring(0, 500)}...</p>
            ) : (
              <p className="placeholder">Transcription processing...</p>
            )}
          </div>
        </div>

        <div className="sidebar-section">
          <h3>Summary</h3>
          <div className="summary">
            {recording.summary ? (
              <p>{recording.summary}</p>
            ) : (
              <p className="placeholder">Summary generating...</p>
            )}
          </div>
        </div>

        <div className="sidebar-section">
          <h3>Key Takeaways</h3>
          <ul className="takeaways">
            {recording.keyTakeaways && recording.keyTakeaways.length > 0 ? (
              recording.keyTakeaways.map((takeaway, idx) => (
                <li key={idx}>{takeaway}</li>
              ))
            ) : (
              <li className="placeholder">Extracting key points...</li>
            )}
          </ul>
        </div>

        {chapters.length > 0 && (
          <div className="sidebar-section">
            <h3>Chapters</h3>
            <div className="chapters-list">
              {chapters.map((chapter, idx) => (
                <button
                  key={idx}
                  className="chapter-btn"
                  onClick={() => jumpToChapter(chapter.timestamp)}
                >
                  <span className="time">
                    {Math.floor(chapter.timestamp / 60)}:{String(chapter.timestamp % 60).padStart(2, '0')}
                  </span>
                  <span className="title">{chapter.title}</span>
                </button>
              ))}
            </div>
          </div>
        )}
      </aside>
    </div>
  );
}

import React from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts';
import '../styles/AnalyticsCharts.css';

export default function RetentionCurve({ data }) {
  if (!data) {
    return (
      <div className="chart-container">
        <p className="chart-empty">Loading...</p>
      </div>
    );
  }

  const retention = data.retention || {};

  // Format data for bar chart
  const chartData = [
    { label: '5 min', viewers: retention['5min'] || 0, percentage: true },
    { label: '10 min', viewers: retention['10min'] || 0, percentage: true },
    { label: '15 min', viewers: retention['15min'] || 0, percentage: true },
    { label: '30 min', viewers: retention['30min'] || 0, percentage: true },
    { label: '60 min', viewers: retention['60min'] || 0, percentage: true },
  ].filter((item) => item.viewers > 0 || retention.total > 0);

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      return (
        <div className="custom-tooltip">
          <p className="tooltip-label">{payload[0].payload.label}</p>
          <p className="tooltip-value">
            {payload[0].payload.viewers}% retained
          </p>
        </div>
      );
    }
    return null;
  };

  return (
    <div className="retention-curve">
      {/* Bar Chart */}
      <div className="chart-container">
        <ResponsiveContainer width="100%" height={350}>
          <BarChart data={chartData} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
            <XAxis
              dataKey="label"
              stroke="#666"
              tick={{ fontSize: 12 }}
              label={{ value: 'Watch Time', position: 'insideBottomRight', offset: -5 }}
            />
            <YAxis
              stroke="#2ecc71"
              label={{
                value: 'Retention Rate (%)',
                angle: -90,
                position: 'insideLeft',
              }}
              domain={[0, 100]}
            />
            <Tooltip content={<CustomTooltip />} />
            <Bar
              dataKey="viewers"
              fill="#2ecc71"
              radius={[8, 8, 0, 0]}
              name="Retention Rate"
            />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* Retention Summary */}
      <div className="retention-summary">
        <h3>Retention Summary</h3>
        <div className="retention-stats">
          <div className="retention-stat">
            <h4>Total Viewers</h4>
            <p className="stat-value">{retention.total || 0}</p>
          </div>
          <div className="retention-stat">
            <h4>Retention at 5 min</h4>
            <p className="stat-value">{retention['5min'] || 0}%</p>
          </div>
          <div className="retention-stat">
            <h4>Retention at 30 min</h4>
            <p className="stat-value">{retention['30min'] || 0}%</p>
          </div>
          <div className="retention-stat">
            <h4>Full Duration</h4>
            <p className="stat-value">{retention['60min'] || 0}%</p>
          </div>
        </div>
      </div>

      {/* Insights */}
      <div className="retention-insights">
        <h3>Key Insights</h3>
        <ul>
          <li>
            <strong>Early Dropoff:</strong> {100 - (retention['5min'] || 0)}% of viewers
            left within the first 5 minutes
          </li>
          <li>
            <strong>Mid-stream Retention:</strong> {retention['30min'] || 0}% stayed
            through the 30-minute mark
          </li>
          <li>
            <strong>Completion Rate:</strong> {retention['60min'] || 0}% watched the
            entire stream
          </li>
          {(retention['5min'] || 0) < 60 && (
            <li>
              <strong>Recommendation:</strong> Consider improving stream opening or
              introductory content
            </li>
          )}
          {(retention['60min'] || 0) > 70 && (
            <li>
              <strong>Strong Performance:</strong> Excellent viewer retention! Keep up
              this content quality
            </li>
          )}
        </ul>
      </div>
    </div>
  );
}

﻿import React, { useState, useEffect } from 'react';
import { api } from '../utils/api';
import ScheduleCard from './ScheduleCard';
import ConfirmDialog from './ConfirmDialog';
import MessageBanner from '../components/MessageBanner';
import '../styles/ScheduledStreamsDashboard.css';

export default function ScheduledStreamsDashboard({ hostId, onRefresh }) {
  const [activeTab, setActiveTab] = useState('upcoming');
  const [schedules, setSchedules] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [confirm, setConfirm] = useState({ open: false, title: '', message: '', onConfirm: null });

  const ITEMS_PER_PAGE = 20;

  useEffect(() => {
    fetchSchedules();
    const interval = setInterval(fetchSchedules, 30000);
    return () => clearInterval(interval);
  }, [hostId]);

  const fetchSchedules = async () => {
    try {
      setLoading(true);
      const response = await api.get(`/schedules/host/${hostId}`);
      setSchedules(response.data || []);
      setError(null);
    } catch (err) {
      console.error('Error fetching schedules:', err);
      setError('Failed to load schedules');
    } finally {
      setLoading(false);
    }
  };

  const categorizeSchedules = (allSchedules) => {
    const now = new Date();
    return {
      upcoming: allSchedules.filter(s => new Date(s.scheduledStartTime) > now && s.status !== 'cancelled'),
      active: allSchedules.filter(s => s.status === 'live'),
      past: allSchedules.filter(s => new Date(s.scheduledStartTime) <= now || s.status === 'completed')
    };
  };

  const getCategorized = categorizeSchedules(schedules);
  const tabData = getCategorized[activeTab];

  const filteredSchedules = tabData.filter(schedule =>
    schedule.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    (schedule.description && schedule.description.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  const paginatedSchedules = filteredSchedules.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const totalPages = Math.ceil(filteredSchedules.length / ITEMS_PER_PAGE);

  const handleEdit = async (schedule) => {
    // This would typically navigate to edit page or open modal
    console.log('Edit schedule:', schedule);
  };

  const handleCancel = (schedule) => {
    setConfirm({
      open: true,
      title: 'Cancel Schedule',
      message: 'Are you sure you want to cancel this schedule?',
      onConfirm: async () => {
        setConfirm({ open: false });
        try {
          await api.put(`/schedules/${schedule._id}`, { status: 'cancelled' });
          fetchSchedules();
        } catch (err) {
          console.error('Error cancelling schedule:', err);
          setError('Failed to cancel schedule');
        }
      },
    });
  };

  const handleViewDetails = (schedule) => {
    console.log('View details:', schedule);
  };

  const getStats = () => ({
    upcoming: getCategorized.upcoming.length,
    active: getCategorized.active.length,
    past: getCategorized.past.length
  });

  const stats = getStats();

  const getEmptyMessage = () => {
    const messages = {
      upcoming: 'No upcoming scheduled streams. Create one to get started!',
      active: 'No active streams right now.',
      past: 'No completed streams yet.'
    };
    return messages[activeTab];
  };

  return (
    <div className="scheduled-streams-dashboard">

      {error && (
        <MessageBanner type="error" title="Schedules" message={error} onClose={() => setError(null)} />
      )}

      <ConfirmDialog
        open={confirm.open}
        title={confirm.title}
        message={confirm.message}
        onConfirm={confirm.onConfirm}
        onCancel={() => setConfirm({ open: false })}
      />
      {/* Stats Section */}
      <div className="stats-section">
        <div className="stat-card">
          <div className="stat-number">{stats.upcoming}</div>
          <div className="stat-label">Upcoming</div>
        </div>
        <div className="stat-card active">
          <div className="stat-number">{stats.active}</div>
          <div className="stat-label">Active Now</div>
        </div>
        <div className="stat-card completed">
          <div className="stat-number">{stats.past}</div>
          <div className="stat-label">Past</div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="tab-navigation">
        <button
          className={`tab-button ${activeTab === 'upcoming' ? 'active' : ''}`}
          onClick={() => {
            setActiveTab('upcoming');
            setCurrentPage(1);
          }}
        >
          ðŸ“… Upcoming ({stats.upcoming})
        </button>
        <button
          className={`tab-button ${activeTab === 'active' ? 'active' : ''}`}
          onClick={() => {
            setActiveTab('active');
            setCurrentPage(1);
          }}
        >
          ðŸ”´ Active ({stats.active})
        </button>
        <button
          className={`tab-button ${activeTab === 'past' ? 'active' : ''}`}
          onClick={() => {
            setActiveTab('past');
            setCurrentPage(1);
          }}
        >
          âœ… Past ({stats.past})
        </button>
      </div>

      {/* Search and Create Section */}
      <div className="controls-section">
        <input aria-label="Search schedules by title or description..."
          type="text"
           placeholder="Search schedules by title or description..."
          value={searchQuery}
          onChange={(e) => {
            setSearchQuery(e.target.value);
            setCurrentPage(1);
          }}
          className="search-input"
        />
        <button className="create-btn" onClick={() => window.location.href = '/schedules'}>
          âž• Create New Schedule
        </button>
      </div>

      {/* Error Message */}
      {error && (
        <div className="error-message">
          <p>{error}</p>
          <button onClick={fetchSchedules}>Retry</button>
        </div>
      )}

      {/* Loading State */}
      {loading && (
        <div className="loading-state">
          <div className="spinner"></div>
          <p>Loading schedules...</p>
        </div>
      )}

      {/* Schedules List */}
      {!loading && (
        <>
          {paginatedSchedules.length > 0 ? (
            <div className="schedules-list">
              {paginatedSchedules.map(schedule => (
                <ScheduleCard
                  key={schedule._id}
                  schedule={schedule}
                  onEdit={handleEdit}
                  onCancel={handleCancel}
                  onViewDetails={handleViewDetails}
                />
              ))}
            </div>
          ) : (
            <div className="empty-state">
              <div className="empty-icon">ðŸ“­</div>
              <p>{getEmptyMessage()}</p>
              {activeTab === 'upcoming' && (
                <button 
                  className="create-btn-primary"
                  onClick={() => window.location.href = '/schedules'}
                >
                  Create Your First Schedule
                </button>
              )}
            </div>
          )}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="pagination">
              <button
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                className="pagination-btn"
              >
                â† Previous
              </button>
              <span className="pagination-info">
                Page {currentPage} of {totalPages}
              </span>
              <button
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                className="pagination-btn"
              >
                Next â†’
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

