            <p className="no-data">No activity logs</p>
          ) : (
            <div className="activity-list">
              {activityLogs
                .filter(log => 
                  log.action.includes(filterAction) &&
                  (!filterSeverity || log.severity === filterSeverity)
                )
                .map((log, index) => (
                  <div key={index} className="activity-item">
                    <div className="activity-icon">{getActionIcon(log.action)}</div>
                    <div className="activity-details">
                      <h4>{log.action}</h4>
                      <p>{log.description}</p>
                      <p className="meta">ðŸŒ {log.ipAddress} â€¢ {formatDate(log.createdAt)}</p>
                    </div>
                    <div
                      className="severity-badge"
                      style={{ backgroundColor: getSeverityColor(log.severity) }}
                    >
                      {log.severity}
                    </div>
                  </div>
                ))}
            </div>
          )}
        </div>
      )}

      {/* Flagged Tab */}
      {tab === 'flagged' && (
        <div className="tab-content">
          <h2>⚠️ Flagged Activities</h2>

          {flaggedActivities.length === 0 ? (
            <p className="no-data">No flagged activities</p>
          ) : (
            <div className="flagged-list">
              {flaggedActivities.map((activity, index) => (
                <div key={index} className="flagged-item">
                  <div className="flagged-header">
                    <h4>⚠️ {activity.action}</h4>
                    <span className="flag-reason">{activity.flagReason}</span>
                  </div>
                  <div className="flagged-body">
                    <p><strong>Description:</strong> {activity.description}</p>
                    <p><strong>IP Address:</strong> {activity.ipAddress}</p>
                    <p><strong>Timestamp:</strong> {formatDate(activity.createdAt)}</p>
                    <p><strong>Admin:</strong> {activity.adminEmail}</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Sync Status Component
 * Shows offline/online status and pending action queue
 * Displays sync progress and retry controls
 */

import { useState, useEffect } from 'react';
import offlineQueueService from '../utils/offlineQueueService';
import ConfirmDialog from './ConfirmDialog';
import '../styles/sync-status.css';

export default function SyncStatusComponent({ onStatusChange }) {
  const [status, setStatus] = useState('online'); // 'online', 'offline', 'syncing'
  const [pendingCount, setPendingCount] = useState(0);
  const [syncProgress, setSyncProgress] = useState(0);
  const [lastSyncTime, setLastSyncTime] = useState(null);
  const [expandedView, setExpandedView] = useState(false);
  const [queueDetails, setQueueDetails] = useState([]);
  const [error, setError] = useState(null);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Monitor online/offline status
  useEffect(() => {
    const handleOnline = () => {
      setStatus('syncing');
      processQueue();
    };

    const handleOffline = () => {
      setStatus('offline');
    };

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Initial check
    if (navigator.onLine) {
      setStatus('online');
    } else {
      setStatus('offline');
    }

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Update pending count
  useEffect(() => {
    const updatePendingCount = async () => {
      const queue = offlineQueueService.getQueue?.() || [];
      setPendingCount(queue.length);
      setQueueDetails(queue);
    };

    updatePendingCount();

    // Poll for changes
    const interval = setInterval(updatePendingCount, 2000);
    return () => clearInterval(interval);
  }, []);

  // Process queue when online
  const processQueue = async () => {
    try {
      setStatus('syncing');

      const queue = offlineQueueService.getQueue?.() || [];
      const total = queue.length;

      if (total === 0) {
        setStatus('online');
        setSyncProgress(100);
        setLastSyncTime(new Date());
        setTimeout(() => setSyncProgress(0), 2000);
        return;
      }

      // Process queue with progress updates
      if (offlineQueueService.processQueue) {
        await offlineQueueService.processQueue();
      }

      setStatus('online');
      setSyncProgress(100);
      setLastSyncTime(new Date());
      setPendingCount(0);
      setQueueDetails([]);

      // Reset progress bar after 2 seconds
      setTimeout(() => setSyncProgress(0), 2000);
    } catch (error) {
      console.error('Queue processing error:', error);
      setStatus('offline');
    }
  };

  // Manual retry
  const handleRetry = async () => {
    if (!navigator.onLine) {
      setError('No internet connection. Please check your connection and try again.');
      setTimeout(() => setError(null), 4000);
      return;
    }

    await processQueue();
  };

  // Clear queue
  const requestClearQueue = () => {
    setShowClearConfirm(true);
  };

  const doClearQueue = () => {
    setShowClearConfirm(false);
    offlineQueueService.clearQueue?.();
    setPendingCount(0);
    setQueueDetails([]);
  };

  // Status display text
  const getStatusText = () => {
    switch (status) {
      case 'offline':
        return `Offline • ${pendingCount} pending`;
      case 'syncing':
        return `Syncing... (${Math.round(syncProgress)}%)`;
      case 'online':
        return 'Synced';
      default:
        return 'Unknown';
    }
  };

  // Status icon
  const getStatusIcon = () => {
    switch (status) {
      case 'offline':
        return '⚠️';
      case 'syncing':
        return '🔄';
      case 'online':
        return '✓';
      default:
        return '?';
    }
  };

  // Status color
  const getStatusColor = () => {
    switch (status) {
      case 'offline':
        return 'red';
      case 'syncing':
        return 'amber';
      case 'online':
        return 'green';
      default:
        return 'gray';
    }
  };

  return (
    <>
      {/* Mini Status Bar (Always Visible) */}
      <div className={`sync-status-bar sync-status-${getStatusColor()}`}>
        <div className="sync-status-content">
          <button
            className="sync-status-toggle"
            onClick={() => setExpandedView(!expandedView)}
            title="Click to expand"
          >
            <span className="sync-status-icon">{getStatusIcon()}</span>
            <span className="sync-status-text">{getStatusText()}</span>
          </button>

          {pendingCount > 0 && (
            <span className="sync-status-badge">{pendingCount}</span>
          )}
        </div>

        {syncProgress > 0 && status === 'syncing' && (
          <div className="sync-progress-bar">
            <div 
              className="sync-progress-fill" 
              style={{ width: `${syncProgress}%` }}
            />
          </div>
        )}
      </div>

      {/* Expanded Detail View */}
      {expandedView && (
        <div className="sync-status-modal">
          <div className="sync-status-modal-content">
            <div className="sync-status-modal-header">
              <h3>Sync Status</h3>
              <button
                className="sync-close-button"
                onClick={() => setExpandedView(false)}
              >
                ✕
              </button>
            </div>

            <div className="sync-status-modal-body">
              {/* Status Summary */}
              <div className="sync-summary">
                <div className={`sync-status-indicator sync-status-${getStatusColor()}`}>
                  <span className="icon">{getStatusIcon()}</span>
                  <span className="text">
                    Status: <strong>{getStatusText()}</strong>
                  </span>
                </div>
              </div>

              {error && <div className="alert alert-error" style={{marginTop:12}}>{error}</div>}

              {/* Last Sync Info */}
              {lastSyncTime && (
                <div className="sync-info">
                  <small>
                    Last synced: {lastSyncTime.toLocaleTimeString()}
                  </small>
                </div>
              )}

              {/* Pending Actions Queue */}
              {pendingCount > 0 && (
                <div className="sync-queue">
                  <h4>Pending Actions ({pendingCount})</h4>
                  <div className="queue-list">
                    {queueDetails.slice(0, 5).map((item, idx) => (
                      <div key={idx} className="queue-item">
                        <div className="queue-method">
                          <span className={`method-badge method-${item.method?.toLowerCase()}`}>
                            {item.method}
                          </span>
                        </div>
                        <div className="queue-details">
                          <small className="queue-path">{item.url}</small>
                          <small className="queue-time">
                            {new Date(item.timestamp).toLocaleTimeString()}
                          </small>
                        </div>
                        <div className="queue-status">
                          {item.retries > 0 && (
                            <span className="retry-badge">Retry {item.retries}</span>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>

                  {pendingCount > 5 && (
                    <small className="text-muted">
                      ... and {pendingCount - 5} more
                    </small>
                  )}
                </div>
              )}

              {/* Actions */}
              <div className="sync-actions">
                {status === 'offline' && pendingCount > 0 && (
                  <button 
                    className="btn btn-primary" 
                    onClick={handleRetry}
                  >
                    Retry Sync
                  </button>
                )}

                {status === 'syncing' && (
                  <button className="btn btn-disabled" disabled>
                    Syncing... Please wait
                  </button>
                )}

                {pendingCount > 0 && (
                  <button 
                    className="btn btn-secondary" 
                    onClick={requestClearQueue}
                  >
                    Clear Pending
                  </button>
                )}

                <button 
                  className="btn btn-text" 
                  onClick={() => setExpandedView(false)}
                >
                  Close
                </button>
              </div>

              {/* Network Info */}
              <div className="sync-network-info">
                <hr />
                <small>
                  <strong>Connection:</strong> {navigator.onLine ? 'Online' : 'Offline'}
                </small>
                <br />
                {navigator.connection && (
                  <>
                    <small>
                      <strong>Network Type:</strong>{' '}
                      {navigator.connection.effectiveType || 'Unknown'}
                    </small>
                    <br />
                  </>
                )}
                <small>
                  <strong>Auto-sync:</strong> Enabled
                </small>
              </div>
            </div>
          </div>

          {/* Modal Overlay */}

          <ConfirmDialog
            open={showClearConfirm}
            title={`Clear ${pendingCount} pending actions?`}
            message={`Are you sure you want to clear ${pendingCount} pending actions? This cannot be undone.`}
            onConfirm={doClearQueue}
            onCancel={() => setShowClearConfirm(false)}
            confirmLabel="Clear"
            cancelLabel="Cancel"
          />

          <div 
            className="sync-status-overlay" 
            onClick={() => setExpandedView(false)}
          />
        </div>
      )}
    </>
  );
}

import React, { useState, useEffect } from 'react';
import api from '../utils/api';
import '../styles/TwoFASetup.css';

export default function TwoFASetup() {
  const [step, setStep] = useState(1); // 1: Generate, 2: Verify, 3: Backup Codes
  const [qrCode, setQrCode] = useState('');
  const [secret, setSecret] = useState('');
  const [verificationCode, setVerificationCode] = useState('');
  const [backupCodes, setBackupCodes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [copied, setCopied] = useState(false);

  // Step 1: Generate 2FA Secret
  const handleGenerate = async () => {
    setLoading(true);
    setError('');

    try {
      const response = await api.post('/security/2fa/generate');
      setQrCode(response.data.qrCode);
      setSecret(response.data.secret);
      setStep(2);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to generate 2FA secret');
    } finally {
      setLoading(false);
    }
  };

  // Step 2: Verify Code
  const handleVerify = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await api.post('/security/2fa/enable', {
        secret,
        verificationCode,
      });

      setBackupCodes(response.data.backupCodes);
      setSuccess('✅ 2FA enabled successfully!');
      setStep(3);
    } catch (err) {
      setError(err.response?.data?.error || 'Invalid verification code');
    } finally {
      setLoading(false);
    }
  };

  // Copy to clipboard
  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="two-fa-setup-container">
      <div className="two-fa-setup-box">
        <div className="two-fa-setup-header">
          <h1>🔐 Enable Two-Factor Authentication</h1>
          <p>Protect your admin account with an extra layer of security</p>
        </div>

        {error && <div className="setup-error">{error}</div>}
        {success && <div className="setup-success">{success}</div>}

        {/* Step 1: Setup Authenticator App */}
        {step === 1 && (
          <div className="setup-step">
            <div className="step-number">Step 1 of 3</div>
            <h2>📱 Download Authenticator App</h2>
            <p>
              Download one of these authenticator apps on your phone:
            </p>
            <div className="app-links">
              <a href="https://apps.apple.com/app/google-authenticator/id388497605" target="_blank" rel="noopener noreferrer">
                🍎 Google Authenticator (iOS)
              </a>
              <a href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2" target="_blank" rel="noopener noreferrer">
                🤖 Google Authenticator (Android)
              </a>
              <a href="https://apps.apple.com/app/microsoft-authenticator/id981333031" target="_blank" rel="noopener noreferrer">
                🔐 Microsoft Authenticator
              </a>
              <a href="https://authy.com" target="_blank" rel="noopener noreferrer">
                🔑 Authy
              </a>
            </div>

            <button
              className="setup-btn"
              onClick={handleGenerate}
              disabled={loading}
            >
              {loading ? '⏳ Generating...' : 'Next: Generate Secret'}
            </button>
          </div>
        )}

        {/* Step 2: Scan QR Code */}
        {step === 2 && (
          <div className="setup-step">
            <div className="step-number">Step 2 of 3</div>
            <h2>🔍 Scan QR Code</h2>
            <p>Scan this QR code with your authenticator app:</p>

            <div className="qr-container">
              {qrCode && (
                <img src={qrCode} alt="2FA QR Code" className="qr-code" />
              )}
            </div>

            <div className="manual-entry">
              <p>Cannot scan? Enter this code manually:</p>
              <div className="secret-box">
                <code>{secret}</code>
                <button
                  type="button"
                  className="copy-btn"
                  onClick={() => copyToClipboard(secret)}
                >
                  {copied ? '✓ Copied!' : '📋 Copy'}
                </button>
              </div>
            </div>

            <form onSubmit={handleVerify}>
              <div className="form-group">
                <label>Enter 6-digit code to verify:</label>
                <input
                  type="text"
                  value={verificationCode}
                  onChange={(e) => setVerificationCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                  placeholder="000000"
                  maxLength="6"
                  pattern="\d{6}"
                  required
                  disabled={loading}
                  className="code-input"
                  autoFocus
                />
              </div>

              <button
                type="submit"
                className="setup-btn"
                disabled={loading}
              >
                {loading ? '⏳ Verifying...' : 'Verify & Continue'}
              </button>
            </form>
          </div>
        )}

        {/* Step 3: Backup Codes */}
        {step === 3 && (
          <div className="setup-step">
            <div className="step-number">Step 3 of 3</div>
            <h2>🔑 Save Backup Codes</h2>
            <p className="important-note">
              ⚠️ Save these backup codes in a safe place. Use them if you lose access to your authenticator app.
            </p>

            <div className="backup-codes-container">
              <div className="backup-codes-list">
                {backupCodes.map((code, index) => (
                  <div key={index} className="backup-code">
                    <span className="code-number">{index + 1}.</span>
                    <code>{code}</code>
                    <button
                      type="button"
                      className="copy-icon"
                      onClick={() => copyToClipboard(code)}
                      title="Copy code"
                    >
                      📋
                    </button>
                  </div>
                ))}
              </div>

              <div className="backup-actions">
                <button
                  type="button"
                  className="action-btn"
                  onClick={() => {
                    const text = backupCodes.join('\n');
                    const element = document.createElement('a');
                    element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(text));
                    element.setAttribute('download', 'backup-codes.txt');
                    element.style.display = 'none';
                    document.body.appendChild(element);
                    element.click();
                    document.body.removeChild(element);
                  }}
                >
                  💾 Download Codes
                </button>
                <button
                  type="button"
                  className="action-btn"
                  onClick={() => copyToClipboard(backupCodes.join('\n'))}
                >
                  📋 Copy All Codes
                </button>
              </div>
            </div>

            <div className="completion-message">
              <h3>✅ 2FA Setup Complete!</h3>
              <p>Your account is now protected with two-factor authentication.</p>
            </div>

            <button
              type="button"
              className="setup-btn"
              onClick={() => window.location.href = '/admin/dashboard'}
            >
              Continue to Dashboard
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import api from '../utils/api';
import '../styles/TwoFAVerification.css';

export default function TwoFAVerification({ token, sessionId, email, onSuccess, onBack }) {
  const [verificationCode, setVerificationCode] = useState('');
  const [backupCode, setBackupCode] = useState('');
  const [method, setMethod] = useState('totp'); // 'totp' or 'backup'
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleVerify = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await api.post(
        '/security/2fa/verify',
        method === 'totp'
          ? { token, verificationCode }
          : { token, backupCode }
      );

      if (response.status === 200) {
        setSuccess('✅ 2FA verified successfully!');
        setTimeout(() => {
          // Get user info from response or re-fetch
          const user = JSON.parse(localStorage.getItem('tempUser') || '{}');
          onSuccess(token, user, sessionId);
        }, 1000);
      }
    } catch (err) {
      setError(err.response?.data?.error || '❌ Invalid code. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="two-fa-container">
      <div className="two-fa-box">
        <div className="two-fa-header">
          <h1>🔐 Two-Factor Authentication</h1>
          <p>Enter your verification code to complete login</p>
        </div>

        {error && <div className="two-fa-error">{error}</div>}
        {success && <div className="two-fa-success">{success}</div>}

        <form onSubmit={handleVerify}>
          {/* Method Selection */}
          <div className="two-fa-method-selector">
            <button
              type="button"
              className={`method-btn ${method === 'totp' ? 'active' : ''}`}
              onClick={() => {
                setMethod('totp');
                setError('');
                setBackupCode('');
              }}
            >
              📱 Authenticator App
            </button>
            <button
              type="button"
              className={`method-btn ${method === 'backup' ? 'active' : ''}`}
              onClick={() => {
                setMethod('backup');
                setError('');
                setVerificationCode('');
              }}
            >
              🔑 Backup Code
            </button>
          </div>

          {/* TOTP Method */}
          {method === 'totp' && (
            <div className="two-fa-form-group">
              <label htmlFor="verificationCode">
                Enter 6-digit code from your authenticator app
              </label>
              <input
                type="text"
                id="verificationCode"
                value={verificationCode}
                onChange={(e) => setVerificationCode(e.target.value.replace(/\D/g, '').slice(0, 6))}
                placeholder="000000"
                maxLength="6"
                pattern="\d{6}"
                required={method === 'totp'}
                disabled={loading}
                className="code-input"
                autoFocus
              />
              <p className="hint">Enter the 6-digit code without spaces</p>
            </div>
          )}

          {/* Backup Code Method */}
          {method === 'backup' && (
            <div className="two-fa-form-group">
              <label htmlFor="backupCode">
                Enter one of your backup codes
              </label>
              <input
                type="text"
                id="backupCode"
                value={backupCode}
                onChange={(e) => setBackupCode(e.target.value.toUpperCase())}
                placeholder="XXXX-XXXX-XXXX"
                required={method === 'backup'}
                disabled={loading}
                autoFocus
              />
              <p className="hint">Format: XXXX-XXXX-XXXX or continuous</p>
            </div>
          )}

          <button
            type="submit"
            className="two-fa-verify-btn"
            disabled={loading}
          >
            {loading ? '⏳ Verifying...' : '✓ Verify'}
          </button>
        </form>

        <div className="two-fa-footer">
          <button
            type="button"
            className="two-fa-back-btn"
            onClick={onBack}
            disabled={loading}
          >
            ← Back to Login
          </button>
          <p className="two-fa-info">
            🔒 2FA adds an extra layer of security to your admin account
          </p>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAdmin } from '../context/AdminContext';

export const UserDetailsModal = ({ user, isOpen, onClose, onAction }) => {
  const { fetchUserActivity } = useAdmin();
  const [activity, setActivity] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('profile');

  useEffect(() => {
    if (isOpen && user) {
      loadActivity();
    }
  }, [isOpen, user]);

  const loadActivity = async () => {
    setLoading(true);
    const data = await fetchUserActivity(user._id);
    if (data) {
      setActivity(data.activity);
    }
    setLoading(false);
  };

  if (!isOpen || !user) return null;

  const getStatusBadge = (status) => {
    if (user.bannedAt) return { text: 'Banned', class: 'banned' };
    if (user.suspendedAt) return { text: 'Suspended', class: 'suspended' };
    return { text: 'Active', class: 'active' };
  };

  const statusInfo = getStatusBadge();

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-dialog" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>{user.firstName} {user.lastName}</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        <div className="modal-tabs">
          <button
            className={`tab-btn ${activeTab === 'profile' ? 'active' : ''}`}
            onClick={() => setActiveTab('profile')}
          >
            Profile
          </button>
          <button
            className={`tab-btn ${activeTab === 'activity' ? 'active' : ''}`}
            onClick={() => setActiveTab('activity')}
          >
            Activity
          </button>
          <button
            className={`tab-btn ${activeTab === 'payments' ? 'active' : ''}`}
            onClick={() => setActiveTab('payments')}
          >
            Payments
          </button>
        </div>

        <div className="modal-body">
          {/* Profile Tab */}
          {activeTab === 'profile' && (
            <div className="profile-section">
              <div className="info-row">
                <label>Email:</label>
                <span>{user.email}</span>
              </div>
              <div className="info-row">
                <label>Name:</label>
                <span>{user.firstName} {user.lastName}</span>
              </div>
              <div className="info-row">
                <label>Status:</label>
                <span className={`status-badge ${statusInfo.class}`}>
                  {statusInfo.text}
                </span>
              </div>
              <div className="info-row">
                <label>Role:</label>
                <span>
                  {user.isAdmin ? '👤 Admin' : ''}
