                bitrate: Math.round((report.bytesReceived * 8) / 1000) + ' kbps',
                framesDecoded: report.framesDecoded,
                packetsLost: report.packetsLost,
              };
            }
          });
        } catch (error) {
          console.error('Error getting stats:', error);
        }
      }
      
      if (Object.keys(newStats).length > 0) {
        setStats(newStats);
      }
    }, 2000);
  };

  // Cleanup
