          console.error('Error replacing track:', error)
        );
      }
    });

    // Update local video display
    setLocalStream(localStreamRef.current);
    if (localVideoRef.current) {
      localVideoRef.current.srcObject = localStreamRef.current;
    }
  };

  const startRecording = async () => {
    try {
      setRecordingStatus('recording');
      const response = await api.post('/recordings/start', {
        sessionId,
        classId,
      });
      console.log('Recording started:', response.data);
    } catch (error) {
      console.error('Failed to start recording:', error);
      setRecordingStatus('idle');
    }
  };

  const stopRecording = async () => {
    try {
      setRecordingStatus('processing');
      const mockVideoUrl = 'https://example.com/video.mp4';

      await api.post('/recordings/complete', {
        recordingId: 'temp-id',
        videoUrl: mockVideoUrl,
        duration: 3600,
      });

      setRecordingStatus('idle');
    } catch (error) {
      console.error('Failed to stop recording:', error);
      setRecordingStatus('idle');
    }
  };

  const sendChatMessage = async () => {
    if (chatInput.trim() && socketRef.current) {
      const messageData = {
        message: chatInput,
        sender: 'You',
        timestamp: new Date(),
      };
      setChatMessages(prev => [...prev, messageData]);
      setChatInput('');

      socketRef.current.emit('chat-message', {
        message: chatInput,
        roomId,
      });
    }
  };

  const endSession = async () => {
    try {
      if (socketRef.current) {
        socketRef.current.emit('leave-room', { roomId });
      }
      await api.post('/video/rooms/leave', { roomId });
      if (onSessionEnd) {
        onSessionEnd();
      }
    } catch (error) {
      console.error('Failed to end session:', error);
    }
  };

  return (
    <div className="video-room">
      {error && <div className="alert alert-error" style={{margin:12}}>{error}</div>}
      <div className="video-container">
        <div className="videos-grid">
          {/* Local video */}
          <div className="video-tile local">
            <video
              ref={localVideoRef}
              autoPlay
              muted
              playsInline
              className="video-element"
            />
            <span className="video-label">ðŸ“¹ You</span>
          </div>

          {/* Remote video tiles */}
          {participants.map((participant) => {
            const stream = remoteStreams[participant.socketId];
            return (
              <div 
                key={participant.socketId} 
                className={`video-tile remote ${activeSpeaker === participant.socketId ? 'speaker' : ''}`}
              >
                {stream ? (
                  <video
                    ref={(el) => {
                      if (el && el.srcObject !== stream) {
                        el.srcObject = stream;
                      }
                    }}
                    autoPlay
                    playsInline
                    className="video-element"
                  />
                ) : (
                  <div className="video-placeholder">Loading...</div>
                )}
                <span className="video-label">ðŸ‘¤ {participant.email.split('@')[0]}</span>
                {stats[participant.socketId] && (
                  <span className="video-stats">{stats[participant.socketId].bitrate}</span>
                )}
              </div>
            );
          })}

          {/* Empty message if alone */}
          {participants.length === 0 && (
            <div className="video-tile empty">
              <span>Waiting for participants...</span>
            </div>
          )}
        </div>

        {/* Connection Status */}
        <div className="connection-status">
          <span className={`status-indicator ${isConnected ? 'connected' : 'disconnected'}`}></span>
          <span>{isConnected ? `Connected (${participants.length + 1} participants)` : 'Disconnected'}</span>
        </div>

        {/* Controls */}
        <div className="controls">
          <button
            className={`control-btn ${!isAudioEnabled ? 'disabled' : ''}`}
            onClick={toggleAudio}
            title="Toggle Audio"
          >
            ðŸŽ¤ {isAudioEnabled ? 'On' : 'Off'}
          </button>

          <button
            className={`control-btn ${!isVideoEnabled ? 'disabled' : ''}`}
            onClick={toggleVideo}
            title="Toggle Video"
          >
            ðŸŽ¥ {isVideoEnabled ? 'On' : 'Off'}
          </button>

          <button
            className={`control-btn ${isScreenSharing ? 'active' : ''}`}
            onClick={isScreenSharing ? stopScreenShare : startScreenShare}
            title="Share Screen"
          >
            ðŸ“º {isScreenSharing ? 'Stop' : 'Share'}
          </button>

          <button
            className={`control-btn ${recordingStatus === 'recording' ? 'recording' : ''}`}
            onClick={recordingStatus === 'idle' ? startRecording : stopRecording}
            title="Record Session"
          >
            â­• {recordingStatus}
          </button>

          <button
            className="control-btn end-session"
            onClick={endSession}
            title="End Session"
          >
            â˜Žï¸ Leave
          </button>
        </div>
      </div>

      {/* Chat Panel */}
      <div className="chat-panel">
        <h3>ðŸ’¬ Chat</h3>
        <div className="messages">
          {chatMessages.map((msg, idx) => (
            <div key={idx} className="message">
              <strong>{msg.sender}:</strong> {msg.message}
            </div>
          ))}
        </div>
        <div className="chat-input">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()}
            placeholder="Type a message..."
          />
          <button onClick={sendChatMessage}>Send</button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import '../styles/ViewerChat.css';

export default function ViewerChat({
  streamId,
  messages,
  onSendMessage,
  isModerated,
  isBlocked,
  blockReason
}) {
  const [newMessage, setNewMessage] = useState('');
  const [charCount, setCharCount] = useState(0);
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef(null);
  const chatContainerRef = useRef(null);

  const MAX_MESSAGE_LENGTH = 200;

  // Auto-scroll to latest message
  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  const handleSendMessage = async () => {
    if (!newMessage.trim()) return;

    setSending(true);
    try {
      await onSendMessage(newMessage);
      setNewMessage('');
      setCharCount(0);
    } catch (err) {
      console.error('Failed to send message:', err);
    } finally {
      setSending(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const handleInputChange = (e) => {
    const text = e.target.value;
    if (text.length <= MAX_MESSAGE_LENGTH) {
      setNewMessage(text);
      setCharCount(text.length);
    }
  };

  const formatTimestamp = (timestamp) => {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${hours}:${minutes}`;
  };

  const getMessageStatusClass = (status) => {
    switch (status) {
      case 'approved':
        return 'message-approved';
      case 'blocked':
        return 'message-blocked';
      case 'pending':
        return 'message-pending';
      default:
        return '';
    }
  };

  return (
    <div className="viewer-chat-container">
      <div className="chat-header">
        <h3>Live Chat</h3>
        {isModerated && <span className="moderation-badge">✓ Moderated</span>}
      </div>

      <div className="chat-messages" ref={chatContainerRef}>
        {messages.length === 0 ? (
          <div className="empty-chat">
            <p>No messages yet. Be the first to chat!</p>
          </div>
        ) : (
          messages.map((msg, index) => (
            <div
              key={msg._id || index}
              className={`chat-message ${getMessageStatusClass(msg.status)}`}
            >
              <div className="message-header">
                <div className="message-author">
                  {msg.avatar && (
                    <img src={msg.avatar} alt={msg.userName} className="avatar" />
                  )}
                  <span className="author-name">{msg.userName}</span>
                </div>
                <span className="message-time">{formatTimestamp(msg.timestamp)}</span>
              </div>

              <div className="message-content">
                {msg.status === 'blocked' ? (
                  <span className="blocked-label">Message blocked by moderators</span>
                ) : msg.status === 'pending' ? (
                  <span className="pending-label">Awaiting moderation...</span>
                ) : (
                  <p className="message-text">{msg.text}</p>
                )}
              </div>
            </div>
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="chat-input-section">
        {isBlocked ? (
          <div className="chat-blocked-notice">
            <p className="blocked-title">🚫 You are temporarily muted</p>
            <p className="blocked-reason">{blockReason}</p>
            <small>You can send messages again in a few minutes</small>
          </div>
        ) : (
          <>
            <textarea
              value={newMessage}
              onChange={handleInputChange}
              onKeyPress={handleKeyPress}
              placeholder="Type a message... (0/200)"
              disabled={sending}
              className="chat-input"
              rows={3}
              maxLength={MAX_MESSAGE_LENGTH}
            />

            <div className="chat-footer">
              <span className="char-count">
                {charCount}/{MAX_MESSAGE_LENGTH}
              </span>

              <button
                onClick={handleSendMessage}
                disabled={!newMessage.trim() || sending}
                className="send-button"
              >
                {sending ? 'Sending...' : 'Send'}
              </button>
            </div>

            {isModerated && (
              <small className="moderation-notice">
                ✓ Messages are reviewed by moderators before appearing
              </small>
            )}
          </>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../utils/api';
import '../styles/WaitingRoom.css';

export default function WaitingRoom({ streamId, classId, scheduledTime, hostInfo }) {
  const navigate = useNavigate();
  const [timeRemaining, setTimeRemaining] = useState('');
  const [streamLive, setStreamLive] = useState(false);
  const [classInfo, setClassInfo] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Countdown timer
  useEffect(() => {
    const calculateTimeRemaining = () => {
      const now = new Date();
      const scheduled = new Date(scheduledTime);
      const diff = scheduled - now;

      if (diff <= 0) {
        setTimeRemaining('STARTING NOW!');
        return true;
      }

      const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      const seconds = Math.floor((diff % (1000 * 60)) / 1000);
      setTimeRemaining(`${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`);
      return false;
    };

    const isStarting = calculateTimeRemaining();
    const timer = setInterval(() => {
      const isNow = calculateTimeRemaining();
      if (isNow) {
        setStreamLive(true);
      }
    }, 1000);

    return () => clearInterval(timer);
  }, [scheduledTime]);

  // Poll stream status
  useEffect(() => {
    const pollStreamStatus = async () => {
      try {
        const response = await api.get(`/live/${streamId}`);
        if (response.data.isLive) {
          setStreamLive(true);
        }
      } catch (err) {
        console.error('Stream status check failed:', err);
      }
    };

    const statusInterval = setInterval(pollStreamStatus, 5000);
    return () => clearInterval(statusInterval);
  }, [streamId]);

  // Fetch class info
  useEffect(() => {
    const fetchClassInfo = async () => {
      try {
        setLoading(true);
        const response = await api.get(`/classes/${classId}`);
        setClassInfo(response.data);
        setError(null);
      } catch (err) {
        console.error('Error fetching class info:', err);
        setError('Failed to load class information');
      } finally {
        setLoading(false);
      }
    };

    if (classId) {
      fetchClassInfo();
    }
  }, [classId]);

  // Redirect when stream starts
  useEffect(() => {
    if (streamLive) {
      const timer = setTimeout(() => {
        navigate(`/watch/${streamId}`);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [streamLive, streamId, navigate]);

  if (loading) {
    return (
      <div className="waiting-room">
        <div className="loading-container">
          <div className="spinner"></div>
          <p>Loading stream information...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="waiting-room">
      <div className="waiting-room-container">
        {/* Banner */}
        <div className="banner-section">
          <div className="going-live-banner">
            <h2>🎬 Going Live Soon!</h2>
            <div className="countdown-display">{timeRemaining}</div>
            {streamLive && <div className="redirect-message">Redirecting to live stream...</div>}
          </div>
        </div>

        <div className="waiting-room-content">
          {/* Left: Host Profile Card */}
          <div className="host-profile-card">
            <div className="card-header">Host Information</div>
            <div className="host-avatar">
              {hostInfo?.avatar ? (
                <img src={hostInfo.avatar} alt={hostInfo?.name} />
              ) : (
                <div className="avatar-placeholder">{hostInfo?.name?.[0]?.toUpperCase() || 'H'}</div>
              )}
            </div>
            <h3 className="host-name">{hostInfo?.name || 'Host'}</h3>
            <p className="host-bio">{hostInfo?.bio || 'Experienced instructor'}</p>
            <div className="host-stats">
              <div className="stat">
                <span className="stat-value">{hostInfo?.classCount || 0}</span>
                <span className="stat-label">Classes</span>
              </div>
              <div className="stat">
                <span className="stat-value">{hostInfo?.rating || '4.8'}</span>
                <span className="stat-label">Rating</span>
              </div>
            </div>
          </div>

          {/* Right: Class & Stream Info */}
          <div className="class-info-section">
            <div className="class-info-card">
              <div className="card-header">Class Information</div>
              <h2 className="class-title">{classInfo?.title || 'Upcoming Class'}</h2>
              <p className="class-description">{classInfo?.description || 'Get ready for an amazing learning experience'}</p>
              
              <div className="stream-details">
                <div className="detail-item">
                  <span className="label">Scheduled Start:</span>
                  <span className="value">{new Date(scheduledTime).toLocaleString()}</span>
                </div>
                <div className="detail-item">
                  <span className="label">Enrolled:</span>
                  <span className="value">{classInfo?.enrolledCount || 0} students</span>
                </div>
                {classInfo?.category && (
                  <div className="detail-item">
                    <span className="label">Category:</span>
                    <span className="value">{classInfo.category}</span>
                  </div>
                )}
              </div>

              <div className="waiting-tips">
                <h4>While You Wait:</h4>
                <ul>
                  <li>✓ Make sure your audio and camera are working</li>
                  <li>✓ Find a quiet, well-lit location</li>
                  <li>✓ Have any materials ready you might need</li>
                  <li>✓ Check your internet connection</li>
                </ul>
              </div>
            </div>

            {/* Chat Section - Disabled */}
            <div className="chat-disabled-section">
              <div className="chat-header">Live Chat</div>
              <div className="chat-disabled-overlay">
                <p>💬 Chat will be available once the stream starts</p>
              </div>
            </div>
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="error-message">
            <p>⚠️ {error}</p>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * React Native - Browse Classes Screen
 * Browse and search available classes with filters
 */

import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TextInput,
  TouchableOpacity,
  FlatList,
  ActivityIndicator,
  SafeAreaView,
} from 'react-native';
import api from '../utils/api';

const BrowseClassesScreen = ({ navigation }) => {
  const [classes, setClasses] = useState([]);
  const [filteredClasses, setFilteredClasses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [sortBy, setSortBy] = useState('newest');

  const categories = [
    { id: 'all', label: 'All' },
    { id: 'programming', label: 'Programming' },
    { id: 'business', label: 'Business' },
    { id: 'design', label: 'Design' },
    { id: 'music', label: 'Music' },
    { id: 'fitness', label: 'Fitness' },
  ];

  useEffect(() => {
    loadClasses();
  }, []);

  useEffect(() => {
    filterClasses();
  }, [searchQuery, selectedCategory, sortBy, classes]);

  const loadClasses = async () => {
    try {
      setLoading(true);
      const response = await api.get('/classes?limit=50');
      setClasses(response.data || []);
    } catch (error) {
      console.error('Failed to load classes:', error);
    } finally {
      setLoading(false);
    }
  };

  const filterClasses = () => {
    let result = classes;

    // Filter by category
    if (selectedCategory !== 'all') {
      result = result.filter((c) => c.category === selectedCategory);
    }

    // Search
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      result = result.filter(
        (c) =>
          c.title.toLowerCase().includes(query) ||
          c.description.toLowerCase().includes(query) ||
          c.host?.name.toLowerCase().includes(query)
      );
    }

    // Sort
    if (sortBy === 'newest') {
      result = result.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    } else if (sortBy === 'price-low') {
      result = result.sort((a, b) => a.basePriceMonth - b.basePriceMonth);
    } else if (sortBy === 'price-high') {
      result = result.sort((a, b) => b.basePriceMonth - a.basePriceMonth);
    } else if (sortBy === 'rating') {
      result = result.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    }

    setFilteredClasses(result);
  };

  const renderClassCard = ({ item }) => (
    <TouchableOpacity
      style={styles.classCard}
      onPress={() => navigation.navigate('ClassDetails', { classId: item.id })}
    >
      <View style={styles.cardHeader}>
        <Text style={styles.cardTitle} numberOfLines={2}>
          {item.title}
        </Text>
        <View style={styles.ratingBadge}>
          <Text style={styles.ratingText}>⭐ {(item.rating || 0).toFixed(1)}</Text>
        </View>
      </View>

      <Text style={styles.cardDescription} numberOfLines={2}>
        {item.description}
      </Text>

      <View style={styles.cardMeta}>
        <Text style={styles.hostName}>👨‍🏫 {item.host?.name}</Text>
        <Text style={styles.category}>{item.category}</Text>
      </View>

      <View style={styles.cardFooter}>
        <Text style={styles.price}>${item.basePriceMonth}/month</Text>
        <TouchableOpacity
          style={styles.enrollButton}
          onPress={() => navigation.navigate('Checkout', { classId: item.id })}
        >
          <Text style={styles.enrollText}>Enroll</Text>
        </TouchableOpacity>
      </View>
    </TouchableOpacity>
  );

  if (loading) {
    return (
      <SafeAreaView style={styles.container}>
        <ActivityIndicator size="large" color="#667eea" />
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      {/* Search Bar */}
      <View style={styles.searchSection}>
        <TextInput
          style={styles.searchInput}
          placeholder="🔍 Search classes..."
          placeholderTextColor="#ccc"
          value={searchQuery}
          onChangeText={setSearchQuery}
        />
      </View>

      <ScrollView showsVerticalScrollIndicator={false}>
        {/* Categories */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={styles.categoriesSection}
        >
          {categories.map((cat) => (
            <TouchableOpacity
              key={cat.id}
              style={[
                styles.categoryBadge,
                selectedCategory === cat.id && styles.categoryBadgeActive,
              ]}
              onPress={() => setSelectedCategory(cat.id)}
            >
              <Text
                style={[
                  styles.categoryText,
                  selectedCategory === cat.id && styles.categoryTextActive,
                ]}
              >
                {cat.label}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>

        {/* Sort Options */}
        <View style={styles.sortSection}>
          <Text style={styles.sortLabel}>Sort by:</Text>
          <View style={styles.sortOptions}>
            {['newest', 'price-low', 'price-high', 'rating'].map((option) => (
              <TouchableOpacity
                key={option}
                style={[
                  styles.sortButton,
                  sortBy === option && styles.sortButtonActive,
                ]}
                onPress={() => setSortBy(option)}
              >
                <Text
                  style={[
                    styles.sortButtonText,
                    sortBy === option && styles.sortButtonTextActive,
                  ]}
                >
                  {option === 'newest'
                    ? 'Newest'
                    : option === 'price-low'
                    ? 'Price: Low'
                    : option === 'price-high'
                    ? 'Price: High'
                    : 'Rating'}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {/* Classes List */}
        {filteredClasses.length === 0 ? (
          <View style={styles.emptyState}>
            <Text style={styles.emptyIcon}>🔍</Text>
            <Text style={styles.emptyText}>No classes found</Text>
            <Text style={styles.emptySubtext}>Try adjusting your search filters</Text>
          </View>
        ) : (
          <View style={styles.classList}>
            {filteredClasses.map((item) => (
              <View key={item.id}>
                {renderClassCard({ item })}
              </View>
            ))}
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
};

