        <ActivityIndicator size="large" color="#667eea" />
      </View>
    );
  }

  return (
    <NavigationContainer linking={linking}>
      <Stack.Navigator screenOptions={{ headerShown: false }}>
        {isAuthenticated ? (
          <Stack.Screen
            name="App"
            component={AppNavigator}
            options={{ animationEnabled: false }}
          />
        ) : (
          <Stack.Screen
            name="Auth"
            component={AuthStack}
            options={{ animationEnabled: false }}
          />
        )}
      </Stack.Navigator>
    </NavigationContainer>
  );
};

/**
 * Deep Linking Configuration
 */
const linking = {
  prefixes: ['edutalk://', 'https://edutalk.app'],
  config: {
    screens: {
      App: {
        screens: {
          HomeTab: {
            screens: {
              HomeScreen: '/',
              ClassDetails: '/class/:classId',
              LiveStream: '/stream/:streamId',
            },
          },
          BrowseTab: {
            screens: {
              Browse: '/browse',
              Search: '/search/:query',
              ClassDetails: '/class/:classId',
            },
          },
          MyClassesTab: {
            screens: {
              MyClasses: '/my-classes',
              ClassDetails: '/class/:classId',
            },
          },
          ProfileTab: {
            screens: {
              ProfileScreen: '/profile',
              EditProfile: '/profile/edit',
              Settings: '/settings',
            },
          },
        },
      },
      Auth: {
        screens: {
          Login: '/login',
          Register: '/register',
          ForgotPassword: '/forgot-password',
        },
      },
    },
  },
};

/**
 * Helper function to get tab icon
 */
const getTabIcon = (routeName) => {
  switch (routeName) {
    case 'HomeTab':
      return '🏠';
    case 'BrowseTab':
      return '🎓';
    case 'MyClassesTab':
      return '📚';
    case 'ProfileTab':
      return '👤';
    default:
      return '•';
  }
};

/**
 * Helper function to get tab label
 */
const getTabLabel = (routeName) => {
  switch (routeName) {
    case 'HomeTab':
      return 'Home';
    case 'BrowseTab':
      return 'Browse';
    case 'MyClassesTab':
      return 'Classes';
    case 'ProfileTab':
      return 'Profile';
    default:
      return '';
  }
};

