/**
 * React Native - Video Player Component
 * HLS video player with quality selection and offline support
 */

import React, { useState, useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ActivityIndicator,
  SafeAreaView,
  Dimensions,
} from 'react-native';
import { Video } from 'expo-av';

const { width: screenWidth, height: screenHeight } = Dimensions.get('window');

const VideoPlayerScreen = ({ route, navigation }) => {
  const { videoUrl, title, hostName } = route.params;
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isMuted, setIsMuted] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [currentQuality, setCurrentQuality] = useState('auto');
  const [duration, setDuration] = useState(0);
  const [position, setPosition] = useState(0);
  const videoRef = useRef(null);

  const qualities = ['auto', '360p', '480p', '720p', '1080p'];

  const handlePlaybackStatusUpdate = (status) => {
    if (status.isLoaded) {
      setIsLoading(false);
      setDuration(status.durationMillis);
      setPosition(status.positionMillis);
    } else if (status.error) {
      console.error('Video error:', status.error);
    }
  };

  const togglePlayPause = async () => {
    if (videoRef.current) {
      if (isPlaying) {
        await videoRef.current.pauseAsync();
      } else {
        await videoRef.current.playAsync();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const toggleMute = async () => {
    if (videoRef.current) {
      await videoRef.current.setIsMutedAsync(!isMuted);
      setIsMuted(!isMuted);
    }
  };

  const toggleFullscreen = () => {
    setIsFullscreen(!isFullscreen);
  };

  const seek = async (ms) => {
    if (videoRef.current) {
      await videoRef.current.setPositionAsync(ms);
    }
  };

  const formatTime = (ms) => {
    if (!ms) return '0:00';
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
  };

  const containerStyle = isFullscreen
    ? [styles.container, styles.fullscreen]
    : styles.container;

  return (
    <SafeAreaView style={containerStyle}>
      <View style={[styles.videoContainer, isFullscreen && styles.fullscreenContainer]}>
        {/* Video Player */}
        <Video
          ref={videoRef}
          source={{ uri: videoUrl }}
          style={styles.video}
          rate={1.0}
          volume={1.0}
          isMuted={isMuted}
          resizeMode="contain"
          useNativeControls={false}
          onPlaybackStatusUpdate={handlePlaybackStatusUpdate}
        />

        {/* Loading Indicator */}
        {isLoading && (
          <View style={styles.loadingContainer}>
            <ActivityIndicator size="large" color="#fff" />
          </View>
        )}

        {/* Play/Pause Overlay */}
        <TouchableOpacity
          style={styles.playPauseButton}
          onPress={togglePlayPause}
          disabled={isLoading}
        >
          <Text style={styles.playPauseIcon}>
            {isPlaying ? '⏸' : '▶️'}
          </Text>
        </TouchableOpacity>

        {/* Video Controls */}
        <View style={styles.controls}>
          {/* Play Button */}
          <TouchableOpacity onPress={togglePlayPause} disabled={isLoading}>
            <Text style={styles.controlIcon}>
              {isPlaying ? '⏸' : '▶️'}
            </Text>
          </TouchableOpacity>

          {/* Time Display */}
          <View style={styles.timeDisplay}>
            <Text style={styles.timeText}>
              {formatTime(position)} / {formatTime(duration)}
            </Text>
          </View>

          {/* Quality Selector */}
          <TouchableOpacity onPress={() => setCurrentQuality(currentQuality)}>
            <Text style={styles.controlIcon}>⚙️</Text>
          </TouchableOpacity>

          {/* Mute Button */}
          <TouchableOpacity onPress={toggleMute}>
            <Text style={styles.controlIcon}>
              {isMuted ? '🔇' : '🔊'}
            </Text>
          </TouchableOpacity>

          {/* Fullscreen Button */}
          <TouchableOpacity onPress={toggleFullscreen}>
            <Text style={styles.controlIcon}>
              {isFullscreen ? '⛔' : '🖥️'}
            </Text>
          </TouchableOpacity>
        </View>

        {/* Progress Bar */}
        <View style={styles.progressContainer}>
          <View
            style={[
              styles.progressBar,
              {
                width:
                  duration > 0
                    ? `${(position / duration) * 100}%`
                    : '0%',
              },
            ]}
          />
        </View>
      </View>

      {/* Video Info */}
      {!isFullscreen && (
        <View style={styles.infoContainer}>
          <Text style={styles.title}>{title}</Text>
          <Text style={styles.host}>Host: {hostName}</Text>

          {/* Quality Selector Menu */}
          <View style={styles.qualityMenu}>
            <Text style={styles.qualityLabel}>Quality:</Text>
            <View style={styles.qualityOptions}>
              {qualities.map((q) => (
                <TouchableOpacity
                  key={q}
                  style={[
                    styles.qualityOption,
                    currentQuality === q && styles.qualityOptionActive,
                  ]}
                  onPress={() => setCurrentQuality(q)}
                >
                  <Text
                    style={[
                      styles.qualityText,
                      currentQuality === q && styles.qualityTextActive,
                    ]}
                  >
                    {q}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        </View>
      )}
    </SafeAreaView>
  );
};

