import { useEffect, useState, useCallback } from 'react';
import { useAuth } from './useAuth';
import api from '../utils/api';

export const usePushNotifications = () => {
  const { isAuthenticated } = useAuth();
  const [isSupported, setIsSupported] = useState(false);
  const [isSubscribed, setIsSubscribed] = useState(false);
  const [subscription, setSubscription] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  // Check if Push Notifications are supported
  useEffect(() => {
    const supported =
      'serviceWorker' in navigator &&
      'PushManager' in window &&
      'Notification' in window;
    setIsSupported(supported);
  }, []);

  // Check current subscription status
  useEffect(() => {
    if (!isSupported || !isAuthenticated) {
      return;
    }

    const checkSubscription = async () => {
      try {
        const registration = await navigator.serviceWorker.ready;
        const sub = await registration.pushManager.getSubscription();
        setSubscription(sub);
        setIsSubscribed(!!sub);
      } catch (err) {
        console.error('Error checking subscription:', err);
        setError(err.message);
      }
    };

    checkSubscription();
  }, [isSupported, isAuthenticated]);

  // Request notification permission
  const requestPermission = useCallback(async () => {
    if (!isSupported) {
      setError('Push notifications not supported');
      return false;
    }

    try {
      const permission = await Notification.requestPermission();
      return permission === 'granted';
    } catch (err) {
      console.error('Error requesting permission:', err);
      setError(err.message);
      return false;
    }
  }, [isSupported]);

  // Subscribe to push notifications
  const subscribe = useCallback(async () => {
    if (!isSupported || !isAuthenticated) {
      return false;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Check Notification permission
      const permission = Notification.permission;
      if (permission !== 'granted') {
        const granted = await requestPermission();
        if (!granted) {
          setError('Permission denied');
          setIsLoading(false);
          return false;
        }
      }

      // Get service worker registration
      const registration = await navigator.serviceWorker.ready;
      const vapidPublicKey = import.meta.env.VITE_VAPID_PUBLIC_KEY;

      if (!vapidPublicKey) {
        throw new Error('VITE_VAPID_PUBLIC_KEY is not configured');
      }

      // Check if already subscribed
      let sub = await registration.pushManager.getSubscription();
      if (!sub) {
        // Subscribe to push
        sub = await registration.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: convertVapidKey(vapidPublicKey),
        });
      }

      // Send subscription to server
      await api.post('/push/subscribe', {
        subscription: sub.toJSON(),
      });

      setSubscription(sub);
      setIsSubscribed(true);
      setIsLoading(false);
      return true;
    } catch (err) {
      console.error('Subscribe error:', err);
      setError(err.message);
      setIsLoading(false);
      return false;
    }
  }, [isSupported, isAuthenticated, requestPermission]);

  // Unsubscribe from push notifications
  const unsubscribe = useCallback(async () => {
    if (!isSupported || !subscription) {
      return false;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Send unsubscribe request to server
      await api.post('/push/unsubscribe', {
        subscription: subscription.toJSON(),
      });

      // Unsubscribe from push
      await subscription.unsubscribe();

      setSubscription(null);
      setIsSubscribed(false);
      setIsLoading(false);
      return true;
    } catch (err) {
      console.error('Unsubscribe error:', err);
      setError(err.message);
      setIsLoading(false);
      return false;
    }
  }, [isSupported, subscription]);

  // Send test notification
  const sendTestNotification = useCallback(async () => {
    if (!isAuthenticated) {
      return false;
    }

    try {
      await api.post('/push/send-test');
      return true;
    } catch (err) {
      console.error('Test notification error:', err);
      setError(err.message);
      return false;
    }
  }, [isAuthenticated]);

  return {
    isSupported,
    isSubscribed,
    subscription,
    isLoading,
    error,
    requestPermission,
    subscribe,
    unsubscribe,
    sendTestNotification,
  };
};

// Convert VAPID public key from base64 to Uint8Array
function convertVapidKey(vapidPublicKey) {
  if (!vapidPublicKey) {
    console.error('VAPID_PUBLIC_KEY not set in environment');
    return new Uint8Array();
  }

  const padding = 4 - (vapidPublicKey.length % 4);
  const paddedKey =
    vapidPublicKey +
    (padding !== 4 ? '='.repeat(padding) : '');

  const binaryString = atob(paddedKey);
  const bytes = new Uint8Array(binaryString.length);

  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  return bytes;
}

import { useEffect, useState, useCallback } from 'react';

export const useServiceWorker = () => {
  const [isSupported, setIsSupported] = useState(false);
  const [isReady, setIsReady] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const [registration, setRegistration] = useState(null);

  useEffect(() => {
    // Check if service workers are supported
    const supported = 'serviceWorker' in navigator;
    setIsSupported(supported);

    let updateIntervalId = null;

    if (!supported) return;

    // Register service worker
    navigator.serviceWorker.register('/sw.js', { scope: '/' })
      .then((reg) => {
        console.log('[App] Service Worker registered:', reg.scope);
        setRegistration(reg);
        setIsReady(true);

        // Check for updates periodically only in production to avoid dev-server noise
        if (import.meta.env.PROD) {
          updateIntervalId = window.setInterval(() => {
            reg.update().catch(() => {});
          }, 60000);
        }

        // Listen for updates
        reg.addEventListener('updatefound', () => {
          const newWorker = reg.installing;
          console.log('[App] New Service Worker installing...');

          newWorker.addEventListener('statechange', () => {
            if (newWorker.state === 'activated') {
              console.log('[App] New Service Worker activated');
              setUpdateAvailable(true);
            }
          });
        });
      })
      .catch((err) => {
        console.error('[App] Service Worker registration failed:', err);
        setIsReady(false);
      });

    // Listen for controller change (SW update applied)
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      console.log('[App] Service Worker controller changed (update applied)');
      setUpdateAvailable(false);
    });

    // Listen for messages from service worker
    navigator.serviceWorker.addEventListener('message', (event) => {
      const { type, data } = event.data;
      console.log('[App] Message from SW:', type);

      if (type === 'SYNC_START') {
        console.log('[App] Starting sync:', data);
      }

      if (type === 'SYNC_COMPLETE') {
        console.log('[App] Sync complete:', data);
      }
    });

    return () => {
      if (updateIntervalId) {
        window.clearInterval(updateIntervalId);
      }
    };
  }, []);

  // Skip waiting - immediately activate new SW version
  const skipWaiting = useCallback(() => {
    if (!registration?.waiting) return;

    console.log('[App] Requesting SW to skip waiting...');
    registration.waiting.postMessage({ type: 'SKIP_WAITING' });
  }, [registration]);

  // Clear all caches
  const clearCache = useCallback(async () => {
    if (!isReady) {
      console.error('[App] Service Worker not ready');
      return false;
    }

    return new Promise((resolve) => {
      const channel = new MessageChannel();
      
      channel.port1.onmessage = (event) => {
        console.log('[App] Cache clear response:', event.data);
        resolve(event.data.success);
      };

      if (navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage(
          { type: 'CLEAR_CACHE' },
          [channel.port2]
        );
      }
    });
  }, [isReady]);

  // Clear specific cache
  const clearNamedCache = useCallback(async (cacheName) => {
    if (!isReady) {
      console.error('[App] Service Worker not ready');
      return false;
    }

    return new Promise((resolve) => {
      const channel = new MessageChannel();
      
      channel.port1.onmessage = (event) => {
        console.log('[App] Named cache clear response:', event.data);
        resolve(event.data.success);
      };

      if (navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage(
          { type: 'CLEAR_CACHE_NAMED', data: cacheName },
          [channel.port2]
        );
      }
    });
  }, [isReady]);

  // Get cache statistics
  const getCacheStats = useCallback(async () => {
    if (!isReady) {
      console.error('[App] Service Worker not ready');
      return null;
    }

    return new Promise((resolve) => {
      const channel = new MessageChannel();
      
      channel.port1.onmessage = (event) => {
        console.log('[App] Cache stats:', event.data);
        resolve(event.data.data);
      };

      if (navigator.serviceWorker.controller) {
        navigator.serviceWorker.controller.postMessage(
          { type: 'GET_CACHE_STATS' },
          [channel.port2]
        );
      }
    });
  }, [isReady]);

  // Trigger background sync
  const triggerSync = useCallback(async (tag) => {
    if (!isReady || !registration) {
      console.error('[App] Service Worker not ready');
      return false;
    }

    try {
      await registration.sync.register(tag);
      console.log('[App] Background sync registered:', tag);
      return true;
    } catch (err) {
      console.error('[App] Background sync failed:', err);
      return false;
    }
  }, [isReady, registration]);

  return {
    isSupported,
    isReady,
    isUpdating,
    updateAvailable,
    registration,
    skipWaiting,
    clearCache,
    clearNamedCache,
    getCacheStats,
    triggerSync,
  };
};

