  });

  const [exportFormat, setExportFormat] = useState('csv');
  const [exporting, setExporting] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');

  useEffect(() => {
    fetchAnalytics();
  }, []);

  const fetchAnalytics = async () => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (filters.startDate) params.append('start', filters.startDate);
      if (filters.endDate) params.append('end', filters.endDate);
      if (filters.classId) params.append('classId', filters.classId);

      const res = await axios.get(`/api/analytics/engagement?${params}`);
      let data = res.data.data || [];
      
      // Filter by minimum count
      data = data.filter(d => d.count >= filters.minCount);
      
      // Sort by count descending
      data.sort((a, b) => b.count - a.count);
      
      setEngagement(data);
    } catch (err) {
      setError(err.response?.data?.message || err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const handleApplyFilter = () => {
    fetchAnalytics();
  };

  const handleExport = async () => {
    if (engagement.length === 0) {
      setError('No data to export');
      return;
    }
    setError('');
    setSuccessMessage('');
    setExporting(true);
    try {
      if (exportFormat === 'csv') {
        exportToCSV();
      } else if (exportFormat === 'json') {
        exportToJSON();
      }
      setSuccessMessage('Analytics exported successfully');
    } catch (err) {
      setError('Export failed: ' + err.message);
    } finally {
      setExporting(false);
    }
  };

  const exportToCSV = () => {
    const headers = ['Action', 'Count', 'Unique Users', 'Percentage', 'Timestamp'];
    const rows = engagement.map((e, idx) => [
      e.action,
      e.count,
      e.uniqueUsers,
      ((e.count / engagement.reduce((s, x) => s + x.count, 0)) * 100).toFixed(2) + '%',
      new Date().toISOString(),
    ]);

    const csv = [headers, ...rows].map(r => r.map(c => `"${c}"`).join(',')).join('\n');
    downloadFile(csv, `analytics_${new Date().getTime()}.csv`, 'text/csv');
  };

  const exportToJSON = () => {
    const total = engagement.reduce((s, e) => s + e.count, 0);
    const data = {
      exportDate: new Date().toISOString(),
      filters,
      summary: {
        totalEvents: total,
        totalActions: engagement.length,
        uniqueUsers: engagement.reduce((s, e) => s + e.uniqueUsers, 0),
        averageCount: (total / engagement.length).toFixed(2),
      },
      events: engagement.map(e => ({
        ...e,
        percentage: ((e.count / total) * 100).toFixed(2),
      })),
    };
    downloadFile(JSON.stringify(data, null, 2), `analytics_${new Date().getTime()}.json`, 'application/json');
  };

  const downloadFile = (content, filename, type) => {
    const blob = new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const totalEvents = engagement.reduce((s, e) => s + e.count, 0);
  const totalUsers = engagement.reduce((s, e) => s + e.uniqueUsers, 0);
  const topAction = engagement[0];

  return (
    <div className="admin-analytics-dashboard">
      <div className="admin-dashboard-header">
        <h1>📊 Platform Analytics Dashboard</h1>
        <p className="subtitle">Real-time event tracking and engagement metrics</p>
      </div>

      {/* Summary Cards */}
      <div className="analytics-summary-grid">
        <div className="summary-card metric-card">
          <div className="card-icon">📈</div>
          <div className="card-content">
            <h3>Total Events</h3>
            <p className="metric-value">{totalEvents.toLocaleString()}</p>
            <span className="metric-label">across all actions</span>
          </div>
        </div>
        <div className="summary-card metric-card">
          <div className="card-icon">👥</div>
          <div className="card-content">
            <h3>Unique Users</h3>
            <p className="metric-value">{totalUsers.toLocaleString()}</p>
            <span className="metric-label">active participants</span>
          </div>
        </div>
        <div className="summary-card metric-card">
          <div className="card-icon">🎯</div>
          <div className="card-content">
            <h3>Top Action</h3>
            <p className="metric-value">{topAction?.action || 'N/A'}</p>
            <span className="metric-label">{topAction?.count || 0} events</span>
          </div>
        </div>
        <div className="summary-card metric-card">
          <div className="card-icon">📊</div>
          <div className="card-content">
            <h3>Avg Events/User</h3>
            <p className="metric-value">{totalUsers > 0 ? (totalEvents / totalUsers).toFixed(2) : 0}</p>
            <span className="metric-label">engagement rate</span>
          </div>
        </div>
      </div>

      {/* Filters Section */}
      <div className="admin-filters-section">
        <h2>Filters & Export</h2>
        <div className="filters-container">
          <div className="filter-group">
            <label>Start Date</label>
            <input 
              type="date" 
              name="startDate" 
              value={filters.startDate}
              onChange={handleFilterChange}
            />
          </div>
          <div className="filter-group">
            <label>End Date</label>
            <input 
              type="date" 
              name="endDate" 
              value={filters.endDate}
              onChange={handleFilterChange}
            />
          </div>
          <div className="filter-group">
            <label>Class ID (Optional)</label>
            <input 
              type="text" 
              name="classId" 
              value={filters.classId}
              onChange={handleFilterChange}
              placeholder="Leave blank for all classes"
            />
          </div>
          <div className="filter-group">
            <label>Min Events</label>
            <input 
              type="number" 
              name="minCount"
              value={filters.minCount}
              onChange={handleFilterChange}
              min="0"
            />
          </div>
          <button 
            onClick={handleApplyFilter} 
            disabled={loading}
            className="btn-apply-filter"
          >
            {loading ? '⏳ Loading...' : '🔍 Apply Filters'}
          </button>
        </div>

        <div className="export-section">
          <div className="export-controls">
            <select 
              value={exportFormat} 
              onChange={(e) => setExportFormat(e.target.value)}
              className="export-select"
            >
              <option value="csv">📄 Export as CSV</option>
              <option value="json">📋 Export as JSON</option>
            </select>
            <button 
              onClick={handleExport} 
              disabled={exporting || engagement.length === 0}
              className="btn-export"
            >
              {exporting ? '⏳ Exporting...' : '💾 Export'}
            </button>
          </div>
        </div>
      </div>
 
      {error && (
        <MessageBanner
          type="error"
          title="Analytics export failed"
          message={error}
          onClose={() => setError('')}
        />
      )}
      {successMessage && (
        <MessageBanner
          type="success"
          title="Export complete"
          message={successMessage}
          onClose={() => setSuccessMessage('')}
        />
      )}

      {/* Data Table */}
      <div className="analytics-data-section">
        <h2>Event Breakdown</h2>
        {engagement.length === 0 ? (
          <div className="no-data-message">
            <p>📭 No events found for the selected date range</p>
          </div>
        ) : (
          <div className="table-wrapper">
            <table className="analytics-table">
              <thead>
                <tr>
                  <th>Rank</th>
                  <th>Action</th>
                  <th>Events</th>
                  <th>Unique Users</th>
                  <th>% of Total</th>
                  <th>Avg Users/Event</th>
                </tr>
              </thead>
              <tbody>
                {engagement.map((e, idx) => (
                  <tr key={idx} className={idx < 3 ? 'top-action' : ''}>
                    <td className="rank-cell">{idx + 1}</td>
                    <td className="action-cell">{e.action}</td>
                    <td className="count-cell">{e.count}</td>
                    <td className="users-cell">{e.uniqueUsers}</td>
                    <td className="percent-cell">
                      <div className="progress-bar">
                        <div 
                          className="progress-fill" 
                          style={{ width: `${(e.count / totalEvents) * 100}%` }}
                        ></div>
                        <span>{((e.count / totalEvents) * 100).toFixed(1)}%</span>
                      </div>
                    </td>
                    <td className="avg-cell">
                      {(e.count / e.uniqueUsers).toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Statistics Footer */}
      {engagement.length > 0 && (
        <div className="analytics-footer">
          <div className="footer-stat">
            <span className="stat-label">Total Records:</span>
            <span className="stat-value">{engagement.length}</span>
          </div>
          <div className="footer-stat">
            <span className="stat-label">Date Range:</span>
            <span className="stat-value">{filters.startDate} to {filters.endDate}</span>
          </div>
          <div className="footer-stat">
            <span className="stat-label">Last Updated:</span>
            <span className="stat-value">{new Date().toLocaleTimeString()}</span>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import api from '../utils/api';
import MessageBanner from '../components/MessageBanner';
import ConfirmDialog from '../components/ConfirmDialog';
import '../styles/AdminEmailJobs.css';

export default function AdminEmailJobs() {
  const [jobs, setJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [successMessage, setSuccessMessage] = useState(null);
  const [page, setPage] = useState(1);
  const [limit] = useState(25);

  const [selectedJob, setSelectedJob] = useState(null);
  const [jobLoading, setJobLoading] = useState(false);

  const [confirm, setConfirm] = useState({ open: false, title: '', message: '', onConfirm: null });

  const fetchJobs = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await api.get(`/admin/utilities/email-jobs?limit=${limit}&page=${page}`);
      setJobs(res.data.jobs || []);
    } catch (err) {
      setError(err.response?.data?.message || err.message || 'Failed to load jobs');
    } finally {
      setLoading(false);
    }
  };

  const openJob = async (jobId) => {
    setJobLoading(true);
    setError(null);
    setSuccessMessage(null);
    try {
      const res = await api.get(`/admin/utilities/email-jobs/${jobId}`);
      setSelectedJob(res.data.job);
    } catch (err) {
      setError('Failed to load job details: ' + (err.response?.data?.message || err.message));
    } finally {
      setJobLoading(false);
    }
  };

  const closeJob = () => setSelectedJob(null);

  const sendNow = (jobId) => {
    setConfirm({
      open: true,
      title: 'Send Email Now',
      message: 'Send this email now?',
      onConfirm: async () => {
        setConfirm({ open: false });
        setError(null);
        setSuccessMessage(null);
        try {
          await api.post(`/admin/utilities/email-jobs/${jobId}/send`);
          setSuccessMessage('Send attempted — check job status');
          fetchJobs();
          openJob(jobId);
        } catch (err) {
          setError('Failed to send job: ' + (err.response?.data?.error || err.message));
        }
      },
    });
  };

  useEffect(() => {
    fetchJobs();
  }, [page]);

  const retryJob = async (jobId) => {
    setError(null);
    setSuccessMessage(null);
    try {
      await api.post(`/admin/utilities/email-jobs/${jobId}/retry`);
      fetchJobs();
      setSuccessMessage('Job requeued');
    } catch (err) {
      setError('Failed to retry job: ' + (err.response?.data?.message || err.message));
    }
  };

  const runBadges = () => {
    setConfirm({
      open: true,
      title: 'Trigger Badge Engine',
      message: 'Trigger badge engine now?',
      onConfirm: async () => {
        setConfirm({ open: false });
        setError(null);
        setSuccessMessage(null);
        try {
          await api.post('/admin/utilities/run-badges');
          setSuccessMessage('Badge engine triggered');
        } catch (err) {
          setError('Failed to trigger badge engine: ' + (err.response?.data?.message || err.message));
        }
      },
    });
  };

  const retryAllFailed = () => {
    setConfirm({
      open: true,
      title: 'Requeue Failed Jobs',
      message: 'Requeue all failed email jobs?',
      onConfirm: async () => {
        setConfirm({ open: false });
        setError(null);
        setSuccessMessage(null);
        try {
          const res = await api.post('/admin/utilities/email-jobs/retry-all');
          setSuccessMessage(`Requeued ${res.data.modifiedCount || 0} jobs`);
          fetchJobs();
        } catch (err) {
          setError('Failed to requeue jobs: ' + (err.response?.data?.message || err.message));
        }
      },
    });
  };

  return (
    <div className="admin-email-jobs container">
      <div className="admin-email-jobs__header">
        <h1>Email Job Queue</h1>
        <div className="admin-email-jobs__actions">
          <button className="btn btn-primary" onClick={fetchJobs}>Refresh</button>
          <button className="btn" onClick={runBadges}>Run Badge Engine</button>
        </div>
      </div>

      {loading && <div>Loading jobs...</div>}
      {error && (
        <MessageBanner
          type="error"
          title="Email jobs error"
          message={error}
          onClose={() => setError(null)}
        />
      )}
      {successMessage && (
        <MessageBanner
          type="success"
          title="Email jobs"
          message={successMessage}
          onClose={() => setSuccessMessage(null)}
        />
      )}

      <ConfirmDialog
        open={confirm.open}
        title={confirm.title}
        message={confirm.message}
        onConfirm={confirm.onConfirm}
        onCancel={() => setConfirm({ open: false })}
      />

      {!loading && !error && (
        <div>
        <table className="admin-email-jobs__table">
          <thead>
            <tr>
              <th>ID</th>
              <th>To</th>
              <th>Subject</th>
              <th>Status</th>
              <th>Attempts</th>
              <th>Created At</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {jobs.map(job => (
              <tr key={job._id}>
                <td>{job._id}</td>
                <td>{job.to}</td>
                <td>{job.subject}</td>
                <td>{job.status}</td>
                <td>{job.attempts}</td>
                <td>{new Date(job.createdAt).toLocaleString()}</td>
                <td>
                  <button className="btn" onClick={() => openJob(job._id)}>View</button>
                  {job.status !== 'pending' && (
                    <button className="btn" onClick={() => retryJob(job._id)}>Retry</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Job detail modal */}
        {selectedJob && (
          <>
            <div className="job-overlay" onClick={closeJob}></div>
            <div className="job-modal" role="dialog" aria-modal="true">
              <div className="job-modal__header">
                <h3>Job: {selectedJob._id}</h3>
                <div>
                  <button className="btn" onClick={() => retryJob(selectedJob._id)}>Retry</button>
                  <button className="btn btn-primary" onClick={() => sendNow(selectedJob._id)}>Send Now</button>
                  <button className="btn" onClick={closeJob}>Close</button>
                </div>
              </div>
              <div className="job-modal__body">
                <div><strong>To:</strong> {selectedJob.to}</div>
                <div><strong>Subject:</strong> {selectedJob.subject}</div>
                <div><strong>Status:</strong> {selectedJob.status}</div>
                <div><strong>Attempts:</strong> {selectedJob.attempts}</div>
                <div><strong>Last Error:</strong> <span style={{color:'#c00'}}>{selectedJob.lastError || 'None'}</span></div>
                <div style={{marginTop:8}}><strong>Payload / Template Data</strong></div>
                <pre className="job-modal__pre">{JSON.stringify(selectedJob.data || { body: selectedJob.body }, null, 2)}</pre>
                {selectedJob.body && (
                  <>
                    <div style={{marginTop:8}}><strong>Rendered Body</strong></div>
                    <div className="job-modal__pre">{selectedJob.body}</div>
                  </>
                )}
              </div>
            </div>
          </>
        )}

        </div>
        )}

        <div className="admin-email-jobs__pagination">
          <button className="btn" disabled={page <= 1} onClick={() => setPage(p => p - 1)}>Previous</button>
          <span>Page {page}</span>
          <button className="btn" onClick={() => setPage(p => p + 1)}>Next</button>
        </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAdmin } from '../context/AdminContext';
import HostDetailsModal from '../components/HostDetailsModal';
import HostApprovalModal from '../components/HostApprovalModal';
import HostSuspensionModal from '../components/HostSuspensionModal';
import '../styles/admin-hosts.css';

const AdminHosts = () => {
  const {
    fetchAllHosts,
    fetchPendingHosts,
    fetchTopPerformers,
    fetchAtRiskHosts,
    fetchHostDetails,
    fetchHostPerformance
  } = useAdmin();

  const [activeTab, setActiveTab] = useState('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // All hosts state
  const [hosts, setHosts] = useState([]);
  const [hostPage, setHostPage] = useState(1);
  const [hostFilters, setHostFilters] = useState({
    status: 'all',
    search: ''
  });

  // Pending hosts
  const [pendingHosts, setPendingHosts] = useState([]);

  // Top performers
  const [topPerformers, setTopPerformers] = useState([]);

  // At-risk hosts
  const [atRiskHosts, setAtRiskHosts] = useState([]);

  // Modal state
  const [selectedHost, setSelectedHost] = useState(null);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [showApprovalModal, setShowApprovalModal] = useState(false);
  const [showSuspensionModal, setShowSuspensionModal] = useState(false);
  const [approvalAction, setApprovalAction] = useState('approve'); // 'approve' or 'reject'
  const [suspensionAction, setSuspensionAction] = useState('suspend'); // 'suspend' or 'unsuspend'

  // Load data on mount and tab change
  useEffect(() => {
    loadTabData();
  }, [activeTab]);

  const loadTabData = async () => {
    setLoading(true);
    setError(null);
    try {
      if (activeTab === 'all') {
        const result = await fetchAllHosts(hostPage, hostFilters);
        setHosts(result?.data || []);
      } else if (activeTab === 'pending') {
        const result = await fetchPendingHosts();
        setPendingHosts(result?.data || []);
      } else if (activeTab === 'top-performers') {
        const result = await fetchTopPerformers();
        setTopPerformers(result?.data || []);
      } else if (activeTab === 'at-risk') {
        const result = await fetchAtRiskHosts();
        setAtRiskHosts(result?.data || []);
      }
    } catch (err) {
      setError(err.message || 'Failed to load data');
      console.error('Error loading host data:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleHostClick = async (host) => {
    try {
      const details = await fetchHostDetails(host._id || host.hostId);
      const performance = await fetchHostPerformance(host._id || host.hostId);
      setSelectedHost({ ...details.host, ...performance });
      setShowDetailsModal(true);
    } catch (err) {
      setError('Failed to load host details');
    }
  };

  const handleApprove = (host) => {
    setSelectedHost(host);
    setApprovalAction('approve');
    setShowApprovalModal(true);
  };

  const handleReject = (host) => {
    setSelectedHost(host);
    setApprovalAction('reject');
    setShowApprovalModal(true);
  };

  const handleSuspend = (host) => {
    setSelectedHost(host);
    setSuspensionAction('suspend');
    setShowSuspensionModal(true);
  };

  const handleUnsuspend = (host) => {
    setSelectedHost(host);
    setSuspensionAction('unsuspend');
    setShowSuspensionModal(true);
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setHostFilters(prev => ({
      ...prev,
      [name]: value
    }));
    setHostPage(1);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved':
        return '#22c55e';
      case 'pending':
        return '#f59e0b';
      case 'suspended':
        return '#ef4444';
      case 'rejected':
        return '#6b7280';
      default:
        return '#3b82f6';
    }
  };

  const renderHostTable = (data, showActions = true) => {
    if (data.length === 0) {
      return <div style={{ textAlign: 'center', padding: '40px', color: '#999' }}>No hosts found</div>;
    }

    return (
      <div className="table-wrapper">
        <table className="data-table">
          <thead>
            <tr>
              <th>Host Name</th>
              <th>Email</th>
              <th>Status</th>
              <th>Plan Tier</th>
              <th>Revenue</th>
              <th>Classes</th>
              <th>Students</th>
              <th>Rating</th>
              {showActions && <th>Actions</th>}
            </tr>
          </thead>
          <tbody>
            {data.map(host => (
              <tr key={host._id || host.hostId}>
                <td onClick={() => handleHostClick(host)} style={{ cursor: 'pointer', color: '#3b82f6' }}>
                  {host.hostName || host.name}
                </td>
                <td>{host.email}</td>
                <td>
                  <span
                    className="status-badge"
                    style={{
                      background: getStatusColor(host.status),
                      color: 'white',
                      padding: '4px 12px',
                      borderRadius: '20px',
                      fontSize: '12px',
                      fontWeight: '600'
                    }}
                  >
                    {host.status?.toUpperCase() || 'UNKNOWN'}
                  </span>
                </td>
                <td>{host.planTier || 'Starter'}</td>
                <td>${(host.totalRevenue || 0).toFixed(2)}</td>
                <td>{host.classCount || 0}</td>
                <td>{host.studentCount || 0}</td>
                <td>
                  <span style={{ fontWeight: '600' }}>
                    ⭐ {(host.rating || 0).toFixed(1)}
                  </span>
                </td>
                {showActions && (
                  <td>
                    <div style={{ display: 'flex', gap: '6px' }}>
                      {host.status === 'pending' && (
                        <>
                          <button
                            className="action-btn approve"
                            onClick={() => handleApprove(host)}
                            title="Approve"
                          >
                            ✓
                          </button>
                          <button
                            className="action-btn reject"
                            onClick={() => handleReject(host)}
                            title="Reject"
                          >
                            ✕
                          </button>
                        </>
                      )}
                      {host.status === 'approved' && (
                        <button
                          className="action-btn suspend"
                          onClick={() => handleSuspend(host)}
                          title="Suspend"
                        >
                          🔒
                        </button>
                      )}
                      {host.status === 'suspended' && (
                        <button
                          className="action-btn unsuspend"
                          onClick={() => handleUnsuspend(host)}
                          title="Unsuspend"
                        >
                          🔓
                        </button>
                      )}
                    </div>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div className="admin-hosts">
      <style>{`
        .admin-hosts {
          padding: 30px;
          background: #f5f7fa;
          min-height: 100vh;
        }

        .hosts-header {
          margin-bottom: 30px;
        }

        .hosts-header h1 {
          font-size: 28px;
          color: #1a1a1a;
          margin: 0 0 10px 0;
          font-weight: 700;
        }

        .hosts-header p {
          color: #666;
          margin: 0;
          font-size: 14px;
        }

