  const durationRef = useRef(null);

  // Get auth token
  const token = localStorage.getItem('token');

  // Initialize socket.io connection
  useEffect(() => {
    if (!token) {
      navigate('/login');
      return;
    }

    socketRef.current = io(import.meta.env.VITE_API_URL || 'http://localhost:5000', {
      auth: { token },
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      reconnectionAttempts: 5,
    });

    return () => {
      if (socketRef.current) {
        socketRef.current.disconnect();
      }
    };
  }, [token, navigate]);

  // Handle viewer count updates via Socket.io
  useEffect(() => {
    if (!socketRef.current || !stream) return;

    socketRef.current.on('stream:viewer-update', (data) => {
      setViewers(data.totalViewers);
      if (data.totalViewers > peakViewers) {
        setPeakViewers(data.totalViewers);
      }
    });

    return () => {
      if (socketRef.current) {
        socketRef.current.off('stream:viewer-update');
      }
    };
  }, [stream, peakViewers]);

  // Fetch stream stats periodically
  useEffect(() => {
    if (!stream || !isLive) return;

    const interval = setInterval(async () => {
      try {
        const res = await axios.get(
          `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${stream._id}/stats`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setViewers(res.data.stats.currentViewers);
        setPeakViewers(res.data.stats.peakViewers);
        setTotalViewers(res.data.stats.totalViewers);
        setAvgWatchTime(res.data.stats.avgWatchTime || 0);
      } catch (err) {
        console.error('Error fetching stats:', err);
      }
    }, 5000); // Update every 5 seconds

    return () => clearInterval(interval);
  }, [stream, isLive, token]);

  // Timer for stream duration
  useEffect(() => {
    if (!isLive) {
      if (durationRef.current) clearInterval(durationRef.current);
      return;
    }

    durationRef.current = setInterval(() => {
      setStreamDuration((prev) => prev + 1);
    }, 1000);

    return () => {
      if (durationRef.current) clearInterval(durationRef.current);
    };
  }, [isLive]);

  // Format duration as MM:SS or HH:MM:SS
  const formatDuration = (seconds) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    if (hours > 0) {
      return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
    }
    return `${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  // Create stream
  const handleCreateStream = async (title, description, duration) => {
    try {
      setLoading(true);
      setError(null);

      const res = await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live`,
        {
          classId,
          title,
          description,
          duration: duration || 60,
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setStream(res.data.liveStream);
      setStreamTitle(title);
      setStreamDescription(description);
      setError(null);
    } catch (err) {
      const message = err.response?.data?.message || 'Failed to create stream';
      setError(message);
      console.error('Error creating stream:', err);
    } finally {
      setLoading(false);
    }
  };

  // Start streaming
  const handleStartStream = async () => {
    try {
      setLoading(true);
      setError(null);

      const qualityConfig = {
        bitrates: [
          { level: '1080p', bitrate: 6000, resolution: '1920x1080' },
          { level: '720p', bitrate: 3000, resolution: '1280x720' },
          { level: '480p', bitrate: 1500, resolution: '854x480' },
        ],
        targetFps: 30,
        enableAdaptive: true,
      };

      const res = await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${stream._id}/start`,
        { quality: qualityConfig },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setStream(res.data.liveStream);
      setIsLive(true);
      setStreamDuration(0);
      setViewers(0);
      setPeakViewers(0);

      // Notify viewers via Socket.io
      if (socketRef.current) {
        socketRef.current.emit('stream:started', {
          streamId: res.data.liveStream._id,
          quality: qualityConfig,
        });
      }

      setError(null);
    } catch (err) {
      const message = err.response?.data?.message || 'Failed to start stream';
      setError(message);
      console.error('Error starting stream:', err);
    } finally {
      setLoading(false);
    }
  };

  // Stop streaming
  const handleStopStream = async () => {
    try {
      setLoading(true);
      setError(null);

      const res = await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${stream._id}/stop`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );

      setStream(res.data.liveStream);
      setIsLive(false);

      // Notify viewers via Socket.io
      if (socketRef.current) {
        socketRef.current.emit('stream:stopped', {
          streamId: stream._id,
        });
      }

      setError(null);
    } catch (err) {
      const message = err.response?.data?.message || 'Failed to stop stream';
      setError(message);
      console.error('Error stopping stream:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="live-stream-host">
      <div className="container">
        <header className="host-header">
          <h1>🎬 Go Live</h1>
          <p>Broadcast your class to students in real-time</p>
        </header>

        {error && (
          <div className="error-message">
            <span>⚠️ {error}</span>
            <button onClick={() => setError(null)}>✕</button>
          </div>
        )}

        {!stream ? (
          <div className="setup-section">
            <StreamSettings onCreateStream={handleCreateStream} loading={loading} />
          </div>
        ) : (
          <div className="streaming-section">
            {/* Status Bar */}
            <div className="status-bar">
              <div className="status-group">
                <div className={`status-badge ${isLive ? 'live' : 'offline'}`}>
                  <span className="status-dot"></span>
                  {isLive ? '🔴 LIVE' : '⚫ OFFLINE'}
                </div>

                {isLive && (
                  <div className="duration-display">
                    ⏱️ {formatDuration(streamDuration)}
                  </div>
                )}
              </div>

              <div className="title-display">
                <h2>{streamTitle}</h2>
              </div>

              <div className="status-group">
                <div className="viewer-count">
                  👥 {viewers} {viewers === 1 ? 'viewer' : 'viewers'}
                </div>
              </div>
            </div>

            {/* Controls */}
            <div className="controls-section">
              <StreamControls
                isLive={isLive}
                loading={loading}
                onStart={handleStartStream}
                onStop={handleStopStream}
                qualityLevel={qualityLevel}
                onQualityChange={setQualityLevel}
              />
            </div>

            {/* Stats Display */}
            {isLive && (
              <div className="stats-section">
                <ViewerStats
                  currentViewers={viewers}
                  peakViewers={peakViewers}
                  totalViewers={totalViewers}
                  avgWatchTime={avgWatchTime}
                  duration={streamDuration}
                />
              </div>
            )}

            {/* RTMP Info (for OBS/encoders) */}
            {isLive && stream.playbackUrl && (
              <div className="rtmp-info">
                <h3>📡 Streaming Information</h3>
                <div className="info-group">
                  <label>RTMP URL:</label>
                  <code>{stream.rtmpUrl || 'rtmps://live.cloudflare.com:443/live/'}</code>
                </div>
                <div className="info-group">
                  <label>Stream Key:</label>
                  <code>{stream.streamKey}</code>
                </div>
                <div className="info-group">
                  <label>Playback URL:</label>
                  <code>{stream.playbackUrl}</code>
                </div>
                <p className="info-text">
                  Use the RTMP URL and Stream Key to configure your encoder (OBS, FFmpeg, etc.)
                </p>
              </div>
            )}

            {/* End Stream Button */}
            {stream && (
              <div className="stream-actions">
                <button
                  className="btn-secondary"
                  onClick={() => {
                    setStream(null);
                    setIsLive(false);
                    setStreamDuration(0);
                  }}
                >
                  ← Back to Setup
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import io from 'socket.io-client';
import HLSPlayer from '../components/HLSPlayer';
import ViewerChat from '../components/ViewerChat';
import StreamMetadata from '../components/StreamMetadata';
import QualitySelector from '../components/QualitySelector';
import '../styles/LiveStreamViewer.css';

export default function LiveStreamViewer() {
  const { streamId } = useParams();
  const navigate = useNavigate();
  const socketRef = useRef(null);

  // Stream state
  const [stream, setStream] = useState(null);
  const [isLive, setIsLive] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Viewer stats
  const [viewers, setViewers] = useState(0);
  const [watchTime, setWatchTime] = useState(0);

  // Chat state
  const [messages, setMessages] = useState([]);
  const [isChatBlocked, setIsChatBlocked] = useState(false);
  const [blockReason, setBlockReason] = useState('');

  // Quality state
  const [selectedQuality, setSelectedQuality] = useState('auto');
  const [availableQualities, setAvailableQualities] = useState([]);

  // Engagement tracking
  const [engagement, setEngagement] = useState(0);
  const joinedAtRef = useRef(Date.now());
  const watchTimeRef = useRef(null);

  // Get auth token
  const token = localStorage.getItem('token');

  // Fetch stream details on mount
  useEffect(() => {
    const fetchStream = async () => {
      try {
        setLoading(true);
        const response = await axios.get(
          `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/streams/${streamId}`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setStream(response.data);
        setIsLive(response.data.status === 'live');
        
        // Set available qualities from stream config
        if (response.data.quality?.bitrates) {
          setAvailableQualities(response.data.quality.bitrates);
        }
        
        // Fetch chat history
        fetchChatHistory();
      } catch (err) {
        console.error('Failed to fetch stream:', err);
        setError('Failed to load stream. Stream may not exist or be archived.');
        setTimeout(() => navigate('/'), 5000);
      } finally {
        setLoading(false);
      }
    };

    if (streamId) {
      fetchStream();
    }
  }, [streamId, token, navigate]);

  // Track viewer join
  useEffect(() => {
    const trackJoin = async () => {
      try {
        await axios.post(
          `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/viewer-join`,
          {
            qualitySelected: selectedQuality,
            browser: getBrowserInfo(),
            os: getOSInfo()
          },
          { headers: { Authorization: `Bearer ${token}` } }
        );
      } catch (err) {
        console.error('Failed to track viewer join:', err);
      }
    };

    if (stream && token) {
      trackJoin();
    }
  }, [stream, streamId, token, selectedQuality]);

  // Initialize Socket.io connection
  useEffect(() => {
    if (!stream || !token) return;

    socketRef.current = io(import.meta.env.VITE_API_URL || 'http://localhost:5000', {
      auth: { token },
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
    });

    // Join stream room
    socketRef.current.emit('stream:join', { streamId });

    // Listen for real-time updates
    socketRef.current.on('stream:viewer-update', (data) => {
      setViewers(data.totalViewers || 0);
    });

    socketRef.current.on('stream:chat-message', (data) => {
      setMessages((prev) => [...prev, data]);
      // Calculate engagement based on chat activity
      setEngagement((prev) => Math.min(prev + 5, 100));
    });

    socketRef.current.on('stream:stats', (data) => {
      if (data.streamHealth?.qualityAvailable) {
        setAvailableQualities(data.streamHealth.qualityAvailable);
      }
    });

    socketRef.current.on('stream:stopped', () => {
      setIsLive(false);
      setTimeout(() => {
        setError('This stream has ended.');
      }, 500);
    });

    socketRef.current.on('stream:quality', (data) => {
      if (data.availableLevels) {
        setAvailableQualities(data.availableLevels);
      }
    });

    return () => {
      if (socketRef.current) {
        socketRef.current.emit('stream:leave', { streamId });
        socketRef.current.disconnect();
      }
    };
  }, [stream, streamId, token]);

  // Start watch time timer
  useEffect(() => {
    watchTimeRef.current = setInterval(() => {
      const elapsed = Math.floor((Date.now() - joinedAtRef.current) / 1000);
      setWatchTime(elapsed);
      
      // Calculate engagement based on watch time
      if (elapsed > 0) {
        setEngagement((prev) => Math.min(prev + 0.5, 100));
      }
    }, 1000);

    return () => clearInterval(watchTimeRef.current);
  }, []);

  // Fetch chat history
  const fetchChatHistory = async () => {
    try {
      const response = await axios.get(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/chat?limit=50`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setMessages(response.data || []);
    } catch (err) {
      console.error('Failed to fetch chat history:', err);
    }
  };

  // Handle sending message
  const handleSendMessage = async (messageText) => {
    try {
      const response = await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/chat`,
        { message: messageText },
        { headers: { Authorization: `Bearer ${token}` } }
      );

      if (response.status === 403) {
        setIsChatBlocked(true);
        setBlockReason(response.data?.reason || 'You are temporarily muted');
        setTimeout(() => setIsChatBlocked(false), 60000); // 1 minute timeout
      } else {
        // Message sent successfully, increment engagement
        setEngagement((prev) => Math.min(prev + 10, 100));
      }
    } catch (err) {
      if (err.response?.status === 403) {
        setIsChatBlocked(true);
        setBlockReason(err.response.data?.reason || 'You are temporarily muted');
      } else {
        console.error('Failed to send message:', err);
      }
    }
  };

  // Handle quality change
  const handleQualityChange = (quality) => {
    setSelectedQuality(quality);
    if (socketRef.current) {
      socketRef.current.emit('stream:quality', { streamId, quality });
    }
  };

  // Track viewer leave
  const handleBeforeUnload = async () => {
    try {
      await axios.post(
        `${import.meta.env.VITE_API_URL || 'http://localhost:5000'}/api/live/${streamId}/viewer-leave`,
        {
          watchTime,
          engagement: Math.round(engagement)
        },
        { headers: { Authorization: `Bearer ${token}` } }
      );
    } catch (err) {
      console.error('Failed to track viewer leave:', err);
    }
  };

  useEffect(() => {
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [watchTime, engagement, streamId, token]);

  if (loading) {
    return (
      <div className="livestream-viewer-loading">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading stream...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="livestream-viewer-error">
        <div className="error-message">
          <h2>⚠️ Unable to Load Stream</h2>
          <p>{error}</p>
          <p style={{ fontSize: '0.9rem', color: '#999' }}>Redirecting to home...</p>
        </div>
      </div>
    );
  }

  if (!stream) {
    return (
      <div className="livestream-viewer-error">
        <div className="error-message">
          <h2>Stream not found</h2>
          <p>The stream you're looking for doesn't exist.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="livestream-viewer-page">
      <div className="video-section">
        <HLSPlayer
          streamId={streamId}
          quality={selectedQuality}
          onQualityChange={handleQualityChange}
          isLive={isLive}
        />

        <StreamMetadata
          title={stream.title}
          description={stream.description}
          hostName={stream.hostName}
          hostAvatar={stream.hostAvatar}
          viewers={viewers}
          category={stream.category}
          startedAt={stream.startedAt}
          isLive={isLive}
        />
      </div>

      <div className="sidebar">
        <QualitySelector
          options={availableQualities}
          selected={selectedQuality}
          onChange={handleQualityChange}
        />

        <div className="viewer-stats-card">
          <h3>Stream Info</h3>
          <div className="stat-item">
            <span className="label">Current Viewers</span>
            <span className="value">{viewers}</span>
          </div>
          <div className="stat-item">
            <span className="label">Watch Time</span>
            <span className="value">{formatWatchTime(watchTime)}</span>
          </div>
          <div className="stat-item">
            <span className="label">Engagement</span>
            <div className="engagement-bar">
              <div className="engagement-fill" style={{ width: `${engagement}%` }}></div>
            </div>
          </div>
          <div className="stat-item">
            <span className="label">Status</span>
            <span className={`status-badge ${isLive ? 'live' : 'ended'}`}>
              {isLive ? '🔴 Live' : '⚫ Ended'}
            </span>
          </div>
        </div>
      </div>

      <div className="chat-section">
        <ViewerChat
          streamId={streamId}
          messages={messages}
          onSendMessage={handleSendMessage}
          isModerated={stream.chatModerated}
          isBlocked={isChatBlocked}
          blockReason={blockReason}
        />
      </div>
    </div>
  );
}

// Utility functions
function formatWatchTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes}m`;
  } else if (minutes > 0) {
    return `${minutes}m ${secs}s`;
  } else {
    return `${secs}s`;
  }
}

function getBrowserInfo() {
  const ua = navigator.userAgent;
  if (ua.includes('Chrome')) return 'Chrome';
  if (ua.includes('Firefox')) return 'Firefox';
  if (ua.includes('Safari')) return 'Safari';
  if (ua.includes('Edge')) return 'Edge';
  return 'Unknown';
}

function getOSInfo() {
  const ua = navigator.userAgent;
  if (ua.includes('Windows')) return 'Windows';
  if (ua.includes('Mac')) return 'MacOS';
  if (ua.includes('Linux')) return 'Linux';
  if (ua.includes('iPhone') || ua.includes('iPad')) return 'iOS';
  if (ua.includes('Android')) return 'Android';
  return 'Unknown';
}

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import '../styles/Auth.css';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      await login(email, password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-container">
        <h2>Login</h2>

        {error && <div className="error-message">{error}</div>}

        <form onSubmit={handleSubmit} className="auth-form">
          <div className="form-group">
            <label htmlFor="login-email">Email</label>
            <input
              id="login-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              placeholder="your@email.com"
            />
          </div>

          <div className="form-group">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              placeholder="Enter your password"
            />
          </div>

          <button type="submit" disabled={loading} className="submit-button">
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>

        <p className="auth-footer">
          Don't have an account? <Link to="/signup">Sign up here</Link>
        </p>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import api from '../utils/api';
import { useAuth } from '../hooks/useAuth';
import '../styles/Notifications.css';
import { Link } from 'react-router-dom';

export default function Notifications() {
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();

  useEffect(() => {
    fetchNotifications();
  }, []);

  const fetchNotifications = async () => {
    try {
      const response = await api.get('/notifications?limit=20');
      setNotifications(response.data.notifications);
      setUnreadCount(response.data.unreadCount);
    } catch (error) {
      console.error('Failed to fetch notifications:', error);
    } finally {
      setLoading(false);
    }
  };

  const markAsRead = async (notificationId) => {
    try {
      await api.put(`/notifications/${notificationId}/read`);
      fetchNotifications();
    } catch (error) {
      console.error('Failed to mark notification as read:', error);
    }
  };

  const markAllAsRead = async () => {
    try {
      await api.put('/notifications/read-all');
      fetchNotifications();
    } catch (error) {
      console.error('Failed to mark all as read:', error);
    }
  };

  const deleteNotification = async (notificationId) => {
    try {
      await api.delete(`/notifications/${notificationId}`);
      fetchNotifications();
    } catch (error) {
      console.error('Failed to delete notification:', error);
    }
  };

  const getNotificationIcon = (type) => {
    const icons = {
      payment_confirmation: '✅',
      session_reminder: '⏰',
      subscription_expiry: '⚠️',
      auto_renewal: '🔄',
      renewal_failed: '❌',
      host_no_show: '😞',
      refund_confirmation: '💰',
      class_cancellation: '🚫',
      plan_upgrade: '⭐',
      referral_reward: '🎁',
      waitlist_available: '🎯',
      new_review: '⭐',
      class_announcement: '📢',
      recording_ready: '🎥',
      achievement_unlocked: '🏅',
    };
    return icons[type] || '📬';
  };

  if (loading) {
    return <div className="loading">Loading notifications...</div>;
  }

  return (
    <div className="notifications-page">
      <div className="container">
        <div className="notifications-header">
          <h1>Notifications</h1>
          {unreadCount > 0 && (
            <div className="unread-badge">{unreadCount} unread</div>
          )}
          {unreadCount > 0 && (
            <button onClick={markAllAsRead} className="btn btn-secondary">
              Mark all as read
            </button>
          )}
        </div>

        {notifications.length > 0 ? (
          <div className="notifications-list">
            {notifications.map((notif) => (
              <div
                key={notif._id}
                className={`notification-item ${!notif.read ? 'unread' : ''}`}
              >
                <div className="notification-icon">
                  {getNotificationIcon(notif.type)}
                </div>

                <div className="notification-content">
                  <div className="notification-title">
                    {notif.title}
                  </div>
                  <div className="notification-message">
                    {notif.message}
                  </div>
                  {notif.type === 'achievement_unlocked' && notif.metadata && (
                    <div className="notification-achievement">
                      <strong>Points:</strong> +{notif.metadata.points || 0}
                      {notif.metadata.achievementId && (
                        <Link to="/achievements" className="view-achievement-link"> View</Link>
                      )}
                    </div>
                  )}
                  <div className="notification-time">
                    {new Date(notif.createdAt).toLocaleString()}
                  </div>
                </div>

                <div className="notification-actions">
                  {!notif.read && (
                    <button
                      onClick={() => markAsRead(notif._id)}
                      className="action-btn"
                      title="Mark as read"
                    >
                      ✓
                    </button>
                  )}
                  <button
                    onClick={() => deleteNotification(notif._id)}
                    className="action-btn delete"
                    title="Delete"
                  >
                    ×
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="no-notifications">
            <p>📭 No notifications yet</p>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useAuth } from '../hooks/useAuth';
import { api } from '../utils/api';
import ScheduledStreamsDashboard from '../components/ScheduledStreamsDashboard';
import '../styles/ScheduledStreamsPage.css';

export default function ScheduledStreamsPage() {
  const { user } = useAuth();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    classId: '',
    scheduledStartTime: '',
    scheduledEndTime: '',
    recurrence: 'once',
    reminders: {
      '24h': false,
      '1h': false,
      '30m': false
    }
  });
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    fetchHostClasses();
  }, [user?.id]);

  const fetchHostClasses = async () => {
    try {
      const response = await api.get('/classes/host/my-classes');
      setClasses(response.data || []);
    } catch (err) {
      console.error('Error fetching classes:', err);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleReminderToggle = (reminderTime) => {
    setFormData(prev => ({
      ...prev,
      reminders: {
        ...prev.reminders,
        [reminderTime]: !prev.reminders[reminderTime]
      }
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.title || !formData.classId || !formData.scheduledStartTime) {
      setMessage({ type: 'error', text: 'Please fill in all required fields' });
      return;
    }

    try {
      setLoading(true);
      const scheduleData = {
        ...formData,
        hostId: user?.id,
        status: 'scheduled'
      };

      const response = await api.post('/schedules', scheduleData);
      
      setMessage({ type: 'success', text: 'Schedule created successfully!' });
      
      // Reset form
      setFormData({
        title: '',
        description: '',
        classId: '',
        scheduledStartTime: '',
        scheduledEndTime: '',
        recurrence: 'once',
        reminders: {
          '24h': false,
          '1h': false,
          '30m': false
        }
      });

      // Refresh dashboard
      setRefreshKey(prev => prev + 1);

      // Clear message after 3 seconds
      setTimeout(() => setMessage({ type: '', text: '' }), 3000);
    } catch (err) {
      console.error('Error creating schedule:', err);
      setMessage({ 
        type: 'error', 
        text: err.response?.data?.message || 'Failed to create schedule' 
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="scheduled-streams-page">
      <div className="page-header">
        <h1>📅 Scheduled Streams</h1>
        <p>Create and manage your scheduled classes</p>
      </div>

      <div className="page-container">
        {/* Left Panel: Form */}
        <div className="form-panel">
          <div className="form-card">
            <h2>Create New Schedule</h2>
            
            {message.text && (
              <div className={`message ${message.type}`}>
                {message.type === 'success' ? '✓' : '✕'} {message.text}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              {/* Title */}
              <div className="form-group">
                <label htmlFor="title">
                  📝 Title <span className="required">*</span>
                </label>
                <input
                  type="text"
                  id="title"
                  name="title"
                  value={formData.title}
                  onChange={handleInputChange}
                  placeholder="Enter stream title"
                  maxLength="100"
                />
              </div>

              {/* Description */}
              <div className="form-group">
                <label htmlFor="description">📋 Description</label>
                <textarea
                  id="description"
                  name="description"
                  value={formData.description}
                  onChange={handleInputChange}
                  placeholder="What will this stream be about?"
                  rows="3"
                  maxLength="500"
                />
              </div>

              {/* Class Selection */}
              <div className="form-group">
                <label htmlFor="classId">
                  🎓 Select Class <span className="required">*</span>
                </label>
                <select
                  id="classId"
                  name="classId"
                  value={formData.classId}
                  onChange={handleInputChange}
                >
                  <option value="">-- Choose a class --</option>
                  {classes.map(cls => (
                    <option key={cls._id} value={cls._id}>
                      {cls.title}
                    </option>
                  ))}
                </select>
              </div>

              {/* Datetime Picker */}
              <div className="form-row">
                <div className="form-group">
                  <label htmlFor="scheduledStartTime">
                    🕐 Start Time <span className="required">*</span>
                  </label>
                  <input
                    type="datetime-local"
                    id="scheduledStartTime"
                    name="scheduledStartTime"
                    value={formData.scheduledStartTime}
                    onChange={handleInputChange}
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="scheduledEndTime">
                    🕑 End Time
                  </label>
                  <input
                    type="datetime-local"
                    id="scheduledEndTime"
                    name="scheduledEndTime"
                    value={formData.scheduledEndTime}
                    onChange={handleInputChange}
                  />
                </div>
              </div>

              {/* Recurrence */}
              <div className="form-group">
                <label htmlFor="recurrence">🔄 Recurrence</label>
                <select
                  id="recurrence"
                  name="recurrence"
                  value={formData.recurrence}
                  onChange={handleInputChange}
                >
                  <option value="once">Once</option>
                  <option value="daily">Daily</option>
                  <option value="weekly">Weekly</option>
                  <option value="monthly">Monthly</option>
                </select>
              </div>

              {/* Reminders */}
              <div className="form-group">
                <label>🔔 Send Reminders</label>
                <div className="reminders-group">
                  {['24h', '1h', '30m'].map(time => (
                    <label key={time} className="reminder-checkbox">
                      <input
                        type="checkbox"
                        checked={formData.reminders[time]}
                        onChange={() => handleReminderToggle(time)}
                      />
                      <span>{time === '24h' ? '24 hours' : time === '1h' ? '1 hour' : '30 minutes'} before</span>
                    </label>
                  ))}
                </div>
              </div>

              {/* Submit Button */}
              <button 
                type="submit" 
                className="submit-btn"
                disabled={loading}
              >
                {loading ? 'Creating...' : '✓ Create Schedule'}
              </button>
            </form>
          </div>
        </div>

        {/* Right Panel: Dashboard */}
        <div className="dashboard-panel">
          <ScheduledStreamsDashboard 
            key={refreshKey}
            hostId={user?.id} 
            onRefresh={() => setRefreshKey(prev => prev + 1)}
          />
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import AnalyticsOverview from '../components/AnalyticsOverview';
import ViewerTimeline from '../components/ViewerTimeline';
import EngagementMetrics from '../components/EngagementMetrics';
import QualityDistribution from '../components/QualityDistribution';
import RetentionCurve from '../components/RetentionCurve';
import DemographicsPanel from '../components/DemographicsPanel';
import '../styles/StreamAnalytics.css';

export default function StreamAnalyticsPage() {
  const { streamId } = useParams();
  const [analytics, setAnalytics] = useState(null);
  const [timelineData, setTimelineData] = useState([]);
  const [engagementData, setEngagementData] = useState(null);
  const [qualityData, setQualityData] = useState(null);
  const [demographics, setDemographics] = useState(null);
  const [retentionData, setRetentionData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [timeRange, setTimeRange] = useState('24h');

  useEffect(() => {
    fetchAnalyticsData();
  }, [streamId, timeRange]);

  const fetchAnalyticsData = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const headers = { Authorization: `Bearer ${token}` };

      // Fetch all analytics data in parallel
      const [overview, timeline, engagement, quality, demographics, retention] =
        await Promise.all([
          axios.get(`/api/analytics/live/streams/${streamId}`, { headers }),
          axios.get(`/api/analytics/live/streams/${streamId}/timeline`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/engagement`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/quality`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/demographics`, {
            headers,
          }),
          axios.get(`/api/analytics/live/streams/${streamId}/retention`, {
            headers,
          }),
        ]);

      setAnalytics(overview.data);
      setTimelineData(timeline.data.timeline || []);
      setEngagementData(engagement.data);
      setQualityData(quality.data);
      setDemographics(demographics.data);
      setRetentionData(retention.data);
      setError(null);
    } catch (err) {
      console.error('Error fetching analytics:', err);
      setError('Failed to load analytics data');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="stream-analytics-page">
        <div className="analytics-loading">
          <div className="spinner"></div>
          <p>Loading analytics...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="stream-analytics-page">
        <div className="analytics-error">
          <h2>Error Loading Analytics</h2>
          <p>{error}</p>
          <button onClick={fetchAnalyticsData} className="btn-retry">
            Retry
          </button>
        </div>
      </div>
    );
  }

  if (!analytics) {
    return (
      <div className="stream-analytics-page">
        <div className="analytics-empty">
          <h2>No Analytics Available</h2>
          <p>This stream hasn't been analyzed yet.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="stream-analytics-page">
      <div className="analytics-header">
        <div className="header-content">
          <h1>Stream Analytics</h1>
          <p className="stream-title">{analytics.stream?.title}</p>
          <p className="stream-date">
            {new Date(analytics.stream?.startedAt).toLocaleDateString()} -{' '}
            {new Date(analytics.stream?.startedAt).toLocaleTimeString()}
          </p>
        </div>

        <div className="time-range-selector">
          <label htmlFor="timeRange">Time Range:</label>
          <select
            id="timeRange"
            value={timeRange}
            onChange={(e) => setTimeRange(e.target.value)}
            className="range-select"
          >
            <option value="24h">Last 24 Hours</option>
            <option value="7d">Last 7 Days</option>
            <option value="30d">Last 30 Days</option>
          </select>
        </div>
      </div>

      {/* KPI Cards */}
      <section className="analytics-section">
        <AnalyticsOverview data={analytics.overview} />
      </section>

      {/* Viewer Timeline Chart */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Viewer Timeline</h2>
          <p>Real-time viewer count throughout the stream</p>
        </div>
        <ViewerTimeline data={timelineData} />
      </section>

      {/* Quality Distribution Chart */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Quality Distribution</h2>
          <p>Percentage of viewers per quality level</p>
        </div>
        <QualityDistribution data={qualityData} />
      </section>

      {/* Engagement Metrics */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Engagement Metrics</h2>
          <p>Chat activity and viewer interaction</p>
        </div>
        <EngagementMetrics data={engagementData} />
      </section>

      {/* Retention Curve */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Retention Curve</h2>
          <p>How long viewers stayed during the stream</p>
        </div>
        <RetentionCurve data={retentionData} />
      </section>

      {/* Demographics */}
      <section className="analytics-section">
        <div className="section-header">
          <h2>Viewer Demographics</h2>
          <p>Browser, OS, and device breakdown</p>
        </div>
        <DemographicsPanel data={demographics} />
      </section>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import PromptDialog from '../components/PromptDialog';
import { useAuth } from '../context/AuthContext';
import api from '../utils/api';
import '../styles/UserAppeals.css';

const UserAppealsPage = () => {
  const { user } = useAuth();
  const [appeals, setAppeals] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedAppeal, setSelectedAppeal] = useState(null);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [promptOpen, setPromptOpen] = useState(false);
  const [promptTarget, setPromptTarget] = useState(null);

  useEffect(() => {
    fetchAppeals();
  }, []);

  const [eligible, setEligible] = useState([]);

  const fetchAppeals = async () => {
    try {
      setLoading(true);
      const response = await api.get('/moderation/appeals/my-appeals');
      setAppeals(response.data.appeals);

      // Fetch rejected items eligible for appeal
      const rej = await api.get('/moderation/my/rejected');
      setEligible(rej.data.logs || []);
    } catch (error) {
      console.error('Error fetching appeals:', error);
    } finally {
      setLoading(false);
    }
  };

  const submitAppeal = (logId) => {
    setPromptTarget(logId);
    setPromptOpen(true);
  };

  const doSubmitAppeal = async (reason) => {
    if (!reason) return;
    setPromptOpen(false);
    try {
      await api.post(`/moderation/${promptTarget}/appeal`, { reason });
      setSuccess('Appeal submitted');
      setTimeout(() => setSuccess(null), 4000);
      fetchAppeals();
    } catch (err) {
      console.error('Failed to submit appeal', err);
      setError('Failed to submit appeal');
      setTimeout(() => setError(null), 4000);
    }
  };

  if (loading) {
    return <div className="appeals-page"><div className="loading">Loading your appeals...</div></div>;
  }

  return (
    <div className="appeals-page">
      <div className="appeals-header">
        <h1>📋 My Appeals</h1>
        <p>Track and manage your content appeals</p>
      </div>
        {error && <div className="alert alert-error">{error}</div>}
        {success && <div className="alert alert-success">{success}</div>}
        <PromptDialog
          open={promptOpen}
          title="Submit Appeal"
          label="Reason"
          placeholder="Explain why this should be reinstated"
          onConfirm={doSubmitAppeal}
          onCancel={() => setPromptOpen(false)}
          confirmLabel="Submit"
          cancelLabel="Cancel"
        />

      <div className="appeals-section">
        <h2>Eligible to Appeal</h2>
        {eligible.length === 0 ? (
          <p>No recently rejected items to appeal.</p>
        ) : (
          <div className="eligible-list">
            {eligible.map(item => (
              <div key={item._id} className="eligible-card">
                <div className="eligible-meta">
                  <strong>{item.contentType.replace(/_/g, ' ')}</strong>
                  <small>Rejected: {new Date(item.rejectedAt || item.createdAt).toLocaleDateString()}</small>
                </div>
                <div className="eligible-content">{item.content.substring(0, 150)}...</div>
                <div className="eligible-actions">
                  <button onClick={() => submitAppeal(item._id)} className="btn">Submit Appeal</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="appeals-list">
        {appeals.map(appeal => (
          <div
            key={appeal._id}
            className={`appeal-card appeal-${appeal.appeal?.status || 'none'}`}
            onClick={() => setSelectedAppeal(selectedAppeal === appeal._id ? null : appeal._id)}
          >
            <div className="appeal-header">
              <div className="appeal-title">
                <span className="content-type">{appeal.contentType.replace(/_/g, ' ')}</span>
                <span className={`appeal-status status-${appeal.appeal?.status || 'none'}`}>
                  {appeal.appeal?.status ? appeal.appeal.status.toUpperCase() : 'NO APPEAL'}
                </span>
              </div>
              <small className="appeal-date">
                {new Date(appeal.createdAt).toLocaleDateString()}
              </small>
            </div>

            {selectedAppeal === appeal._id && (
              <div className="appeal-details">
                <div className="detail-section">
                  <h4>Original Content</h4>
                  <div className="content-box">
                    {appeal.content}
                  </div>
                </div>

                <div className="detail-section">
                  <h4>Rejection Reason</h4>
                  <p className="reason-text">
                    {appeal.reviewNotes || 'No specific reason provided'}
                  </p>
                </div>

                {appeal.categories && Object.keys(appeal.categories).filter(k => appeal.categories[k]).length > 0 && (
                  <div className="detail-section">
                    <h4>Violation Categories</h4>
                    <div className="categories">
                      {Object.keys(appeal.categories)
                        .filter(k => appeal.categories[k])
                        .map(category => (
                          <span key={category} className="category-badge">
                            {category.replace(/_/g, ' ')}
                          </span>
                        ))}
                    </div>
                  </div>
                )}

                {appeal.appeal?.status === 'pending' && (
                  <div className="detail-section">
                    <h4>Your Appeal</h4>
                    <p className="appeal-text">
                      <strong>Submitted:</strong> {new Date(appeal.appeal.submittedAt).toLocaleDateString()}
                    </p>
                    <p className="appeal-text">
                      <strong>Your Reason:</strong>
                    </p>
                    <div className="content-box">
                      {appeal.appeal.reason}
                    </div>
                    <p className="pending-message">
                      ⏳ Your appeal is being reviewed. You'll receive an email when a decision is made.
                    </p>
                  </div>
                )}

                {appeal.appeal?.status === 'approved' && (
                  <div className="detail-section success">
                    <h4>✅ Appeal Approved</h4>
                    <p>
                      <strong>Decision Date:</strong> {new Date(appeal.appeal.reviewedAt).toLocaleDateString()}
                    </p>
                    <p>
                      Your appeal has been approved. Your content has been restored and is now visible again.
                    </p>
                    {appeal.appeal.appealNotes && (
                      <p>
                        <strong>Admin Notes:</strong> {appeal.appeal.appealNotes}
                      </p>
                    )}
                  </div>
                )}

                {appeal.appeal?.status === 'rejected' && (
                  <div className="detail-section error">
                    <h4>❌ Appeal Rejected</h4>
                    <p>
                      <strong>Decision Date:</strong> {new Date(appeal.appeal.reviewedAt).toLocaleDateString()}
                    </p>
                    <p>
                      Your appeal has been reviewed and rejected. The original decision to reject this content stands.
                    </p>
                    {appeal.appeal.appealNotes && (
                      <p>
                        <strong>Admin Notes:</strong> {appeal.appeal.appealNotes}
                      </p>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default UserAppealsPage;

/**
 * PDF Certificate Generator using HTML2PDF library
 * Install: npm install html2pdf.js
 */

export const generateCertificatePDF = async (certificate) => {
  try {
    // Dynamically import html2pdf if not already loaded
    if (!window.html2pdf) {
      const script = document.createElement('script');
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';
      await new Promise((resolve, reject) => {
        script.onload = resolve;
        script.onerror = reject;
        document.head.appendChild(script);
      });
    }

    const {
      certificateNumber,
      studentName,
      className,
      completionDate,
      verificationCode,
      issueDate,
      template = 'classic'
    } = certificate;

    // Create certificate HTML
    const certificateHTML = `
      <div style="
        width: 100%;
        height: 100%;
        padding: 40px 60px;
        background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
        border: 4px solid #b45309;
        font-family: 'Times New Roman', serif;
        text-align: center;
        box-sizing: border-box;
      ">
        <div style="margin-bottom: 40px;">
          <div style="font-size: 32px; font-weight: bold; background: linear-gradient(135deg, #3b82f6, #8b5cf6); -webkit-background-clip: text; -webkit-text-fill-color: transparent; margin-bottom: 16px;">
            EduTalk
          </div>
          <h1 style="font-size: 48px; font-weight: bold; color: #1f2937; margin: 20px 0;">
            Certificate of Completion
          </h1>
        </div>

        <div style="margin: 40px 0; font-size: 16px; color: #4b5563; line-height: 1.8;">
          <p>This is to certify that</p>
          <h2 style="font-size: 36px; color: #1f2937; text-decoration: underline; text-decoration-style: dotted; margin: 20px 0;">
            ${studentName}
          </h2>
          <p>has successfully completed the course</p>
          <h3 style="font-size: 24px; color: #374151; font-style: italic; margin: 20px 0;">
            ${className}
          </h3>
          <p>with dedication and excellence</p>
        </div>

        <div style="display: flex; justify-content: space-around; margin: 40px 0; font-size: 14px;">
          <div>
            <p style="margin: 0 0 8px 0; color: #6b7280; font-weight: bold;">DATE OF COMPLETION</p>
            <p style="margin: 0; color: #1f2937; font-size: 16px; font-weight: bold;">
              ${new Date(completionDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
          </div>
          <div>
            <p style="margin: 0 0 8px 0; color: #6b7280; font-weight: bold;">CERTIFICATE NO.</p>
            <p style="margin: 0; color: #1f2937; font-size: 16px; font-weight: bold;">
              ${certificateNumber}
            </p>
          </div>
        </div>

        <div style="margin: 40px 0; padding: 12px; background: rgba(0, 0, 0, 0.02); border-radius: 4px;">
          <p style="margin: 0; font-size: 12px; color: #4b5563;">
            Verification Code: <code style="font-family: 'Courier New', monospace; font-weight: bold; color: #1f2937; background: rgba(0, 0, 0, 0.05); padding: 2px 6px; border-radius: 3px;">
              ${verificationCode}
            </code>
          </p>
        </div>

        <div style="margin-top: 60px;">
          <div style="height: 2px; width: 200px; margin: 0 auto 8px; background: #6b7280;"></div>
          <p style="margin: 0; font-size: 14px; font-weight: bold; color: #1f2937;">
            EduTalk Certification Authority
